--
-- TOC entry 1066 (class 1255 OID 21154)
-- Name: app_admin_gestiona_usuario(uuid); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.app_admin_gestiona_usuario(p_usuario uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $$
    SELECT app_es_admin_cualquiera()
       AND p_usuario IS DISTINCT FROM app_usuario()
       AND p_usuario <> '00000000-0000-0000-0000-000000000001'::uuid
       -- Bloquea escalación sobre cualquier rol (activo o inactivo) fuera de la jerarquía de asignación del admin actual
       AND NOT EXISTS (
           SELECT 1 FROM usuario_rol ur
            WHERE ur.usuario_id = p_usuario
              AND NOT app_puede_asignar_rol(ur.usuario_id, ur.rol_id, ur.municipio_id, ur.mercado_id)
       )
       AND (
           EXISTS (SELECT 1 FROM usuario u WHERE u.id = p_usuario AND u.creado_por = app_usuario())
        OR EXISTS (SELECT 1 FROM usuario_rol ur WHERE ur.usuario_id = p_usuario
                    AND app_puede_asignar_rol(ur.usuario_id, ur.rol_id, ur.municipio_id, ur.mercado_id))
        OR EXISTS (SELECT 1 FROM usuario u WHERE u.id = p_usuario AND u.persona_id IS NOT NULL
                    AND app_persona_en_mi_mercado(u.persona_id))
       )
$$;


ALTER FUNCTION gesta.app_admin_gestiona_usuario(p_usuario uuid) OWNER TO gesta_owner;

