--
-- TOC entry 970 (class 1255 OID 20533)
-- Name: app_concesiones_locatario_historico(); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.app_concesiones_locatario_historico() RETURNS uuid[]
    LANGUAGE sql STABLE SECURITY DEFINER PARALLEL SAFE
    SET search_path TO 'gesta', 'public'
    AS $$
    SELECT COALESCE(array_agg(DISTINCT c.id), '{}'::uuid[])
      FROM usuario u
      JOIN usuario_rol ur ON ur.usuario_id = u.id AND ur.activo
      JOIN rol r          ON r.id = ur.rol_id AND r.clave = 'LOCATARIO'
      JOIN concesion c    ON (u.persona_id = c.titular_persona_id
                           OR EXISTS (SELECT 1 FROM concesion_suplente s WHERE s.concesion_id = c.id AND s.persona_id = u.persona_id))
     WHERE u.id = app_usuario() AND u.activo
$$;


ALTER FUNCTION gesta.app_concesiones_locatario_historico() OWNER TO gesta_owner;

--
-- TOC entry 1028 (class 1255 OID 21155)
-- Name: app_doc_acceso(uuid, uuid, uuid, uuid, uuid, uuid, bigint, boolean); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.app_doc_acceso(p_local uuid, p_concesion uuid, p_traspaso uuid, p_deposito uuid, p_pago uuid, p_persona uuid, p_tarifa bigint, p_escribe boolean) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $$
DECLARE v_mercado bigint; v_mun bigint; v_tmerc bigint;
BEGIN
    IF app_usuario() IS NULL THEN RETURN false; END IF;
    IF p_persona IS NOT NULL THEN
        IF app_persona_en_mi_mercado(p_persona) THEN RETURN true; END IF;
        IF NOT p_escribe AND app_persona_en_mi_alcance_operativo(p_persona) THEN RETURN true; END IF;
        RETURN NOT p_escribe AND p_persona = app_persona_actual();
    END IF;
    IF p_tarifa IS NOT NULL THEN
        SELECT municipio_id, mercado_id INTO v_mun, v_tmerc FROM tarifa WHERE id = p_tarifa;
        IF p_escribe THEN
            RETURN (v_tmerc IS NOT NULL AND app_es_admin(v_tmerc))
                OR (v_tmerc IS NULL AND app_es_admin_municipio(v_mun));
        END IF;
        RETURN EXISTS (SELECT 1 FROM mercado m WHERE m.municipio_id = v_mun
                         AND (app_es_admin(m.id) OR app_tiene_rol('TESORERIA', m.id)));
    END IF;
    v_mercado := COALESCE(
        (SELECT mercado_id FROM local_comercial WHERE id = p_local),
        (SELECT lc.mercado_id FROM concesion c JOIN local_comercial lc ON lc.id = c.local_id WHERE c.id = p_concesion),
        (SELECT lc.mercado_id FROM traspaso t JOIN local_comercial lc ON lc.id = t.local_id WHERE t.id = p_traspaso),
        (SELECT mercado_id FROM deposito_hacienda WHERE id = p_deposito),
        (SELECT mercado_id FROM pago WHERE id = p_pago));
    IF v_mercado IS NULL THEN RETURN false; END IF;
    IF app_es_admin(v_mercado) THEN RETURN true; END IF;
    IF app_tiene_rol('TESORERIA', v_mercado) THEN
        IF NOT p_escribe THEN RETURN true; END IF;
        RETURN (p_deposito IS NOT NULL OR p_pago IS NOT NULL);
    END IF;
    IF app_tiene_rol('INSPECTOR', v_mercado) THEN
        IF NOT p_escribe AND (p_local IS NOT NULL OR p_concesion IS NOT NULL) THEN RETURN true; END IF;
        IF p_escribe AND p_local IS NOT NULL THEN RETURN true; END IF;
    END IF;
    IF p_escribe THEN RETURN false; END IF;
    IF p_local     IS NOT NULL THEN RETURN app_es_locatario_de(p_local); END IF;
    IF p_concesion IS NOT NULL THEN RETURN app_es_locatario_concesion(p_concesion); END IF;
    IF p_pago      IS NOT NULL THEN RETURN app_es_locatario_de((SELECT local_id FROM pago WHERE id = p_pago)); END IF;
    RETURN false;
END $$;


ALTER FUNCTION gesta.app_doc_acceso(p_local uuid, p_concesion uuid, p_traspaso uuid, p_deposito uuid, p_pago uuid, p_persona uuid, p_tarifa bigint, p_escribe boolean) OWNER TO gesta_owner;

