--
-- TOC entry 968 (class 1255 OID 20539)
-- Name: app_es_admin_cualquiera(); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.app_es_admin_cualquiera() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER PARALLEL SAFE
    SET search_path TO 'gesta', 'public'
    AS $$
    SELECT cardinality(app_mercados_rol('ADMINISTRADOR')) > 0
        OR EXISTS (
            SELECT 1 FROM usuario_rol ur
            JOIN rol r ON r.id = ur.rol_id
            JOIN usuario u ON u.id = ur.usuario_id
            WHERE ur.usuario_id = app_usuario() AND ur.activo AND u.activo AND r.clave = 'ADMINISTRADOR'
        )
$$;


