--
-- TOC entry 544 (class 1255 OID 40965)
-- Name: app_es_auth(); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.app_es_auth() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER PARALLEL SAFE
    SET search_path TO 'gesta', 'public'
    AS $$
    SELECT EXISTS (
        SELECT 1
          FROM pg_roles r
         WHERE r.rolname = session_user
           AND (
               r.rolsuper
               OR r.rolname IN ('postgres', 'gesta_owner')
               OR (
                   pg_has_role(session_user, 'gesta_auth', 'USAGE')
                   AND NOT pg_has_role(session_user, 'gesta_app', 'USAGE')
               )
           )
    )
$$;


ALTER FUNCTION gesta.app_es_auth() OWNER TO gesta_owner;

