--
-- TOC entry 978 (class 1255 OID 21152)
-- Name: app_gestiona_asignacion(uuid, bigint, bigint); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.app_gestiona_asignacion(p_usuario uuid, p_municipio bigint, p_mercado bigint) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $$
BEGIN
    IF app_usuario() IS NULL THEN RETURN false; END IF;
    IF p_municipio IS NOT NULL THEN RETURN app_es_admin_municipio(p_municipio); END IF;
    IF p_mercado   IS NOT NULL THEN RETURN app_es_admin(p_mercado); END IF;
    RETURN EXISTS (SELECT 1 FROM usuario u WHERE u.id = p_usuario AND u.persona_id IS NOT NULL
                                              AND app_persona_en_mi_mercado(u.persona_id));
END $$;


ALTER FUNCTION gesta.app_gestiona_asignacion(p_usuario uuid, p_municipio bigint, p_mercado bigint) OWNER TO gesta_owner;

--
-- TOC entry 479 (class 1255 OID 20532)
-- Name: app_locales_locatario_activo(); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.app_locales_locatario_activo() RETURNS uuid[]
    LANGUAGE sql STABLE SECURITY DEFINER PARALLEL SAFE
    SET search_path TO 'gesta', 'public'
    AS $$
    SELECT COALESCE(array_agg(DISTINCT c.local_id), '{}'::uuid[])
      FROM gesta.usuario u
      JOIN gesta.usuario_rol ur ON ur.usuario_id = u.id AND ur.activo
      JOIN gesta.rol r          ON r.id = ur.rol_id AND r.clave = 'LOCATARIO'
      JOIN gesta.concesion c    ON (u.persona_id = c.titular_persona_id
                                 OR EXISTS (SELECT 1 FROM gesta.concesion_suplente s
                                             WHERE s.concesion_id = c.id AND s.persona_id = u.persona_id))
     WHERE u.id = gesta.app_usuario()
       AND u.activo
       AND c.estado = ANY (gesta.fn_estados_concesion_proceso('OCUPACION_ACTIVA'))
$$;


ALTER FUNCTION gesta.app_locales_locatario_activo() OWNER TO gesta_owner;

--
-- TOC entry 1198 (class 1255 OID 20531)
-- Name: app_mercados_rol(text); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.app_mercados_rol(p_rol text) RETURNS bigint[]
    LANGUAGE sql STABLE SECURITY DEFINER PARALLEL SAFE
    SET search_path TO 'gesta', 'public'
    AS $$
    SELECT COALESCE(array_agg(DISTINCT m.id), '{}'::bigint[])
      FROM usuario_rol ur
      JOIN rol r     ON r.id = ur.rol_id
      JOIN usuario u ON u.id = ur.usuario_id
      JOIN mercado m ON (ur.mercado_id = m.id OR ur.municipio_id = m.municipio_id)
     WHERE ur.usuario_id = app_usuario() AND ur.activo AND u.activo AND r.clave = p_rol
$$;


ALTER FUNCTION gesta.app_mercados_rol(p_rol text) OWNER TO gesta_owner;

