--
-- TOC entry 335 (class 1255 OID 20541)
-- Name: app_opera_en_mercado(bigint); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.app_opera_en_mercado(p_mercado bigint) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER PARALLEL SAFE
    SET search_path TO 'gesta', 'public'
    AS $$
    SELECT p_mercado = ANY (app_mercados_rol('ADMINISTRADOR'))
        OR p_mercado = ANY (app_mercados_rol('TESORERIA'))
        OR p_mercado = ANY (app_mercados_rol('INSPECTOR'))
$$;


ALTER FUNCTION gesta.app_opera_en_mercado(p_mercado bigint) OWNER TO gesta_owner;

--
-- TOC entry 856 (class 1255 OID 41349)
