--

CREATE FUNCTION gesta.app_pago_en_cargo_de_locatario(p_pago uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER PARALLEL SAFE
    SET search_path TO 'gesta', 'public'
    AS $$
    SELECT EXISTS (
        SELECT 1
          FROM gesta.pago_detalle pd
          JOIN gesta.cargo cg ON cg.id = pd.cargo_id
         WHERE pd.pago_id = p_pago
           AND gesta.app_es_locatario_concesion(cg.concesion_id)
    )
$$;


