--
-- TOC entry 561 (class 1255 OID 24693)
-- Name: app_persona_en_mi_alcance_operativo(uuid); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.app_persona_en_mi_alcance_operativo(p_persona uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER PARALLEL SAFE
    SET search_path TO 'gesta', 'public'
    AS $$
    SELECT EXISTS (
        SELECT 1 FROM persona_mercado pm
         WHERE pm.persona_id = p_persona
           AND app_opera_en_mercado(pm.mercado_id)
    ) OR EXISTS (
        SELECT 1 FROM concesion c
         WHERE (c.titular_persona_id = p_persona
                OR c.ocupante_persona_id = p_persona
                OR EXISTS (SELECT 1 FROM concesion_suplente cs
                            WHERE cs.concesion_id = c.id AND cs.persona_id = p_persona))
           AND app_opera_en_local(c.local_id)
    )
$$;


ALTER FUNCTION gesta.app_persona_en_mi_alcance_operativo(p_persona uuid) OWNER TO gesta_owner;

--
-- TOC entry 404 (class 1255 OID 20538)
