CREATE FUNCTION gesta.app_persona_en_mi_mercado(p_persona uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER PARALLEL SAFE
    SET search_path TO 'gesta', 'public'
    AS $$
    SELECT EXISTS (SELECT 1 FROM persona_mercado pm WHERE pm.persona_id = p_persona AND app_es_admin(pm.mercado_id))
$$;


ALTER FUNCTION gesta.app_persona_en_mi_mercado(p_persona uuid) OWNER TO gesta_owner;

--
-- TOC entry 1288 (class 1255 OID 21153)
-- Name: app_puede_asignar_rol(uuid, smallint, bigint, bigint); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.app_puede_asignar_rol(p_usuario uuid, p_rol smallint, p_municipio bigint, p_mercado bigint) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $$
DECLARE v_clave text; v_mun bigint;
BEGIN
    IF app_usuario() IS NULL OR p_usuario IS NULL OR p_usuario = app_usuario() THEN RETURN false; END IF;
    SELECT clave INTO v_clave FROM rol WHERE id = p_rol;
    IF v_clave IS NULL THEN RETURN false; END IF;
    IF p_municipio IS NOT NULL THEN RETURN app_es_admin_municipio(p_municipio); END IF;
    IF p_mercado IS NOT NULL THEN
        IF v_clave = 'INSPECTOR' THEN RETURN app_es_admin(p_mercado); END IF;
        IF v_clave IN ('ADMINISTRADOR','TESORERIA') THEN
            SELECT municipio_id INTO v_mun FROM mercado WHERE id = p_mercado;
            RETURN app_es_admin_municipio(v_mun);
        END IF;
        RETURN false;
    END IF;
    IF v_clave = 'LOCATARIO' THEN
        RETURN EXISTS (SELECT 1 FROM usuario u WHERE u.id = p_usuario AND u.persona_id IS NOT NULL
                                                  AND app_persona_en_mi_mercado(u.persona_id));
    END IF;
    RETURN false;
END $$;


ALTER FUNCTION gesta.app_puede_asignar_rol(p_usuario uuid, p_rol smallint, p_municipio bigint, p_mercado bigint) OWNER TO gesta_owner;

