--
-- TOC entry 812 (class 1255 OID 19973)
-- Name: app_usuario(); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.app_usuario() RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER PARALLEL SAFE
    SET search_path TO 'gesta', 'public'
    AS $_$
DECLARE
    v_raw text := NULLIF(btrim(current_setting('app.usuario_id', true)), '');
    v_sig text := NULLIF(btrim(current_setting('app.usuario_sig', true)), '');
    v_uid uuid;
    v_sec bytea;
    v_hmac text;
BEGIN
    -- 1. Si no se definió app.usuario_id, solo el rol gesta_batch recibe identidad de sistema
    IF v_raw IS NULL THEN
        IF gesta.app_es_sistema() THEN
            RETURN '00000000-0000-0000-0000-000000000001'::uuid;
        END IF;
        RETURN NULL;
    END IF;

    v_uid := v_raw::uuid;

    -- 2. Bloqueo estricto del UUID de sistema para cualquier rol distinto de gesta_batch
    IF v_uid = '00000000-0000-0000-0000-000000000001'::uuid THEN
        IF NOT gesta.app_es_sistema() THEN
            RAISE EXCEPTION 'Violación de seguridad: el rol % no está autorizado para operar como usuario de sistema', session_user;
        END IF;
        RETURN v_uid;
    END IF;

    -- 3. Verificación obligatoria (fail-closed) de firma HMAC-SHA256 para toda sesión no-sistema
    IF NOT gesta.app_es_sistema() THEN
        SELECT s.secreto_hmac
          INTO v_sec
          FROM gesta.secreto_firma_sesion s
         WHERE s.id = true
           AND s.exigir_firma = true;

        IF NOT FOUND OR v_sec IS NULL OR octet_length(v_sec) < 32 THEN
            RAISE EXCEPTION 'Configuración de seguridad incompleta: el secreto HMAC de sesión no ha sido inicializado (ejecute gesta.fn_configurar_secreto_hmac)';
        END IF;

        IF v_sig IS NULL OR v_sig !~ '^[0-9a-fA-F]{64}$' THEN
            RAISE EXCEPTION 'Violación de seguridad: falta firma criptográfica de sesión válida (app.usuario_sig)';
        END IF;

        -- Conversión explícita del mensaje a bytea (UTF8) para invocar public.hmac(bytea, bytea, text)
        v_hmac := encode(
            public.hmac(
                convert_to(v_uid::text || ':' || txid_current()::text, 'UTF8'),
                v_sec,
                'sha256'
            ),
            'hex'
        );

        -- Comparación resistente a ataques de tiempo mediante digest SHA-256 de ambas cadenas hexadecimales
        IF public.digest(convert_to(lower(v_sig), 'UTF8'), 'sha256')
           IS DISTINCT FROM public.digest(convert_to(v_hmac, 'UTF8'), 'sha256') THEN
            RAISE EXCEPTION 'Violación de seguridad: firma app.usuario_sig inválida para el usuario % en la transacción actual', v_uid;
        END IF;
    END IF;

    RETURN v_uid;
END $_$;


ALTER FUNCTION gesta.app_usuario() OWNER TO gesta_owner;

