--
-- TOC entry 249 (class 1259 OID 20316)
-- Name: local_comercial; Type: TABLE; Schema: gesta; Owner: gesta_owner
--

CREATE TABLE gesta.local_comercial (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    mercado_id bigint NOT NULL,
    zona_id bigint,
    numero_local character varying(20) NOT NULL,
    nombre_comercial character varying(150),
    folio_tarjeton character varying(30),
    tipo_espacio gesta.tipo_espacio DEFAULT 'FIJO'::gesta.tipo_espacio NOT NULL,
    estatus gesta.estatus_local DEFAULT 'OCUPADO'::gesta.estatus_local NOT NULL,
    giro_observado_id bigint,
    geom public.geometry(Polygon,4326),
    area_calculada_m2 numeric(10,2),
    perimetro_m numeric(10,2),
    centroide public.geometry(Point,4326),
    area_oficial_m2 numeric(10,2),
    area_oficial_motivo text,
    metros_lineales numeric(10,2),
    notas text,
    creado_en timestamp with time zone DEFAULT now() NOT NULL,
    actualizado_en timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ck_local_area_motivo CHECK (((area_oficial_m2 IS NULL) OR ((area_oficial_motivo IS NOT NULL) AND (length(btrim(area_oficial_motivo)) > 0)))),
    CONSTRAINT ck_local_area_oficial CHECK (((area_oficial_m2 IS NULL) OR (area_oficial_m2 > (0)::numeric))),
    CONSTRAINT ck_local_geom_valida CHECK (((geom IS NULL) OR public.st_isvalid(geom))),
    CONSTRAINT local_comercial_metros_lineales_check CHECK (((metros_lineales IS NULL) OR (metros_lineales > (0)::numeric)))
);

ALTER TABLE ONLY gesta.local_comercial FORCE ROW LEVEL SECURITY;


