--
-- TOC entry 736 (class 1255 OID 21091)
-- Name: fn_ajustar_cargo(uuid, numeric, text); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.fn_ajustar_cargo(p_cargo uuid, p_nuevo_monto numeric, p_motivo text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $_$
DECLARE
    v gesta.cargo%ROWTYPE;
    v_mercado bigint;
    v_mun bigint;
    v_nuevo numeric(12,2);
    v_pagado_bruto numeric(12,2);
    v_exceso numeric(12,2);
    v_usr uuid := gesta.app_usuario();
    r_rec record;
    rm record;
    v_pagado_origen_a_fecha numeric(12,2);
    v_insoluto_ant numeric(12,2);
    v_insoluto_nvo numeric(12,2);
    v_rec_prev_insoluto numeric(12,2) := 0;
    v_rec_acum_nvo numeric(12,2) := 0;
    v_tope_rec numeric(12,2);
    v_nuevo_rec numeric(12,2);
    v_pagado_rec_bruto numeric(12,2);
    v_exceso_rec numeric(12,2);
BEGIN
    IF v_usr IS NULL THEN
        RAISE EXCEPTION 'Se requiere un usuario identificado';
    END IF;
    IF p_motivo IS NULL OR btrim(p_motivo) = '' THEN
        RAISE EXCEPTION 'El motivo del ajuste es obligatorio';
    END IF;
    IF p_nuevo_monto IS NULL OR p_nuevo_monto <= 0 THEN
        RAISE EXCEPTION 'El nuevo monto debe ser mayor a cero (para anular use fn_cancelar_cargo)';
    END IF;

    v_nuevo := ROUND(p_nuevo_monto, 2);
    SELECT * INTO v FROM gesta.cargo WHERE id = p_cargo FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'El cargo % no existe', p_cargo;
    END IF;

    SELECT lc.mercado_id, m.municipio_id
      INTO v_mercado, v_mun
      FROM gesta.local_comercial lc
      JOIN gesta.mercado m ON m.id = lc.mercado_id
     WHERE lc.id = v.local_id;

    IF NOT gesta.app_autoriza_ajuste_fiscal(v_mercado) THEN
        RAISE EXCEPTION 'RN-FIS-05 / CU-20: No cuenta con autorización de Tesorería o Administración Municipal para ajustar cargos';
    END IF;
    IF v.estado = 'CANCELADO' THEN
        RAISE EXCEPTION 'No se ajusta un cargo cancelado';
    END IF;
    IF EXISTS (
        SELECT 1
          FROM gesta.pago_detalle d
          JOIN gesta.pago p ON p.id = d.pago_id
         WHERE d.cargo_id = v.id
           AND p.cobrador_id = v_usr
           AND v_usr <> '00000000-0000-0000-0000-000000000001'::uuid
    ) THEN
        RAISE EXCEPTION 'RN-FIS-05 / CU-20: Segregación de funciones: no puede ajustar un cargo con cobros realizados por usted mismo';
    END IF;

    SELECT COALESCE(SUM(d.monto_aplicado), 0) INTO v_pagado_bruto
      FROM gesta.pago_detalle d
      JOIN gesta.pago p ON p.id = d.pago_id
     WHERE d.cargo_id = v.id AND p.estado = 'VIGENTE';

    INSERT INTO gesta.cargo_ajuste (cargo_id, local_id, mercado_id, tipo, monto_anterior, monto_nuevo, estado_anterior, motivo, usuario_id)
    VALUES (v.id, v.local_id, v_mercado, 'AJUSTE', v.monto_total, v_nuevo, v.estado, btrim(p_motivo), v_usr);

    PERFORM set_config('gesta.ajuste_autorizado', v.id::text, true);

    UPDATE gesta.cargo
       SET monto_total = v_nuevo,
           monto_pagado = LEAST(v_pagado_bruto, v_nuevo),
           estado = CASE WHEN v_pagado_bruto >= v_nuevo THEN 'PAGADO'::gesta.estado_cargo
                         WHEN v_pagado_bruto = 0 THEN 'PENDIENTE'::gesta.estado_cargo
                         ELSE 'PARCIAL'::gesta.estado_cargo END
     WHERE id = v.id;

    PERFORM set_config('gesta.ajuste_autorizado', '', true);

    IF v_nuevo < v_pagado_bruto THEN
        v_exceso := v_pagado_bruto - v_nuevo;
        UPDATE gesta.pago
           SET requiere_revision = true,
               motivo_revision = COALESCE(motivo_revision || '; ', '')
                                 || 'Excedente a favor ($' || v_exceso || ') generado por ajuste a la baja del cargo ' || v.id
         WHERE id IN (SELECT pd.pago_id FROM gesta.pago_detalle pd WHERE pd.cargo_id = v.id)
           AND estado = 'VIGENTE';
    END IF;

    -- Si el cargo origen quedó liquidado con el nuevo monto, anular recargos posteriores a la fecha de liquidación
    IF v_pagado_bruto >= v_nuevo THEN
        PERFORM gesta.fn_anular_recargos_indebidos(v.id, v_usr);
    END IF;

    -- Conciliación automática de recargos hijos activos vinculados al cargo ajustado
    IF v.concepto IN ('DERECHO_PISO', 'PENALIZACION') AND v_nuevo <> v.monto_total THEN
        FOR r_rec IN
            SELECT id, periodo_inicio, monto_total, monto_pagado, estado
              FROM gesta.cargo
             WHERE cargo_origen_id = v.id
               AND concepto = 'RECARGO'
               AND estado <> 'CANCELADO'
             ORDER BY periodo_inicio ASC, generado_en ASC
               FOR UPDATE
        LOOP
            SELECT COALESCE(SUM(d.monto_aplicado), 0)
              INTO v_pagado_origen_a_fecha
              FROM gesta.pago_detalle d
              JOIN gesta.pago p ON p.id = d.pago_id
             WHERE d.cargo_id = v.id
               AND p.estado = 'VIGENTE'
               AND gesta.fn_fecha_local(v_mercado, p.fecha_pago) <= r_rec.periodo_inicio;

            v_insoluto_ant := GREATEST(v.monto_total - v_pagado_origen_a_fecha, 0);
            v_insoluto_nvo := GREATEST(v_nuevo - v_pagado_origen_a_fecha, 0);

            SELECT r.porcentaje_recargo, r.tipo_calculo, r.tope_maximo_pct
              INTO rm
              FROM gesta.regla_mora r
             WHERE r.activo
               AND r.municipio_id = v_mun
               AND (r.mercado_id IS NULL OR r.mercado_id = v_mercado)
               AND r_rec.periodo_inicio >= r.vigente_desde
               AND r_rec.periodo_inicio <= COALESCE(r.vigente_hasta, 'infinity'::date)
             ORDER BY (r.mercado_id IS NOT NULL) DESC, r.vigente_desde DESC, r.id DESC
             LIMIT 1;

            IF v_insoluto_nvo <= 0 THEN
                v_nuevo_rec := 0;
            ELSIF FOUND THEN
                v_tope_rec := ROUND(v_nuevo * rm.tope_maximo_pct / 100.0, 2);
                v_nuevo_rec := ROUND(
                    (v_insoluto_nvo + CASE WHEN rm.tipo_calculo = 'COMPUESTO' THEN v_rec_prev_insoluto ELSE 0 END)
                    * rm.porcentaje_recargo / 100.0,
                    2
                );
                v_nuevo_rec := LEAST(v_nuevo_rec, GREATEST(v_tope_rec - v_rec_acum_nvo, 0));
            ELSIF v_insoluto_ant > 0 THEN
                v_nuevo_rec := ROUND(r_rec.monto_total * (v_insoluto_nvo / v_insoluto_ant), 2);
            ELSE
                v_nuevo_rec := 0;
            END IF;

            SELECT COALESCE(SUM(d.monto_aplicado), 0)
              INTO v_pagado_rec_bruto
              FROM gesta.pago_detalle d
              JOIN gesta.pago p ON p.id = d.pago_id
             WHERE d.cargo_id = r_rec.id
               AND p.estado = 'VIGENTE';

            IF v_nuevo_rec <= 0 THEN
                INSERT INTO gesta.cargo_ajuste (
                    cargo_id, local_id, mercado_id, tipo, monto_anterior, monto_nuevo, estado_anterior, motivo, usuario_id
                )
                VALUES (
                    r_rec.id, v.local_id, v_mercado, 'CANCELACION', r_rec.monto_total, NULL, r_rec.estado,
                    'Conciliación accesoria por ajuste del cargo origen ' || v.id || ': ' || btrim(p_motivo), v_usr
                );

                PERFORM set_config('gesta.ajuste_autorizado', r_rec.id::text, true);
                UPDATE gesta.cargo
                   SET estado = 'CANCELADO',
                       motivo_cancelacion = 'Conciliación accesoria por ajuste del cargo origen ' || v.id,
                       cancelado_por = v_usr,
                       cancelado_en = now()
                 WHERE id = r_rec.id;
                PERFORM set_config('gesta.ajuste_autorizado', '', true);

                IF v_pagado_rec_bruto > 0 THEN
                    UPDATE gesta.pago
                       SET requiere_revision = true,
                           motivo_revision = COALESCE(motivo_revision || '; ', '')
                                             || 'Recargo ' || r_rec.id || ' cancelado por ajuste a la baja del cargo origen (saldo a favor)'
                     WHERE id IN (SELECT pd.pago_id FROM gesta.pago_detalle pd WHERE pd.cargo_id = r_rec.id)
                       AND estado = 'VIGENTE';
                END IF;
            ELSIF v_nuevo_rec <> r_rec.monto_total THEN
                INSERT INTO gesta.cargo_ajuste (
                    cargo_id, local_id, mercado_id, tipo, monto_anterior, monto_nuevo, estado_anterior, motivo, usuario_id
                )
                VALUES (
                    r_rec.id, v.local_id, v_mercado, 'AJUSTE', r_rec.monto_total, v_nuevo_rec, r_rec.estado,
                    'Conciliación proporcional de recargo por ajuste del cargo origen ' || v.id || ': ' || btrim(p_motivo), v_usr
                );

                PERFORM set_config('gesta.ajuste_autorizado', r_rec.id::text, true);
                UPDATE gesta.cargo
                   SET monto_total = v_nuevo_rec,
                       monto_pagado = LEAST(v_pagado_rec_bruto, v_nuevo_rec),
                       estado = CASE WHEN v_pagado_rec_bruto >= v_nuevo_rec THEN 'PAGADO'::gesta.estado_cargo
                                     WHEN v_pagado_rec_bruto = 0 THEN 'PENDIENTE'::gesta.estado_cargo
                                     ELSE 'PARCIAL'::gesta.estado_cargo END
                 WHERE id = r_rec.id;
                PERFORM set_config('gesta.ajuste_autorizado', '', true);

                IF v_nuevo_rec < v_pagado_rec_bruto THEN
                    v_exceso_rec := v_pagado_rec_bruto - v_nuevo_rec;
                    UPDATE gesta.pago
                       SET requiere_revision = true,
                           motivo_revision = COALESCE(motivo_revision || '; ', '')
                                             || 'Excedente a favor ($' || v_exceso_rec || ') en recargo ' || r_rec.id
                                             || ' por ajuste del cargo origen ' || v.id
                     WHERE id IN (SELECT pd.pago_id FROM gesta.pago_detalle pd WHERE pd.cargo_id = r_rec.id)
                       AND estado = 'VIGENTE';
                END IF;

                v_rec_acum_nvo := v_rec_acum_nvo + v_nuevo_rec;
                v_rec_prev_insoluto := v_rec_prev_insoluto + GREATEST(v_nuevo_rec - LEAST(v_pagado_rec_bruto, v_nuevo_rec), 0);
            ELSE
                v_rec_acum_nvo := v_rec_acum_nvo + r_rec.monto_total;
                v_rec_prev_insoluto := v_rec_prev_insoluto + GREATEST(r_rec.monto_total - r_rec.monto_pagado, 0);
            END IF;
        END LOOP;
    END IF;
END $_$;


ALTER FUNCTION gesta.fn_ajustar_cargo(p_cargo uuid, p_nuevo_monto numeric, p_motivo text) OWNER TO gesta_owner;

--
-- TOC entry 550 (class 1255 OID 21084)
-- Name: fn_anular_recargos_indebidos(uuid, uuid); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.fn_anular_recargos_indebidos(p_cargo uuid, p_usuario uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $$
DECLARE
    v gesta.cargo%ROWTYPE; v_mercado bigint; v_pagado numeric; v_ult date;
    v_gracia smallint; v_n integer := 0; r record; v_usr uuid; v_limite date;
BEGIN
    v_usr := COALESCE(p_usuario, app_usuario(), '00000000-0000-0000-0000-000000000001'::uuid);
    SELECT * INTO v FROM cargo WHERE id = p_cargo;
    IF NOT FOUND OR v.concepto NOT IN ('DERECHO_PISO','PENALIZACION') OR v.estado = 'CANCELADO' THEN RETURN 0; END IF;
    SELECT mercado_id INTO v_mercado FROM local_comercial WHERE id = v.local_id;

    SELECT COALESCE(SUM(d.monto_aplicado), 0), MAX(fn_fecha_local(v_mercado, p.fecha_pago)) INTO v_pagado, v_ult
      FROM pago_detalle d JOIN pago p ON p.id = d.pago_id
     WHERE d.cargo_id = p_cargo AND p.estado = 'VIGENTE';
    IF v_pagado < v.monto_total OR v_ult IS NULL THEN RETURN 0; END IF;

    SELECT rm.dias_gracia INTO v_gracia FROM mercado m JOIN LATERAL (
        SELECT rr.dias_gracia FROM regla_mora rr
         WHERE rr.activo AND rr.municipio_id = m.municipio_id
           AND (rr.mercado_id IS NULL OR rr.mercado_id = m.id)
           AND v_ult >= rr.vigente_desde AND v_ult <= COALESCE(rr.vigente_hasta, 'infinity'::date)
         ORDER BY (rr.mercado_id IS NOT NULL) DESC, rr.vigente_desde DESC, rr.id DESC LIMIT 1) rm ON true
     WHERE m.id = v_mercado;

    v_limite := CASE WHEN v.periodicidad = 'MENSUAL' AND v.concepto IN ('DERECHO_PISO', 'PENALIZACION')
                     THEN v.periodo_inicio + GREATEST(COALESCE(v_gracia, 0) - 1, 0)
                     ELSE v.periodo_fin + COALESCE(v_gracia, 0)
                END;

    -- Anula: (a) todos los recargos si se pagó dentro del plazo legal (v_ult <= v_limite), o
    --        (b) los recargos de meses posteriores a la fecha real de liquidación (r.periodo_inicio > v_ult)
    FOR r IN SELECT id, estado, monto_total, periodo_inicio FROM cargo
              WHERE cargo_origen_id = p_cargo AND concepto = 'RECARGO' AND estado <> 'CANCELADO'
                AND (v_ult <= v_limite OR periodo_inicio > v_ult)
                FOR UPDATE LOOP
        IF r.estado = 'PENDIENTE' THEN
            INSERT INTO cargo_ajuste (cargo_id, local_id, mercado_id, tipo, monto_anterior, monto_nuevo, estado_anterior, motivo, usuario_id)
            VALUES (r.id, v.local_id, v_mercado, 'CANCELACION', r.monto_total, NULL, r.estado,
                    'RN-FIS-04: recargo improcedente; el cargo origen quedó liquidado el ' || v_ult || ' y sincronizó después', v_usr);
            PERFORM set_config('gesta.ajuste_autorizado', r.id::text, true);
            UPDATE cargo SET estado = 'CANCELADO',
                   motivo_cancelacion = 'RN-FIS-04: recargo improcedente; el cargo origen quedó liquidado el ' || v_ult || ' y sincronizó después',
                   cancelado_por = v_usr, cancelado_en = now()
             WHERE id = r.id;
            PERFORM set_config('gesta.ajuste_autorizado', '', true);
            v_n := v_n + 1;
        ELSE
            UPDATE pago SET requiere_revision = true,
                   motivo_revision = COALESCE(motivo_revision || '; ', '') || 'RN-FIS-04: recargo improcedente ya pagado (total o parcial); revisar devolución'
             WHERE id IN (SELECT d.pago_id FROM pago_detalle d WHERE d.cargo_id IN (p_cargo, r.id));
        END IF;
    END LOOP;
    RETURN v_n;
END $$;


ALTER FUNCTION gesta.fn_anular_recargos_indebidos(p_cargo uuid, p_usuario uuid) OWNER TO gesta_owner;

--
-- TOC entry 422 (class 1255 OID 21085)
-- Name: fn_aplicar_pago(uuid, uuid, numeric); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.fn_aplicar_pago(p_pago uuid, p_cargo uuid, p_monto numeric DEFAULT NULL::numeric) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $$
DECLARE
    v_usr uuid := gesta.app_usuario();
    v_pago gesta.pago%ROWTYPE;
    v_cargo gesta.cargo%ROWTYPE;
    v_est gesta.estatus_local;
    v_libre numeric;
    v_saldo numeric;
    v_aplicar numeric;
    v_motivo text;
BEGIN
    SELECT * INTO v_pago FROM gesta.pago WHERE id = p_pago FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Pago % no existe', p_pago; END IF;

    IF v_usr IS NULL
       OR NOT (
           v_usr = '00000000-0000-0000-0000-000000000001'::uuid
           OR gesta.app_es_admin(v_pago.mercado_id)
           OR gesta.app_tiene_rol('TESORERIA', v_pago.mercado_id)
           OR v_pago.cobrador_id = v_usr
       ) THEN
        RAISE EXCEPTION 'No tiene permiso para aplicar el pago %', p_pago;
    END IF;

    IF v_pago.estado = 'CANCELADO' THEN RETURN 'PAGO_CANCELADO'; END IF;

    IF (v_pago.corte_caja_id IS NOT NULL OR v_pago.deposito_id IS NOT NULL)
       AND current_setting('gesta.aplicacion_post_corte_autorizada', true) IS DISTINCT FROM p_pago::text
       AND NOT gesta.app_autoriza_ajuste_fiscal(v_pago.mercado_id) THEN
        RAISE EXCEPTION 'RN-FIS-05: El pago % ya está liquidado en corte de caja o depositado; requiere autorización de Tesorería/Administración Municipal o flujo de compensación de saldo a favor para aplicarse', p_pago;
    END IF;

    SELECT * INTO v_cargo FROM gesta.cargo WHERE id = p_cargo FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Cargo % no existe', p_cargo; END IF;
    SELECT estatus INTO v_est FROM gesta.local_comercial WHERE id = v_pago.local_id;

    v_motivo := CASE WHEN v_cargo.estado = 'CANCELADO'        THEN 'Pago para un cargo cancelado'
                     WHEN v_est = 'BAJA'                      THEN 'Pago para un local dado de baja'
                     WHEN v_cargo.local_id <> v_pago.local_id THEN 'El cargo es de otro local' END;
    IF v_motivo IS NOT NULL THEN
        UPDATE gesta.pago SET requiere_revision = true,
               motivo_revision = COALESCE(motivo_revision || '; ', '') || v_motivo
         WHERE id = p_pago;
        RETURN 'REVISION';
    END IF;

    WITH cargos_del_pago AS (
        SELECT pd0.cargo_id FROM gesta.pago_detalle pd0 WHERE pd0.pago_id = p_pago
    ), det_efectivo AS (
        SELECT pd.pago_id,
               pd.cargo_id,
               CASE
                   WHEN cg.estado = 'CANCELADO'::gesta.estado_cargo THEN 0::numeric
                   ELSE GREATEST(
                       LEAST(
                           pd.monto_aplicado,
                           cg.monto_total - COALESCE(
                               SUM(pd.monto_aplicado) OVER (
                                   PARTITION BY pd.cargo_id
                                   ORDER BY p.fecha_pago ASC, pd.pago_id ASC
                                   ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING
                               ), 0::numeric
                           )
                       ), 0::numeric
                   )
               END AS aplicado_efectivo
          FROM gesta.pago_detalle pd
          JOIN cargos_del_pago cp ON cp.cargo_id = pd.cargo_id
          JOIN gesta.cargo cg     ON cg.id = pd.cargo_id
          JOIN gesta.pago p       ON p.id = pd.pago_id
         WHERE p.estado = 'VIGENTE'::gesta.estado_pago
    )
    SELECT v_pago.monto - COALESCE(SUM(aplicado_efectivo), 0)
      INTO v_libre
      FROM det_efectivo
     WHERE pago_id = p_pago;

    IF v_libre <= 0 THEN RETURN 'SIN_SALDO_EN_PAGO'; END IF;
    v_saldo := GREATEST(v_cargo.monto_total - v_cargo.monto_pagado, 0);
    v_aplicar := LEAST(COALESCE(p_monto, v_libre), v_libre, v_saldo);

    IF v_aplicar <= 0 THEN
        UPDATE gesta.pago SET requiere_revision = true,
               motivo_revision = COALESCE(motivo_revision || '; ', '') || 'Cargo ya cubierto: pago sin aplicar (saldo a favor)'
         WHERE id = p_pago;
        RETURN 'REVISION';
    END IF;

    PERFORM set_config('gesta.aplicacion_post_corte_autorizada', p_pago::text, true);

    INSERT INTO gesta.pago_detalle (pago_id, cargo_id, monto_aplicado)
    VALUES (p_pago, p_cargo, v_aplicar)
    ON CONFLICT (pago_id, cargo_id) DO UPDATE
        SET monto_aplicado = gesta.pago_detalle.monto_aplicado + EXCLUDED.monto_aplicado;

    PERFORM set_config('gesta.aplicacion_post_corte_autorizada', '', true);

    PERFORM gesta.fn_anular_recargos_indebidos(p_cargo, v_usr);

    IF COALESCE(p_monto, v_libre) > v_aplicar THEN
        UPDATE gesta.pago SET requiere_revision = true,
               motivo_revision = COALESCE(motivo_revision || '; ', '') || 'Excedente sin aplicar (saldo a favor)'
         WHERE id = p_pago;
        RETURN 'APLICADO_PARCIAL';
    END IF;
    RETURN 'APLICADO';
END $$;


ALTER FUNCTION gesta.fn_aplicar_pago(p_pago uuid, p_cargo uuid, p_monto numeric) OWNER TO gesta_owner;

--
-- TOC entry 1032 (class 1255 OID 24601)
-- Name: fn_aplicar_penalizacion_morosidad_diaria(uuid, date); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.fn_aplicar_penalizacion_morosidad_diaria(p_local uuid, p_fecha date DEFAULT NULL::date) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $$
DECLARE
    v_usr uuid := gesta.app_usuario();
    v_mercado bigint;
    v_modo_omisiones varchar(15);
    v_estatus gesta.estatus_local;
    v_hoy date;
    v_ini_mes date;
    v_fin_mes date;
    v_omisiones_totales integer := 0;
    v_max_racha integer := 0;
    v_omisiones_eval integer := 0;
    v_pagado_mes numeric(12,2);
    v_concesion uuid;
    v_conc_ini date;
    v_conc_fin date;
    q record;
    tf_row gesta.tarifa%ROWTYPE;
    v_dias_mes integer;
    v_dias_activos integer;
    v_monto_mensual numeric(12,2);
    v_saldo_exigible numeric(12,2);
    r_pend record;
    r_rec record;
    v_cargo_penal uuid;
    v_ini_eval date;
    v_fin_eval date;
    v_lim_omision date;
    v_factor_uma numeric(12,4);
    v_proporcion_mes numeric(12,6);
BEGIN
    IF v_usr IS NULL THEN
        RAISE EXCEPTION 'Se requiere un usuario identificado';
    END IF;

    SELECT lc.mercado_id, lc.estatus, m.modo_omisiones_penalizacion
      INTO v_mercado, v_estatus, v_modo_omisiones
      FROM gesta.local_comercial lc
      JOIN gesta.mercado m ON m.id = lc.mercado_id
     WHERE lc.id = p_local;

    IF v_mercado IS NULL THEN
        RAISE EXCEPTION 'El local % no existe', p_local;
    END IF;
    IF NOT gesta.app_opera_en_mercado(v_mercado)
       AND NOT gesta.app_es_sistema()
       AND v_usr <> '00000000-0000-0000-0000-000000000001'::uuid THEN
        RAISE EXCEPTION 'No tiene permisos para aplicar la RN-FIS-02 en el mercado %', v_mercado;
    END IF;

    IF v_estatus IN ('BAJA', 'DESOCUPADO') THEN
        RETURN NULL;
    END IF;

    v_hoy := COALESCE(p_fecha, gesta.fn_hoy_local(v_mercado));
    v_ini_mes := date_trunc('month', v_hoy)::date;
    v_fin_mes := (v_ini_mes + interval '1 month' - interval '1 day')::date;

    SELECT id INTO v_cargo_penal
      FROM gesta.cargo
     WHERE local_id = p_local
       AND concepto = 'PENALIZACION'
       AND estado <> 'CANCELADO'
       AND date_trunc('month', periodo_inicio)::date = v_ini_mes;
    IF v_cargo_penal IS NOT NULL THEN
        RETURN v_cargo_penal;
    END IF;

    SELECT id, fecha_inicio, fecha_fin
      INTO v_concesion, v_conc_ini, v_conc_fin
      FROM gesta.concesion
     WHERE local_id = p_local
       AND estado IN ('VIGENTE', 'CEDIDA')
       AND NOT es_temporal_feria
       AND fecha_inicio <= v_hoy
       AND COALESCE(fecha_fin, 'infinity'::date) >= v_ini_mes
     ORDER BY (estado = 'VIGENTE') DESC, fecha_inicio DESC
     LIMIT 1;

    IF v_concesion IS NULL THEN
        RETURN NULL;
    END IF;

    v_ini_eval := GREATEST(v_ini_mes, v_conc_ini);
    v_fin_eval := LEAST(v_fin_mes, COALESCE(v_conc_fin, v_fin_mes));
    v_lim_omision := LEAST(v_hoy - 1, v_fin_eval);
    IF v_lim_omision < v_ini_eval THEN
        RETURN NULL;
    END IF;

    SELECT * INTO q FROM gesta.fn_calcular_cuota(p_local, v_ini_eval);
    IF q.monto IS NULL OR q.periodicidad <> 'DIARIA' THEN
        RETURN NULL;
    END IF;

    -- Evaluación sobre calendario hábil del mercado excluyendo días con incidencia AUSENTE_CERRADO
    -- (los cierres/ausencias se computan para abandono Art. 20 Fracc. XXVIII, no como omisión de cobro en activo)
    WITH dias_habiles_operativos AS (
        SELECT g.dia::date AS fecha,
               ROW_NUMBER() OVER (ORDER BY g.dia::date) AS rn_habil,
               (
                   EXISTS (
                       SELECT 1 FROM gesta.cargo c
                        WHERE c.local_id = p_local
                          AND (c.concesion_id = v_concesion OR c.concesion_id IS NULL)
                          AND c.concepto = 'DERECHO_PISO'
                          AND c.periodicidad = 'DIARIA'
                          AND c.estado IN ('PENDIENTE', 'PARCIAL')
                          AND g.dia::date BETWEEN c.periodo_inicio AND c.periodo_fin
                   )
                   OR (
                       NOT q.incluir_en_lote
                       AND NOT EXISTS (
                           SELECT 1 FROM gesta.cargo c
                            WHERE c.local_id = p_local
                              AND (c.concesion_id = v_concesion OR c.concesion_id IS NULL)
                              AND c.concepto = 'DERECHO_PISO'
                              AND c.estado IN ('PAGADO', 'CANCELADO')
                              AND g.dia::date BETWEEN c.periodo_inicio AND c.periodo_fin
                       )
                   )
               ) AS es_omision
          FROM generate_series(v_ini_eval, v_lim_omision, interval '1 day') AS g(dia)
         WHERE gesta.fn_es_dia_habil_mercado(v_mercado, g.dia::date)
           AND NOT EXISTS (
               SELECT 1 FROM gesta.asistencia_local al
                WHERE al.local_id = p_local
                  AND al.fecha = g.dia::date
                  AND al.tipo_incidencia = 'AUSENTE_CERRADO'
           )
    ), rachas AS (
        SELECT fecha,
               rn_habil - ROW_NUMBER() OVER (ORDER BY rn_habil) AS grp
          FROM dias_habiles_operativos
         WHERE es_omision
    ), conteo_rachas AS (
        SELECT grp, COUNT(*)::int AS longitud_racha
          FROM rachas
         GROUP BY grp
    )
    SELECT COALESCE((SELECT SUM(longitud_racha)::int FROM conteo_rachas), 0),
           COALESCE((SELECT MAX(longitud_racha)::int FROM conteo_rachas), 0)
      INTO v_omisiones_totales, v_max_racha;

    v_omisiones_eval := CASE
        WHEN v_modo_omisiones = 'ACUMULADAS' THEN v_omisiones_totales
        ELSE v_max_racha
    END;

    IF v_omisiones_eval < 5 THEN
        RETURN NULL;
    END IF;

    SELECT * INTO tf_row FROM gesta.tarifa WHERE id = q.tarifa_id;
    v_dias_mes := (v_fin_mes - v_ini_mes + 1);
    v_dias_activos := (v_fin_eval - v_ini_eval + 1);
    v_factor_uma := CASE WHEN tf_row.unidad_valor = 'UMA' THEN q.uma_aplicada ELSE 1 END;
    v_proporcion_mes := v_dias_activos::numeric / v_dias_mes::numeric;

    IF tf_row.valor_base_mensual THEN
        v_monto_mensual := ROUND(LEAST(
            GREATEST(
                (CASE tf_row.metodo_calculo
                    WHEN 'POR_M2' THEN q.area_m2 * tf_row.valor
                    WHEN 'POR_METRO_LINEAL' THEN q.metros_lineales * tf_row.valor
                    WHEN 'CUOTA_BASE_MAS_EXCEDENTE' THEN tf_row.cuota_base + (GREATEST(q.area_m2 - tf_row.metros_libres_base, 0) * tf_row.valor)
                    ELSE tf_row.valor END)
                * v_factor_uma * v_proporcion_mes,
                CASE WHEN tf_row.cuota_minima IS NOT NULL
                     THEN tf_row.cuota_minima * v_factor_uma * v_proporcion_mes END
            ),
            CASE WHEN tf_row.cuota_maxima IS NOT NULL
                 THEN tf_row.cuota_maxima * v_factor_uma * v_proporcion_mes END
        ), 2);
    ELSE
        v_monto_mensual := ROUND(q.monto * v_dias_activos, 2);
    END IF;

    SELECT COALESCE(SUM(LEAST(monto_pagado, monto_total)), 0)
      INTO v_pagado_mes
      FROM gesta.cargo
     WHERE local_id = p_local
       AND (concesion_id = v_concesion OR (concesion_id IS NULL AND periodo_inicio >= v_ini_eval AND periodo_fin <= v_fin_eval))
       AND concepto = 'DERECHO_PISO'
       AND periodo_inicio >= v_ini_eval
       AND periodo_fin <= v_fin_eval
       AND estado <> 'CANCELADO';

    v_saldo_exigible := GREATEST(v_monto_mensual - v_pagado_mes, 0);
    IF v_saldo_exigible <= 0 THEN
        RETURN NULL;
    END IF;

    FOR r_pend IN
        SELECT id, monto_total, monto_pagado, estado
          FROM gesta.cargo
         WHERE local_id = p_local
           AND (concesion_id = v_concesion OR (concesion_id IS NULL AND periodo_inicio >= v_ini_eval AND periodo_fin <= v_fin_eval))
           AND concepto = 'DERECHO_PISO'
           AND periodo_inicio >= v_ini_eval
           AND periodo_fin <= v_fin_eval
           AND estado IN ('PENDIENTE', 'PARCIAL')
           FOR UPDATE
    LOOP
        IF r_pend.estado = 'PENDIENTE' THEN
            INSERT INTO gesta.cargo_ajuste (cargo_id, local_id, mercado_id, tipo, monto_anterior, monto_nuevo, estado_anterior, motivo, usuario_id)
            VALUES (r_pend.id, p_local, v_mercado, 'CANCELACION', r_pend.monto_total, NULL, r_pend.estado,
                    'RN-FIS-02: revocación de cobro diario fragmentado por acumular ' || v_omisiones_eval || ' omisiones hábiles (' || v_modo_omisiones || ')', v_usr);
            PERFORM set_config('gesta.ajuste_autorizado', r_pend.id::text, true);
            UPDATE gesta.cargo
               SET estado = 'CANCELADO',
                   motivo_cancelacion = 'RN-FIS-02: sustituido por exigibilidad de cuota mensual vencida',
                   cancelado_por = v_usr,
                   cancelado_en = now()
             WHERE id = r_pend.id;
            PERFORM set_config('gesta.ajuste_autorizado', '', true);
        ELSIF r_pend.estado = 'PARCIAL' AND r_pend.monto_pagado > 0 THEN
            INSERT INTO gesta.cargo_ajuste (cargo_id, local_id, mercado_id, tipo, monto_anterior, monto_nuevo, estado_anterior, motivo, usuario_id)
            VALUES (r_pend.id, p_local, v_mercado, 'AJUSTE', r_pend.monto_total, r_pend.monto_pagado, r_pend.estado,
                    'RN-FIS-02: ajuste al monto abonado por absorción de saldo insoluto en cargo mensual de PENALIZACION', v_usr);
            PERFORM set_config('gesta.ajuste_autorizado', r_pend.id::text, true);
            UPDATE gesta.cargo
               SET monto_total = r_pend.monto_pagado,
                   estado = 'PAGADO'
             WHERE id = r_pend.id;
            PERFORM set_config('gesta.ajuste_autorizado', '', true);
        END IF;

        FOR r_rec IN
            SELECT id, monto_total, estado
              FROM gesta.cargo
             WHERE cargo_origen_id = r_pend.id
               AND concepto = 'RECARGO'
               AND estado = 'PENDIENTE'
               FOR UPDATE
        LOOP
            INSERT INTO gesta.cargo_ajuste (cargo_id, local_id, mercado_id, tipo, monto_anterior, monto_nuevo, estado_anterior, motivo, usuario_id)
            VALUES (r_rec.id, p_local, v_mercado, 'CANCELACION', r_rec.monto_total, NULL, r_rec.estado,
                    'RN-FIS-02: cancelación accesoria por sustitución de cargo diario ' || r_pend.id, v_usr);
            PERFORM set_config('gesta.ajuste_autorizado', r_rec.id::text, true);
            UPDATE gesta.cargo
               SET estado = 'CANCELADO',
                   motivo_cancelacion = 'RN-FIS-02: cancelación accesoria por sustitución de cargo diario',
                   cancelado_por = v_usr,
                   cancelado_en = now()
             WHERE id = r_rec.id;
            PERFORM set_config('gesta.ajuste_autorizado', '', true);
        END LOOP;
    END LOOP;

    INSERT INTO gesta.cargo (
        local_id, concesion_id, tarifa_id, concepto, periodo_inicio, periodo_fin,
        area_m2_aplicada, metros_lineales_aplicados, metodo_calculo, valor_tarifa_aplicado,
        unidad_valor_aplicada, valor_uma_aplicado, cuota_unidad_aplicada, periodicidad,
        unidades, monto_total
    )
    VALUES (
        p_local, v_concesion, q.tarifa_id, 'PENALIZACION', v_ini_eval, v_fin_eval,
        q.area_m2, q.metros_lineales, q.metodo, q.valor,
        q.unidad, q.uma_aplicada, v_saldo_exigible, 'MENSUAL',
        1, v_saldo_exigible
    )
    RETURNING id INTO v_cargo_penal;

    PERFORM gesta.fn_aplicar_saldo_favor_local(p_local, v_concesion);

    RETURN v_cargo_penal;
END $$;


