-- Name: FUNCTION fn_aplicar_penalizacion_morosidad_diaria(p_local uuid, p_fecha date); Type: COMMENT; Schema: gesta; Owner: gesta_owner
--

COMMENT ON FUNCTION gesta.fn_aplicar_penalizacion_morosidad_diaria(p_local uuid, p_fecha date) IS 'Fuente única de verdad de RN-FIS-02 en base de datos: evalúa 5 omisiones diarias en días hábiles del mercado (excluyendo ausencias cerradas), consolida la deuda mensual vencida y aplica saldo a favor FIFO. Invocable desde cobro o job programado.';


--
-- TOC entry 1172 (class 1255 OID 41106)
-- Name: fn_aplicar_saldo_favor_local(uuid, uuid); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.fn_aplicar_saldo_favor_local(p_local uuid, p_concesion uuid DEFAULT NULL::uuid) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $_$
DECLARE
    v_mercado bigint;
    v_conc_id uuid;
    v_titular uuid;
    v_conc_ini date;
    v_conc_fin date;
    v_total_aplicado numeric(12,2) := 0;
    v_abono numeric(12,2);
    v_saldo_cargo numeric(12,2);
    v_est_cargo gesta.estado_cargo;
    v_res text;
    v_motivo_limpio text;
    r_pago record;
    r_cargo record;
BEGIN
    SELECT mercado_id INTO v_mercado FROM gesta.local_comercial WHERE id = p_local;
    IF v_mercado IS NULL THEN RETURN 0; END IF;

    IF p_concesion IS NOT NULL THEN
        SELECT id, titular_persona_id, fecha_inicio, fecha_fin
          INTO v_conc_id, v_titular, v_conc_ini, v_conc_fin
          FROM gesta.concesion
         WHERE id = p_concesion;
    ELSE
        SELECT id, titular_persona_id, fecha_inicio, fecha_fin
          INTO v_conc_id, v_titular, v_conc_ini, v_conc_fin
          FROM gesta.concesion
         WHERE local_id = p_local
           AND estado IN ('VIGENTE', 'SUSPENDIDA')
         ORDER BY (estado = 'VIGENTE') DESC, fecha_inicio DESC
         LIMIT 1;
    END IF;

    FOR r_pago IN
        WITH det_efectivo AS (
            SELECT pd.pago_id,
                   pd.cargo_id,
                   CASE
                       WHEN cg.estado = 'CANCELADO'::gesta.estado_cargo THEN 0::numeric
                       ELSE GREATEST(
                           LEAST(
                               pd.monto_aplicado,
                               cg.monto_total - COALESCE(
                                   SUM(pd.monto_aplicado) OVER (
                                       PARTITION BY pd.cargo_id
                                       ORDER BY p_1.fecha_pago ASC, pd.pago_id ASC
                                       ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING
                                   ), 0::numeric
                               )
                           ), 0::numeric
                       )
                   END AS aplicado_efectivo
              FROM gesta.pago_detalle pd
              JOIN gesta.cargo cg ON cg.id = pd.cargo_id
              JOIN gesta.pago p_1 ON p_1.id = pd.pago_id
             WHERE p_1.local_id = p_local
               AND p_1.estado = 'VIGENTE'::gesta.estado_pago
        )
        SELECT p.id AS pago_id,
               p.fecha_pago,
               p.requiere_revision,
               p.motivo_revision,
               (p.monto - COALESCE(d.aplicado, 0::numeric)) AS saldo_libre
          FROM gesta.pago p
          LEFT JOIN (
              SELECT pago_id, SUM(aplicado_efectivo) AS aplicado
                FROM det_efectivo
               GROUP BY pago_id
          ) d ON d.pago_id = p.id
         WHERE p.local_id = p_local
           AND p.estado = 'VIGENTE'::gesta.estado_pago
           AND (p.monto - COALESCE(d.aplicado, 0::numeric)) > 0
           AND (
               v_titular IS NULL
               OR p.persona_pagador_id IS NOT DISTINCT FROM v_titular
               OR (p.persona_pagador_id IS NULL AND (v_conc_ini IS NULL OR gesta.fn_fecha_local(v_mercado, p.fecha_pago) >= v_conc_ini))
           )
         ORDER BY p.fecha_pago ASC, p.creado_en ASC, p.id ASC
    LOOP
        FOR r_cargo IN
            SELECT cg.id
              FROM gesta.cargo cg
             WHERE cg.local_id = p_local
               AND cg.estado IN ('PENDIENTE', 'PARCIAL')
               AND (cg.monto_total - cg.monto_pagado) > 0
               AND (
                   v_conc_id IS NULL
                   OR cg.concesion_id = v_conc_id
                   OR (cg.concesion_id IS NULL AND (v_conc_ini IS NULL OR cg.periodo_inicio >= v_conc_ini)
                       AND (v_conc_fin IS NULL OR cg.periodo_fin <= v_conc_fin))
               )
             ORDER BY (cg.concepto = 'RECARGO') ASC,
                      cg.periodo_inicio ASC,
                      cg.generado_en ASC,
                      cg.id ASC
        LOOP
            EXIT WHEN r_pago.saldo_libre <= 0;

            SELECT estado, GREATEST(monto_total - monto_pagado, 0)
              INTO v_est_cargo, v_saldo_cargo
              FROM gesta.cargo
             WHERE id = r_cargo.id;

            IF v_est_cargo NOT IN ('PENDIENTE', 'PARCIAL') OR v_saldo_cargo <= 0 THEN
                CONTINUE;
            END IF;

            v_abono := LEAST(r_pago.saldo_libre, v_saldo_cargo);
            IF v_abono > 0 THEN
                v_res := gesta.fn_aplicar_pago(r_pago.pago_id, r_cargo.id, v_abono);
                IF v_res IN ('APLICADO', 'APLICADO_PARCIAL') THEN
                    r_pago.saldo_libre := r_pago.saldo_libre - v_abono;
                    v_total_aplicado := v_total_aplicado + v_abono;
                END IF;
            END IF;
        END LOOP;

        -- Si el saldo a favor del pago se consumió por completo y la revisión obedecía únicamente al saldo a favor,
        -- se limpia la bandera requiere_revision dejando trazabilidad en motivo_revision
        IF r_pago.saldo_libre <= 0 AND r_pago.requiere_revision THEN
            v_motivo_limpio := COALESCE(r_pago.motivo_revision, '');
            v_motivo_limpio := regexp_replace(v_motivo_limpio, '(^|;\s*)Cargo ya cubierto: pago sin aplicar \(saldo a favor\)', '', 'gi');
            v_motivo_limpio := regexp_replace(v_motivo_limpio, '(^|;\s*)Excedente (en caja/Excel )?sin aplicar \(saldo a favor\)', '', 'gi');
            v_motivo_limpio := regexp_replace(v_motivo_limpio, '(^|;\s*)Pago en caja/Excel sin cargo aplicable \(saldo a favor\)', '', 'gi');
            v_motivo_limpio := regexp_replace(v_motivo_limpio, '(^|;\s*)Excedente a favor \(\$[0-9.]+\) generado por ajuste a la baja del cargo [0-9a-f-]+', '', 'gi');
            v_motivo_limpio := btrim(v_motivo_limpio, ' ;|');

            IF v_motivo_limpio = '' THEN
                PERFORM set_config('gesta.revision_pago_autorizada', r_pago.pago_id::text, true);
                UPDATE gesta.pago
                   SET requiere_revision = false,
                       motivo_revision = COALESCE(motivo_revision || ' | ', '')
                                         || 'Saldo a favor consumido automáticamente por prelación FIFO'
                 WHERE id = r_pago.pago_id;
                PERFORM set_config('gesta.revision_pago_autorizada', '', true);
            END IF;
        END IF;
    END LOOP;

    RETURN v_total_aplicado;
END $_$;


ALTER FUNCTION gesta.fn_aplicar_saldo_favor_local(p_local uuid, p_concesion uuid) OWNER TO gesta_owner;

--
-- TOC entry 907 (class 1255 OID 21051)
-- Name: fn_auditoria_agregar(text, text, text, uuid, jsonb, jsonb, bigint, bigint); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.fn_auditoria_agregar(p_tabla text, p_registro text, p_accion text, p_usuario uuid, p_antes jsonb, p_despues jsonb, p_mercado bigint, p_municipio bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $$
DECLARE v_prev text; v_ts timestamptz;
BEGIN
    PERFORM pg_advisory_xact_lock(hashtextextended('auditoria_cadena:' || COALESCE(p_mercado::text, 'global'), 0));
    IF p_mercado IS NULL THEN
        SELECT hash INTO v_prev FROM auditoria WHERE mercado_id IS NULL ORDER BY id DESC LIMIT 1;
    ELSE
        SELECT hash INTO v_prev FROM auditoria WHERE mercado_id = p_mercado ORDER BY id DESC LIMIT 1;
    END IF;
    v_ts := clock_timestamp();
    INSERT INTO auditoria (tabla, registro_id, accion, usuario_id, datos_antes, datos_despues,
                           ocurrido_en, mercado_id, municipio_id, hash_prev, hash)
    VALUES (p_tabla, p_registro, p_accion, p_usuario, p_antes, p_despues, v_ts, p_mercado, p_municipio, v_prev,
            fn_hash_auditoria(v_prev, p_tabla, p_registro, p_accion, p_usuario, p_antes, p_despues, v_ts, p_mercado, p_municipio));
END $$;


