--
-- TOC entry 1270 (class 1255 OID 21096)
-- Name: fn_buscar_vincular_persona(text, text, bigint); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.fn_buscar_vincular_persona(p_curp text, p_rfc text, p_mercado bigint) RETURNS gesta.persona_ref
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $$
DECLARE v_curp text := NULLIF(upper(btrim(p_curp)), ''); v_rfc text := NULLIF(upper(btrim(p_rfc)), '');
        v_ids uuid[]; p persona%ROWTYPE; v_res persona_ref;
BEGIN
    IF app_usuario() IS NULL THEN RAISE EXCEPTION 'Se requiere un usuario identificado'; END IF;
    IF p_mercado IS NULL OR NOT app_es_admin(p_mercado) THEN
        RAISE EXCEPTION 'Solo el administrador del mercado % puede buscar y vincular personas', p_mercado;
    END IF;
    IF v_curp IS NULL AND v_rfc IS NULL THEN RAISE EXCEPTION 'Indique CURP o RFC'; END IF;
    SELECT array_agg(id) INTO v_ids FROM persona
     WHERE (v_curp IS NOT NULL AND curp = v_curp) OR (v_rfc IS NOT NULL AND rfc = v_rfc);
    IF v_ids IS NULL THEN
        PERFORM fn_auditoria_agregar('persona', NULL, 'BUSCAR', app_usuario(), NULL,
                                     jsonb_build_object('encontrada', false, 'mercado_id', p_mercado), p_mercado, NULL);
        RETURN NULL;
    END IF;
    IF cardinality(v_ids) > 1 THEN
        RAISE EXCEPTION 'El CURP y el RFC indicados corresponden a personas distintas: revisar el padrón';
    END IF;
    SELECT * INTO p FROM persona WHERE id = v_ids[1];
    PERFORM fn_vincular_persona(p.id, p_mercado);
    PERFORM fn_auditoria_agregar('persona', p.id::text, 'VINCULAR', app_usuario(), NULL,
                                 jsonb_build_object('persona_id', p.id, 'mercado_id', p_mercado), p_mercado, NULL);
    v_res.id := p.id;
    v_res.nombre := CASE WHEN p.tipo_persona = 'MORAL' THEN p.razon_social
                         ELSE concat_ws(' ', p.nombres, p.apellido_paterno, p.apellido_materno) END;
    RETURN v_res;
END $$;


ALTER FUNCTION gesta.fn_buscar_vincular_persona(p_curp text, p_rfc text, p_mercado bigint) OWNER TO gesta_owner;

--
-- TOC entry 987 (class 1255 OID 20602)
-- Name: fn_calcular_cuota(uuid, date); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.fn_calcular_cuota(p_local uuid, p_fecha date DEFAULT NULL::date) RETURNS TABLE(tarifa_id bigint, area_m2 numeric, valor numeric, unidad gesta.unidad_valor, uma_aplicada numeric, metodo gesta.metodo_calculo, periodicidad gesta.periodicidad, monto numeric, incluir_en_lote boolean, metros_lineales numeric)
    LANGUAGE sql STABLE SECURITY DEFINER PARALLEL SAFE
    SET search_path TO 'gesta', 'public'
    AS $$
    WITH l AS (
        SELECT lc.id AS local_id, lc.mercado_id, m.municipio_id, lc.zona_id, lc.tipo_espacio,
               COALESCE(lc.area_oficial_m2, lc.area_calculada_m2) AS area,
               lc.metros_lineales AS ml,
               COALESCE(p_fecha, gesta.fn_hoy_local(lc.mercado_id)) AS fecha_eval,
               COALESCE(c.giro_id, lc.giro_observado_id) AS giro_id,
               c.fecha_inicio AS conc_ini,
               c.fecha_fin AS conc_fin
        FROM gesta.local_comercial lc
        JOIN gesta.mercado m ON m.id = lc.mercado_id
        LEFT JOIN LATERAL (
            SELECT cx.giro_id, cx.fecha_inicio, cx.fecha_fin
              FROM gesta.concesion cx
             WHERE cx.local_id = lc.id
               AND cx.estado = ANY (gesta.fn_estados_concesion_proceso('CALCULO_CUOTA'))
               AND cx.fecha_inicio <= COALESCE(p_fecha, gesta.fn_hoy_local(lc.mercado_id))
               AND COALESCE(cx.fecha_fin, 'infinity'::date) >= COALESCE(p_fecha, gesta.fn_hoy_local(lc.mercado_id))
             ORDER BY (cx.estado = 'VIGENTE') DESC,
                      (cx.estado = ANY (gesta.fn_estados_concesion_proceso('OCUPACION_ACTIVA'))) DESC,
                      cx.fecha_inicio DESC
             LIMIT 1
        ) c ON true
        WHERE lc.id = p_local
          AND (
              gesta.app_usuario() = '00000000-0000-0000-0000-000000000001'::uuid
              OR gesta.app_opera_en_mercado(lc.mercado_id)
              OR gesta.app_es_locatario_de(lc.id)
          )
    ), u AS (
        SELECT gesta.fn_valor_uma((SELECT fecha_eval FROM l), (SELECT mercado_id FROM l)) AS uma
    ), tf_sel AS (
        SELECT tf.*, l.local_id, l.area, l.ml, l.fecha_eval, l.conc_ini, l.conc_fin, u.uma,
               date_trunc('month', l.fecha_eval)::date AS ini_mes,
               (date_trunc('month', l.fecha_eval)::date + interval '1 month' - interval '1 day')::date AS fin_mes,
               EXTRACT(DAY FROM (date_trunc('month', l.fecha_eval)::date + interval '1 month' - interval '1 day'))::int AS dias_mes,
               LEAST(
                   GREATEST(
                       (CASE tf.metodo_calculo
                           WHEN 'POR_M2' THEN l.area * tf.valor
                           WHEN 'POR_METRO_LINEAL' THEN l.ml * tf.valor
                           WHEN 'CUOTA_BASE_MAS_EXCEDENTE'
                                THEN tf.cuota_base + (GREATEST(l.area - tf.metros_libres_base, 0) * tf.valor)
                           ELSE tf.valor END)
                       * (CASE WHEN tf.unidad_valor = 'UMA' THEN u.uma ELSE 1 END),
                       CASE WHEN tf.cuota_minima IS NOT NULL
                            THEN tf.cuota_minima * (CASE WHEN tf.unidad_valor = 'UMA' THEN u.uma ELSE 1 END)
                       END
                   ),
                   CASE WHEN tf.cuota_maxima IS NOT NULL
                        THEN tf.cuota_maxima * (CASE WHEN tf.unidad_valor = 'UMA' THEN u.uma ELSE 1 END)
                   END
               ) AS base_mensual_o_unitaria
        FROM gesta.tarifa tf
        JOIN l ON tf.municipio_id = l.municipio_id
              AND (tf.mercado_id IS NULL OR tf.mercado_id = l.mercado_id)
              AND (tf.zona_id IS NULL OR tf.zona_id = l.zona_id)
              AND (tf.tipo_espacio IS NULL OR tf.tipo_espacio = l.tipo_espacio)
              AND (tf.giro_id IS NULL OR tf.giro_id = l.giro_id)
        CROSS JOIN u
        WHERE tf.activo
          AND l.fecha_eval >= tf.vigente_desde
          AND l.fecha_eval <= COALESCE(tf.vigente_hasta, 'infinity'::date)
        ORDER BY (CASE WHEN tf.giro_id IS NOT NULL THEN 4 ELSE 0 END
                + CASE WHEN tf.zona_id IS NOT NULL THEN 2 ELSE 0 END
                + CASE WHEN tf.tipo_espacio IS NOT NULL THEN 1 ELSE 0 END) DESC,
                 (tf.mercado_id IS NOT NULL) DESC,
                 tf.vigente_desde DESC,
                 tf.id DESC
        LIMIT 1
    )
    SELECT t.id, t.area, t.valor, t.unidad_valor,
           CASE WHEN t.unidad_valor = 'UMA' THEN t.uma END,
           t.metodo_calculo, t.periodicidad,
           CASE WHEN (t.metodo_calculo IN ('POR_M2','CUOTA_BASE_MAS_EXCEDENTE') AND t.area IS NULL)
                  OR (t.metodo_calculo = 'POR_METRO_LINEAL' AND t.ml IS NULL)
                  OR (t.unidad_valor = 'UMA' AND t.uma IS NULL) THEN NULL
                WHEN NOT t.valor_base_mensual THEN ROUND(t.base_mensual_o_unitaria, 2)
                WHEN t.incluir_en_lote
                     AND t.fecha_eval = t.fin_mes
                     AND COALESCE(t.conc_ini, t.ini_mes) <= t.ini_mes
                     AND COALESCE(t.conc_fin, 'infinity'::date) >= t.fin_mes THEN
                     GREATEST(
                         ROUND(t.base_mensual_o_unitaria, 2) - (ROUND(t.base_mensual_o_unitaria * 12.0 / 365.0, 2) * (t.dias_mes - 1)),
                         0::numeric
                     )
                ELSE ROUND(t.base_mensual_o_unitaria * 12.0 / 365.0, 2)
           END,
           t.incluir_en_lote,
           t.ml
    FROM tf_sel t
$$;


ALTER FUNCTION gesta.fn_calcular_cuota(p_local uuid, p_fecha date) OWNER TO gesta_owner;

--
-- TOC entry 1243 (class 1255 OID 20633)
-- Name: fn_calcular_derecho_traspaso(uuid, uuid, numeric, date); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.fn_calcular_derecho_traspaso(p_concesion_origen_id uuid, p_persona_destino_id uuid, p_cuota_base_uma numeric DEFAULT 10.0, p_fecha date DEFAULT NULL::date) RETURNS TABLE(concesion_origen_id uuid, local_id uuid, mercado_id bigint, persona_destino_id uuid, es_familiar_suplente boolean, parentesco_registrado character varying, porcentaje_descuento numeric, uma_aplicada numeric, cuota_base_uma numeric, monto_bruto numeric, monto_bonificacion numeric, monto_neto_pagar numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $$
DECLARE
    v_usr       uuid := gesta.app_usuario();
    v_conc      gesta.concesion%ROWTYPE;
    v_mercado   bigint;
    v_fecha     date;
    v_uma       numeric(10,2);
    v_parent    varchar(50);
    v_es_fam    boolean := false;
    v_desc      numeric(5,2) := 0.00;
    v_bruto     numeric(12,2);
    v_bonif     numeric(12,2);
BEGIN
    IF v_usr IS NULL THEN
        RAISE EXCEPTION 'Se requiere un usuario identificado (app.usuario_id)';
    END IF;

    IF p_cuota_base_uma IS NULL OR p_cuota_base_uma <= 0 THEN
        RAISE EXCEPTION 'La cuota base en UMA para el derecho de traspaso debe ser mayor a cero';
    END IF;

    SELECT * INTO v_conc FROM gesta.concesion WHERE id = p_concesion_origen_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'La concesión de origen % no existe', p_concesion_origen_id;
    END IF;

    SELECT lc.mercado_id INTO v_mercado FROM gesta.local_comercial lc WHERE lc.id = v_conc.local_id;
    IF NOT gesta.app_opera_en_mercado(v_mercado)
       AND NOT gesta.app_es_locatario_concesion(v_conc.id)
       AND v_usr <> '00000000-0000-0000-0000-000000000001'::uuid THEN
        RAISE EXCEPTION 'No tiene permisos para calcular derechos de traspaso en el mercado %', v_mercado;
    END IF;

    v_fecha := COALESCE(p_fecha, gesta.fn_hoy_local(v_mercado));
    v_uma   := gesta.fn_valor_uma(v_fecha, v_mercado);

    SELECT cs.parentesco INTO v_parent
      FROM gesta.concesion_suplente cs
     WHERE cs.concesion_id = p_concesion_origen_id
       AND cs.persona_id   = p_persona_destino_id
     LIMIT 1;

    IF FOUND THEN
        v_es_fam := true;
        v_desc   := 50.00;
    END IF;

    IF v_uma IS NOT NULL THEN
        v_bruto := ROUND(p_cuota_base_uma * v_uma, 2);
        v_bonif := ROUND(v_bruto * (v_desc / 100.0), 2);
    END IF;

    RETURN QUERY SELECT
        v_conc.id,
        v_conc.local_id,
        v_mercado,
        p_persona_destino_id,
        v_es_fam,
        v_parent,
        v_desc,
        v_uma,
        p_cuota_base_uma,
        v_bruto,
        v_bonif,
        CASE WHEN v_uma IS NOT NULL THEN v_bruto - v_bonif ELSE NULL END;
END $$;


ALTER FUNCTION gesta.fn_calcular_derecho_traspaso(p_concesion_origen_id uuid, p_persona_destino_id uuid, p_cuota_base_uma numeric, p_fecha date) OWNER TO gesta_owner;

--
-- TOC entry 1326 (class 1255 OID 21090)
-- Name: fn_cancelar_cargo(uuid, text); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.fn_cancelar_cargo(p_cargo uuid, p_motivo text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $$
DECLARE
    v gesta.cargo%ROWTYPE;
    v_mercado bigint;
    r_rec record;
    v_usr uuid := gesta.app_usuario();
BEGIN
    IF v_usr IS NULL THEN
        RAISE EXCEPTION 'Se requiere un usuario identificado';
    END IF;
    IF p_motivo IS NULL OR btrim(p_motivo) = '' THEN
        RAISE EXCEPTION 'El motivo de la cancelación es obligatorio';
    END IF;

    SELECT * INTO v FROM gesta.cargo WHERE id = p_cargo FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'El cargo % no existe', p_cargo;
    END IF;

    SELECT mercado_id INTO v_mercado FROM gesta.local_comercial WHERE id = v.local_id;
    IF NOT gesta.app_autoriza_ajuste_fiscal(v_mercado) THEN
        RAISE EXCEPTION 'RN-FIS-05 / CU-20: No cuenta con autorización de Tesorería o Administración Municipal para cancelar cargos';
    END IF;
    IF v.estado = 'CANCELADO' THEN
        RAISE EXCEPTION 'El cargo ya está cancelado';
    END IF;
    IF EXISTS (
        SELECT 1
          FROM gesta.pago_detalle d
          JOIN gesta.pago p ON p.id = d.pago_id
         WHERE (d.cargo_id = v.id OR d.cargo_id IN (SELECT rc.id FROM gesta.cargo rc WHERE rc.cargo_origen_id = v.id))
           AND p.cobrador_id = v_usr
    ) THEN
        RAISE EXCEPTION 'RN-FIS-05 / CU-20: Segregación de funciones: no puede cancelar un cargo con cobros realizados por usted mismo';
    END IF;

    INSERT INTO gesta.cargo_ajuste (cargo_id, local_id, mercado_id, tipo, monto_anterior, monto_nuevo, estado_anterior, motivo, usuario_id)
    VALUES (v.id, v.local_id, v_mercado, 'CANCELACION', v.monto_total, NULL, v.estado, btrim(p_motivo), v_usr);

    PERFORM set_config('gesta.ajuste_autorizado', v.id::text, true);
    UPDATE gesta.cargo
       SET estado = 'CANCELADO',
           motivo_cancelacion = btrim(p_motivo),
           cancelado_por = v_usr,
           cancelado_en = now()
     WHERE id = v.id;
    PERFORM set_config('gesta.ajuste_autorizado', '', true);

    IF v.monto_pagado > 0 THEN
        UPDATE gesta.pago
           SET requiere_revision = true,
               motivo_revision = COALESCE(motivo_revision || '; ', '')
                                 || 'Cargo ' || v.id || ' cancelado con pagos aplicados (saldo a favor / revisar devolución)'
         WHERE id IN (SELECT pd.pago_id FROM gesta.pago_detalle pd WHERE pd.cargo_id = v.id)
           AND estado = 'VIGENTE';
    END IF;

    FOR r_rec IN
        SELECT id, monto_total, monto_pagado, estado
          FROM gesta.cargo
         WHERE cargo_origen_id = v.id
           AND concepto = 'RECARGO'
           AND estado <> 'CANCELADO'
           FOR UPDATE
    LOOP
        INSERT INTO gesta.cargo_ajuste (cargo_id, local_id, mercado_id, tipo, monto_anterior, monto_nuevo, estado_anterior, motivo, usuario_id)
        VALUES (r_rec.id, v.local_id, v_mercado, 'CANCELACION', r_rec.monto_total, NULL, r_rec.estado,
                'Cancelación accesoria por anulación de cargo origen ' || v.id || ': ' || btrim(p_motivo), v_usr);

        PERFORM set_config('gesta.ajuste_autorizado', r_rec.id::text, true);
        UPDATE gesta.cargo
           SET estado = 'CANCELADO',
               motivo_cancelacion = 'Cancelación accesoria por anulación de cargo origen ' || v.id,
               cancelado_por = v_usr,
               cancelado_en = now()
         WHERE id = r_rec.id;
        PERFORM set_config('gesta.ajuste_autorizado', '', true);

        IF r_rec.monto_pagado > 0 THEN
            UPDATE gesta.pago
               SET requiere_revision = true,
                   motivo_revision = COALESCE(motivo_revision || '; ', '')
                                     || 'Recargo ' || r_rec.id || ' cancelado por anulación de cargo origen (saldo a favor)'
             WHERE id IN (SELECT pd.pago_id FROM gesta.pago_detalle pd WHERE pd.cargo_id = r_rec.id)
               AND estado = 'VIGENTE';
        END IF;
    END LOOP;
END $$;


ALTER FUNCTION gesta.fn_cancelar_cargo(p_cargo uuid, p_motivo text) OWNER TO gesta_owner;

--
-- TOC entry 558 (class 1255 OID 21092)
-- Name: fn_cancelar_pago(uuid, text); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.fn_cancelar_pago(p_pago uuid, p_motivo text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $$
DECLARE
    v gesta.pago%ROWTYPE;
    v_usr uuid := gesta.app_usuario();
BEGIN
    IF v_usr IS NULL THEN
        RAISE EXCEPTION 'Se requiere un usuario identificado';
    END IF;
    IF p_motivo IS NULL OR btrim(p_motivo) = '' THEN
        RAISE EXCEPTION 'El motivo de la cancelación del pago es obligatorio';
    END IF;

    SELECT * INTO v FROM gesta.pago WHERE id = p_pago FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'El pago % no existe', p_pago;
    END IF;
    IF NOT gesta.app_autoriza_ajuste_fiscal(v.mercado_id) THEN
        RAISE EXCEPTION 'RN-FIS-05 / CU-20: No cuenta con autorización de Tesorería o Administración Municipal para cancelar pagos';
    END IF;
    IF v.cobrador_id IS NOT NULL AND v.cobrador_id = v_usr THEN
        RAISE EXCEPTION 'RN-FIS-05 / CU-20: Segregación de funciones: no puede cancelar un pago cobrado por usted mismo';
    END IF;
    IF v.estado = 'CANCELADO' THEN
        RAISE EXCEPTION 'El pago ya está cancelado';
    END IF;

    PERFORM set_config('gesta.cancelacion_pago_autorizada', v.id::text, true);
    UPDATE gesta.pago
       SET estado = 'CANCELADO',
           motivo_cancelacion = btrim(p_motivo)
     WHERE id = p_pago;
    PERFORM set_config('gesta.cancelacion_pago_autorizada', '', true);

    IF v.corte_caja_id IS NOT NULL THEN
        INSERT INTO gesta.corte_caja_ajuste (
            corte_caja_id, pago_id, mercado_id, deposito_id,
            monto_anulado, motivo, autorizado_por
        )
        VALUES (
            v.corte_caja_id, v.id, v.mercado_id, v.deposito_id,
            v.monto, btrim(p_motivo), v_usr
        );
    END IF;
END $$;


ALTER FUNCTION gesta.fn_cancelar_pago(p_pago uuid, p_motivo text) OWNER TO gesta_owner;

--
-- TOC entry 291 (class 1255 OID 32780)
-- Name: fn_cerrar_corte(uuid, bigint, date, numeric, text); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.fn_cerrar_corte(p_cobrador uuid, p_mercado bigint, p_fecha date, p_monto_declarado numeric, p_observaciones text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $$
DECLARE
    v_id uuid;
    v_total numeric(12,2);
    v_n integer;
    v_sec smallint;
    v_ids uuid[];
    v_fcorte date;
    v_usr uuid := gesta.app_usuario();
BEGIN
    IF v_usr IS NULL THEN
        RAISE EXCEPTION 'Se requiere un usuario identificado (app.usuario_id)';
    END IF;
    IF p_cobrador IS NULL THEN
        RAISE EXCEPTION 'Debe indicar el cobrador del corte de caja';
    END IF;
    IF p_monto_declarado IS NULL OR p_monto_declarado < 0 THEN
        RAISE EXCEPTION 'RN-FIS-05: El corte de caja es ciego; debe declarar explícitamente el monto físico contado (>= 0)';
    END IF;
    IF NOT gesta.app_autoriza_ajuste_fiscal(p_mercado)
       OR (p_cobrador = v_usr AND NOT gesta.app_es_sistema()) THEN
        RAISE EXCEPTION 'RN-FIS-05: El corte de caja diario ciego no puede ser autoliquidado por el mismo cobrador; debe liquidarse ante Tesorería o Administración Municipal distinta';
    END IF;

    v_fcorte := COALESCE(p_fecha, gesta.fn_hoy_local(p_mercado));
    PERFORM pg_advisory_xact_lock(hashtextextended('corte:' || p_cobrador::text || ':' || p_mercado::text, 0));

    SELECT COALESCE(array_agg(x.id), '{}'::uuid[]), COALESCE(SUM(x.monto), 0), COUNT(*)
      INTO v_ids, v_total, v_n
      FROM (
          SELECT id, monto
            FROM gesta.pago
           WHERE cobrador_id = p_cobrador
             AND mercado_id = p_mercado
             AND estado = 'VIGENTE'
             AND forma_pago = 'EFECTIVO'
             AND corte_caja_id IS NULL
             AND gesta.fn_fecha_local(p_mercado, fecha_pago) = v_fcorte
           FOR UPDATE
      ) x;

    IF v_n = 0 THEN
        RAISE EXCEPTION 'No hay pagos en efectivo pendientes de corte para la fecha %', v_fcorte;
    END IF;

    SELECT COALESCE(MAX(secuencia), 0) + 1
      INTO v_sec
      FROM gesta.corte_caja_diario
     WHERE cobrador_id = p_cobrador
       AND mercado_id = p_mercado
       AND fecha_corte = v_fcorte;

    INSERT INTO gesta.corte_caja_diario (
        cobrador_id, mercado_id, fecha_corte, secuencia,
        monto_total, monto_declarado, num_pagos, recibido_por, observaciones
    )
    VALUES (
        p_cobrador, p_mercado, v_fcorte, v_sec,
        v_total, ROUND(p_monto_declarado, 2), v_n, v_usr, NULLIF(btrim(p_observaciones), '')
    )
    RETURNING id INTO v_id;

    PERFORM set_config('gesta.corte_autorizado', v_id::text, true);
    UPDATE gesta.pago SET corte_caja_id = v_id WHERE id = ANY (v_ids);
    PERFORM set_config('gesta.corte_autorizado', '', true);

    RETURN v_id;
END $$;


ALTER FUNCTION gesta.fn_cerrar_corte(p_cobrador uuid, p_mercado bigint, p_fecha date, p_monto_declarado numeric, p_observaciones text) OWNER TO gesta_owner;

