--
-- TOC entry 773 (class 1255 OID 32953)
-- Name: fn_configurar_secreto_hmac(text); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.fn_configurar_secreto_hmac(p_secreto_hex text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $_$
DECLARE
    v_clean text := NULLIF(btrim(p_secreto_hex), '');
    v_bytes bytea;
BEGIN
    IF v_clean IS NULL OR v_clean !~ '^[0-9a-fA-F]{64,128}$' THEN
        RAISE EXCEPTION 'El secreto HMAC debe proporcionarse como cadena hexadecimal de al menos 64 caracteres (256 bits)';
    END IF;

    -- Prohibir explícitamente reutilizar el secreto comprometido en el volcado 8_6
    IF lower(v_clean) = 'a564ab09e07774df2a18a438d7d9233a6561127be6f9dd7c55f4c43f01ce8f90' THEN
        RAISE EXCEPTION 'Seguridad: el secreto indicado fue expuesto en un volcado previo y está revocado';
    END IF;

    v_bytes := decode(v_clean, 'hex');

    INSERT INTO gesta.secreto_firma_sesion (id, secreto_hmac, exigir_firma, actualizado_en)
    VALUES (true, v_bytes, true, now())
    ON CONFLICT (id) DO UPDATE
        SET secreto_hmac = EXCLUDED.secreto_hmac,
            exigir_firma = true,
            actualizado_en = now();
END $_$;


ALTER FUNCTION gesta.fn_configurar_secreto_hmac(p_secreto_hex text) OWNER TO gesta_owner;

--
-- TOC entry 1116 (class 1255 OID 41281)
-- Name: fn_dispositivo_avanzar_consecutivo(uuid, bigint); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.fn_dispositivo_avanzar_consecutivo(p_dispositivo uuid, p_consecutivo bigint) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $$
DECLARE
    v_usr uuid := gesta.app_usuario();
    d gesta.dispositivo%ROWTYPE;
BEGIN
    IF v_usr IS NULL THEN
        RAISE EXCEPTION 'Se requiere un usuario identificado (app.usuario_id)';
    END IF;
    IF p_consecutivo IS NULL OR p_consecutivo <= 0 THEN
        RAISE EXCEPTION 'El consecutivo debe ser un entero positivo mayor a cero';
    END IF;

    SELECT * INTO d FROM gesta.dispositivo WHERE id = p_dispositivo FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'El dispositivo % no existe', p_dispositivo;
    END IF;
    IF NOT d.activo THEN
        RAISE EXCEPTION 'El dispositivo % se encuentra inactivo', p_dispositivo;
    END IF;

    IF NOT (
        gesta.app_es_sistema()
        OR d.usuario_id = v_usr
        OR (d.mercado_id IS NOT NULL AND gesta.app_es_admin(d.mercado_id))
    ) THEN
        RAISE EXCEPTION 'No tiene permisos para actualizar el consecutivo del dispositivo %', p_dispositivo;
    END IF;

    IF p_consecutivo < d.ultimo_consecutivo THEN
        RAISE EXCEPTION 'Seguridad de folios (CU-18 / CU-19): no se permite disminuir ultimo_consecutivo del dispositivo % (actual %, intentado %)',
                        d.id, d.ultimo_consecutivo, p_consecutivo;
    END IF;

    PERFORM set_config('gesta.dispositivo_autorizado', d.id::text, true);
    UPDATE gesta.dispositivo
       SET ultimo_consecutivo = p_consecutivo,
           ultima_sincronizacion = now()
     WHERE id = d.id;
    PERFORM set_config('gesta.dispositivo_autorizado', '', true);

    RETURN p_consecutivo;
END $$;


ALTER FUNCTION gesta.fn_dispositivo_avanzar_consecutivo(p_dispositivo uuid, p_consecutivo bigint) OWNER TO gesta_owner;

--
-- TOC entry 1424 (class 1255 OID 41280)
-- Name: fn_dispositivo_cambiar_serie(uuid, character varying); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.fn_dispositivo_cambiar_serie(p_dispositivo uuid, p_nueva_serie character varying) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $_$
DECLARE
    v_usr uuid := gesta.app_usuario();
    v_serie text := upper(NULLIF(btrim(p_nueva_serie), ''));
    d gesta.dispositivo%ROWTYPE;
BEGIN
    IF v_usr IS NULL THEN
        RAISE EXCEPTION 'Se requiere un usuario identificado (app.usuario_id)';
    END IF;
    IF v_serie IS NULL OR v_serie !~ '^[A-Z0-9]{2,10}$' THEN
        RAISE EXCEPTION 'La serie_folio debe contener entre 2 y 10 caracteres alfanuméricos';
    END IF;

    SELECT * INTO d FROM gesta.dispositivo WHERE id = p_dispositivo FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'El dispositivo % no existe', p_dispositivo;
    END IF;

    IF NOT (
        gesta.app_es_sistema()
        OR (d.mercado_id IS NOT NULL AND gesta.app_es_admin(d.mercado_id))
        OR (d.mercado_id IS NULL AND gesta.app_admin_gestiona_usuario(d.usuario_id))
    ) THEN
        RAISE EXCEPTION 'Solo un Administrador autorizado puede modificar serie_folio del dispositivo %', p_dispositivo;
    END IF;

    IF d.ultimo_consecutivo > 0
       OR EXISTS (SELECT 1 FROM gesta.pago p WHERE p.dispositivo_id = d.id)
       OR EXISTS (SELECT 1 FROM gesta.pago_conflicto_folio pc WHERE pc.dispositivo_id = d.id) THEN
        RAISE EXCEPTION 'Inmutabilidad de serie (CU-18): no se puede cambiar serie_folio (%) del dispositivo % porque ya registra pagos o consecutivos emitidos',
                        d.serie_folio, d.id;
    END IF;

    PERFORM set_config('gesta.dispositivo_autorizado', d.id::text, true);
    UPDATE gesta.dispositivo
       SET serie_folio = v_serie
     WHERE id = d.id;
    PERFORM set_config('gesta.dispositivo_autorizado', '', true);
END $_$;


ALTER FUNCTION gesta.fn_dispositivo_cambiar_serie(p_dispositivo uuid, p_nueva_serie character varying) OWNER TO gesta_owner;

--
-- TOC entry 897 (class 1255 OID 41282)
-- Name: fn_dispositivo_rotar_secreto_hmac(uuid, text); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.fn_dispositivo_rotar_secreto_hmac(p_dispositivo uuid, p_secreto_hex text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $_$
DECLARE
    v_usr uuid := gesta.app_usuario();
    v_clean text := NULLIF(btrim(p_secreto_hex), '');
    v_bytes bytea;
    d gesta.dispositivo%ROWTYPE;
BEGIN
    IF v_usr IS NULL THEN
        RAISE EXCEPTION 'Se requiere un usuario identificado (app.usuario_id)';
    END IF;

    SELECT * INTO d FROM gesta.dispositivo WHERE id = p_dispositivo FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'El dispositivo % no existe', p_dispositivo;
    END IF;

    IF NOT (
        gesta.app_es_sistema()
        OR (d.mercado_id IS NOT NULL AND gesta.app_es_admin(d.mercado_id))
        OR (d.mercado_id IS NULL AND gesta.app_admin_gestiona_usuario(d.usuario_id))
    ) THEN
        RAISE EXCEPTION 'Solo un Administrador autorizado puede provisionar o rotar el secreto HMAC del dispositivo %', p_dispositivo;
    END IF;

    IF v_clean IS NULL THEN
        v_bytes := public.gen_random_bytes(32);
    ELSE
        IF v_clean !~ '^[0-9a-fA-F]{64,128}$' THEN
            RAISE EXCEPTION 'El secreto HMAC del dispositivo debe ser una cadena hexadecimal de entre 64 y 128 caracteres (256 a 512 bits)';
        END IF;
        v_bytes := decode(v_clean, 'hex');
    END IF;

    PERFORM set_config('gesta.dispositivo_autorizado', d.id::text, true);
    UPDATE gesta.dispositivo
       SET secreto_hmac = v_bytes
     WHERE id = d.id;
    PERFORM set_config('gesta.dispositivo_autorizado', '', true);

    RETURN encode(v_bytes, 'hex');
END $_$;


ALTER FUNCTION gesta.fn_dispositivo_rotar_secreto_hmac(p_dispositivo uuid, p_secreto_hex text) OWNER TO gesta_owner;

--
-- TOC entry 1083 (class 1255 OID 41279)
-- Name: fn_dispositivo_set_activo(uuid, boolean, text); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.fn_dispositivo_set_activo(p_dispositivo uuid, p_activo boolean, p_motivo text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $$
DECLARE
    v_usr uuid := gesta.app_usuario();
    d gesta.dispositivo%ROWTYPE;
BEGIN
    IF v_usr IS NULL THEN
        RAISE EXCEPTION 'Se requiere un usuario identificado (app.usuario_id)';
    END IF;
    IF p_activo IS NULL THEN
        RAISE EXCEPTION 'Debe indicar el estado activo (true/false)';
    END IF;

    SELECT * INTO d FROM gesta.dispositivo WHERE id = p_dispositivo FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'El dispositivo % no existe', p_dispositivo;
    END IF;

    IF NOT (
        gesta.app_es_sistema()
        OR (d.mercado_id IS NOT NULL AND gesta.app_es_admin(d.mercado_id))
        OR (d.mercado_id IS NULL AND gesta.app_admin_gestiona_usuario(d.usuario_id))
    ) THEN
        RAISE EXCEPTION 'Solo un Administrador autorizado puede activar o desactivar el dispositivo %', p_dispositivo;
    END IF;

    IF d.usuario_id = v_usr
       AND NOT gesta.app_es_sistema()
       AND NOT (d.mercado_id IS NOT NULL AND gesta.app_es_admin(d.mercado_id)) THEN
        RAISE EXCEPTION 'Segregación de funciones: un cobrador no puede reactivar ni cambiar el estado de su propio dispositivo';
    END IF;

    PERFORM set_config('gesta.dispositivo_autorizado', d.id::text, true);
    UPDATE gesta.dispositivo
       SET activo = p_activo
     WHERE id = d.id;
    PERFORM set_config('gesta.dispositivo_autorizado', '', true);
END $$;


ALTER FUNCTION gesta.fn_dispositivo_set_activo(p_dispositivo uuid, p_activo boolean, p_motivo text) OWNER TO gesta_owner;

--
-- TOC entry 555 (class 1255 OID 41143)
-- Name: fn_es_dia_habil_mercado(bigint, date); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.fn_es_dia_habil_mercado(p_mercado bigint, p_fecha date) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER PARALLEL SAFE
    SET search_path TO 'gesta', 'public'
    AS $$
    SELECT EXISTS (
        SELECT 1
          FROM gesta.mercado m
         WHERE m.id = p_mercado
           AND EXTRACT(ISODOW FROM p_fecha)::smallint = ANY (m.dias_operacion)
           AND NOT EXISTS (
               SELECT 1
                 FROM gesta.mercado_dia_inhabil di
                WHERE di.mercado_id = p_mercado
                  AND di.fecha = p_fecha
           )
    )
$$;


ALTER FUNCTION gesta.fn_es_dia_habil_mercado(p_mercado bigint, p_fecha date) OWNER TO gesta_owner;

--
-- TOC entry 1382 (class 1255 OID 41244)
-- Name: fn_estados_concesion_proceso(text); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.fn_estados_concesion_proceso(p_proceso text) RETURNS gesta.estado_concesion[]
    LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'gesta', 'public'
    AS $$
BEGIN
    CASE upper(btrim(p_proceso))
        -- Unicidad personalísima en padrón (RN-PAD-01): cuenta VIGENTE y SUSPENDIDA
        WHEN 'UNICIDAD_PADRON' THEN
            RETURN ARRAY['VIGENTE', 'SUSPENDIDA']::gesta.estado_concesion[];
        -- Ocupación activa del local y visibilidad operativa de locatario activo
        WHEN 'OCUPACION_ACTIVA' THEN
            RETURN ARRAY['VIGENTE', 'SUSPENDIDA']::gesta.estado_concesion[];
        -- Facturación periódica y penalización por morosidad (excluye SUSPENDIDA, REVOCADA y VENCIDA)
        WHEN 'FACTURACION' THEN
            RETURN ARRAY['VIGENTE', 'CEDIDA']::gesta.estado_concesion[];
        -- Cobro en campo y caja (permite cobrar adeudos o periodo en curso de VIGENTE, SUSPENDIDA y tramo CEDIDA)
        WHEN 'COBRO' THEN
            RETURN ARRAY['VIGENTE', 'SUSPENDIDA', 'CEDIDA']::gesta.estado_concesion[];
        -- Cálculo y simulación de cuota (excluye VENCIDA y REVOCADA)
        WHEN 'CALCULO_CUOTA' THEN
            RETURN ARRAY['VIGENTE', 'SUSPENDIDA', 'CEDIDA']::gesta.estado_concesion[];
        -- Job de cierre automático por vencimiento de vigencia
        WHEN 'CIERRE_VENCIMIENTO' THEN
            RETURN ARRAY['VIGENTE', 'SUSPENDIDA']::gesta.estado_concesion[];
        ELSE
            RAISE EXCEPTION 'Proceso de matriz de estados de concesión no reconocido: %', p_proceso;
    END CASE;
END $$;


ALTER FUNCTION gesta.fn_estados_concesion_proceso(p_proceso text) OWNER TO gesta_owner;

--
-- TOC entry 1244 (class 1255 OID 41147)
-- Name: fn_evaluar_penalizaciones_mercado(bigint, date); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.fn_evaluar_penalizaciones_mercado(p_mercado bigint, p_fecha date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $$
DECLARE
    v_usr uuid := gesta.app_usuario();
    v_fecha date;
    v_evaluados integer := 0;
    v_penalizados integer := 0;
    v_cargo_penal uuid;
    r_loc record;
    v_res jsonb;
BEGIN
    IF v_usr IS NULL THEN
        RAISE EXCEPTION 'Se requiere un usuario identificado (app.usuario_id)';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM gesta.mercado WHERE id = p_mercado) THEN
        RAISE EXCEPTION 'El mercado % no existe', p_mercado;
    END IF;
    IF NOT gesta.app_es_admin(p_mercado)
       AND NOT gesta.app_tiene_rol('TESORERIA', p_mercado)
       AND NOT gesta.app_es_sistema()
       AND v_usr <> '00000000-0000-0000-0000-000000000001'::uuid THEN
        RAISE EXCEPTION 'Solo Administración, Tesorería o el job de sistema pueden evaluar penalizaciones masivas en el mercado %', p_mercado;
    END IF;

    v_fecha := COALESCE(p_fecha, gesta.fn_hoy_local(p_mercado));

    FOR r_loc IN
        SELECT lc.id AS local_id
          FROM gesta.local_comercial lc
         WHERE lc.mercado_id = p_mercado
           AND lc.estatus NOT IN ('BAJA', 'DESOCUPADO')
         ORDER BY lc.numero_local
    LOOP
        v_evaluados := v_evaluados + 1;
        IF NOT EXISTS (
            SELECT 1 FROM gesta.cargo cp
             WHERE cp.local_id = r_loc.local_id
               AND cp.concepto = 'PENALIZACION'
               AND cp.estado <> 'CANCELADO'
               AND date_trunc('month', cp.periodo_inicio)::date = date_trunc('month', v_fecha)::date
        ) THEN
            v_cargo_penal := gesta.fn_aplicar_penalizacion_morosidad_diaria(r_loc.local_id, v_fecha);
            IF v_cargo_penal IS NOT NULL THEN
                v_penalizados := v_penalizados + 1;
            END IF;
        END IF;
    END LOOP;

    v_res := jsonb_build_object(
        'mercado_id', p_mercado,
        'fecha_evaluacion', v_fecha,
        'locales_evaluados', v_evaluados,
        'penalizaciones_generadas', v_penalizados
    );

    PERFORM gesta.fn_auditoria_agregar('cargo', NULL, 'JOB_PENAL', v_usr, NULL, v_res, p_mercado, NULL);
    RETURN v_res;
END $$;


ALTER FUNCTION gesta.fn_evaluar_penalizaciones_mercado(p_mercado bigint, p_fecha date) OWNER TO gesta_owner;

--
-- TOC entry 573 (class 1255 OID 20275)
-- Name: fn_fecha_local(bigint, timestamp with time zone); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.fn_fecha_local(p_mercado bigint, p_ts timestamp with time zone) RETURNS date
    LANGUAGE sql STABLE SECURITY DEFINER PARALLEL SAFE
    SET search_path TO 'gesta', 'public'
    AS $$
    SELECT (p_ts AT TIME ZONE COALESCE(mu.zona_horaria, 'America/Mexico_City'))::date
      FROM gesta.mercado m
      JOIN gesta.municipio mu ON mu.id = m.municipio_id
     WHERE m.id = p_mercado
$$;


ALTER FUNCTION gesta.fn_fecha_local(p_mercado bigint, p_ts timestamp with time zone) OWNER TO gesta_owner;

--
-- TOC entry 469 (class 1255 OID 40972)
-- Name: fn_generar_cargo_local(uuid, date, date); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.fn_generar_cargo_local(p_local uuid, p_inicio date DEFAULT NULL::date, p_fin date DEFAULT NULL::date) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $$
DECLARE
    v_mercado bigint;
    v_estatus gesta.estatus_local;
    v_conc uuid;
    v_conc_ini date;
    v_conc_fin date;
    v_ini date;
    v_fin date;
    v_unid numeric;
    v_monto numeric(12,2);
    v_cargo_id uuid;
    q record;
BEGIN
    IF gesta.app_usuario() IS NULL THEN
        RAISE EXCEPTION 'Se requiere un usuario identificado (app.usuario_id)';
    END IF;

    SELECT lc.mercado_id, lc.estatus
      INTO v_mercado, v_estatus
      FROM gesta.local_comercial lc
     WHERE lc.id = p_local;

    IF v_mercado IS NULL THEN
        RAISE EXCEPTION 'El local % no existe', p_local;
    END IF;

    IF NOT gesta.app_es_admin(v_mercado)
       AND NOT gesta.app_tiene_rol('TESORERIA', v_mercado)
       AND NOT gesta.app_es_sistema() THEN
        RAISE EXCEPTION 'No tiene permisos para generar cargos en el mercado %', v_mercado;
    END IF;

    IF v_estatus IN ('BAJA', 'DESOCUPADO') THEN
        RAISE EXCEPTION 'No se pueden generar cargos para un local en estatus %', v_estatus;
    END IF;

    v_ini := COALESCE(p_inicio, gesta.fn_hoy_local(v_mercado));
    v_fin := COALESCE(p_fin, v_ini);
    IF v_fin < v_ini THEN
        RAISE EXCEPTION 'Periodo inválido: % > %', v_ini, v_fin;
    END IF;

    SELECT c.id, c.fecha_inicio, c.fecha_fin
      INTO v_conc, v_conc_ini, v_conc_fin
      FROM gesta.concesion c
     WHERE c.local_id = p_local
       AND c.estado IN ('VIGENTE', 'CEDIDA')
       AND c.fecha_inicio <= v_fin
       AND COALESCE(c.fecha_fin, 'infinity'::date) >= v_ini
     ORDER BY (c.estado = 'VIGENTE') DESC, c.fecha_inicio DESC
     LIMIT 1;

    IF v_conc IS NULL THEN
        RAISE EXCEPTION 'El local % no cuenta con concesión vigente para el periodo solicitado', p_local;
    END IF;

    v_ini := GREATEST(v_ini, v_conc_ini);
    v_fin := LEAST(v_fin, COALESCE(v_conc_fin, 'infinity'::date));

    SELECT * INTO q FROM gesta.fn_calcular_cuota(p_local, v_ini);
    IF q.tarifa_id IS NULL OR q.monto IS NULL OR q.monto <= 0 THEN
        RAISE EXCEPTION 'No existe tarifa, UMA o superficie/metraje válido para calcular el cargo del local %', p_local;
    END IF;

    v_unid := CASE
        WHEN q.periodicidad IN ('DIARIA', 'POR_VISITA') AND v_ini = v_fin THEN 1
        ELSE gesta.fn_unidades_periodo(q.periodicidad, v_ini, v_fin, p_local)
    END;
    v_monto := ROUND(q.monto * v_unid, 2);

    IF v_unid <= 0 OR v_monto <= 0 THEN
        RAISE EXCEPTION 'Las unidades calculadas para el periodo (% a %) son cero', v_ini, v_fin;
    END IF;

    INSERT INTO gesta.cargo (
        local_id, concesion_id, tarifa_id, concepto, periodo_inicio, periodo_fin,
        area_m2_aplicada, metros_lineales_aplicados, metodo_calculo, valor_tarifa_aplicado,
        unidad_valor_aplicada, valor_uma_aplicado, cuota_unidad_aplicada, periodicidad,
        unidades, monto_total
    )
    VALUES (
        p_local, v_conc, q.tarifa_id, 'DERECHO_PISO', v_ini, v_fin,
        q.area_m2, q.metros_lineales, q.metodo, q.valor,
        q.unidad, q.uma_aplicada, q.monto, q.periodicidad,
        ROUND(v_unid, 2), v_monto
    )
    RETURNING id INTO v_cargo_id;

    RETURN v_cargo_id;
END $$;


ALTER FUNCTION gesta.fn_generar_cargo_local(p_local uuid, p_inicio date, p_fin date) OWNER TO gesta_owner;

--
-- TOC entry 925 (class 1255 OID 21080)
-- Name: fn_generar_cargos(bigint, date, date); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.fn_generar_cargos(p_mercado bigint, p_inicio date, p_fin date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $$
DECLARE
    v_usr uuid := gesta.app_usuario();
    v_lote uuid := gen_random_uuid();
    r record;
    t record;
    q record;
    q_sub record;
    v_ini date;
    v_fin date;
    v_dia date;
    v_t_ini date;
    v_t_fin date;
    v_cursor date;
    v_fin_bloque date;
    v_unid numeric;
    v_monto numeric;
    v_motivo text;
    v_motivo_dia text;
    v_n integer;
    v_gen integer := 0;
    v_ya integer := 0;
    v_diaria integer := 0;
    v_tiene boolean;
    v_omit jsonb := '{}'::jsonb;
    v_tot integer := 0;
    v_resumen jsonb;
    v_suma_lote numeric(14,2) := 0;
BEGIN
    IF p_fin < p_inicio THEN RAISE EXCEPTION 'Periodo inválido: % > %', p_inicio, p_fin; END IF;
    IF NOT EXISTS (SELECT 1 FROM gesta.mercado WHERE id = p_mercado) THEN RAISE EXCEPTION 'El mercado % no existe', p_mercado; END IF;
    IF v_usr IS NULL THEN RAISE EXCEPTION 'Se requiere un usuario identificado (app.usuario_id)'; END IF;
    IF NOT gesta.app_es_admin(p_mercado) AND v_usr <> '00000000-0000-0000-0000-000000000001'::uuid THEN
        RAISE EXCEPTION 'Solo el administrador del mercado % o el proceso batch pueden generar cargos', p_mercado;
    END IF;

    PERFORM pg_advisory_xact_lock(hashtextextended('lote_cargos:' || p_mercado::text, 0));
    INSERT INTO gesta.lote_cargos (id, mercado_id, periodo_inicio, periodo_fin, ejecutado_por)
    VALUES (v_lote, p_mercado, p_inicio, p_fin, v_usr);

    PERFORM set_config('gesta.en_lote_cargos', '1', true);

    FOR r IN SELECT lc.id AS local_id, lc.estatus FROM gesta.local_comercial lc
              WHERE lc.mercado_id = p_mercado
                AND lc.estatus NOT IN ('BAJA', 'DESOCUPADO')
              ORDER BY lc.numero_local LOOP
        v_tiene := false;
        FOR t IN SELECT c.id, c.fecha_inicio, c.fecha_fin FROM gesta.concesion c
                  WHERE c.local_id = r.local_id
                    AND c.estado = ANY (gesta.fn_estados_concesion_proceso('FACTURACION'))
                    AND c.fecha_inicio <= p_fin
                    AND COALESCE(c.fecha_fin, 'infinity'::date) >= p_inicio
                  ORDER BY c.fecha_inicio LOOP
            v_tiene := true;
            v_ini := GREATEST(p_inicio, t.fecha_inicio);
            v_fin := LEAST(p_fin, COALESCE(t.fecha_fin, 'infinity'::date));

            SELECT * INTO q FROM gesta.fn_calcular_cuota(r.local_id, v_ini);
            v_motivo := CASE WHEN q.tarifa_id IS NULL THEN 'SIN_TARIFA'
                             WHEN q.metodo IN ('POR_M2','CUOTA_BASE_MAS_EXCEDENTE') AND q.area_m2 IS NULL THEN 'SIN_AREA'
                             WHEN q.metodo = 'POR_METRO_LINEAL' AND q.metros_lineales IS NULL THEN 'SIN_METROS_LINEALES'
                             WHEN q.unidad = 'UMA' AND q.uma_aplicada IS NULL THEN 'SIN_UMA' END;
            IF v_motivo IS NULL AND q.periodicidad = 'DIARIA' AND NOT q.incluir_en_lote THEN
                v_diaria := v_diaria + 1; CONTINUE;
            END IF;

            IF v_motivo IS NULL THEN
                IF q.periodicidad IN ('DIARIA', 'POR_VISITA') THEN
                    FOR v_dia IN
                        SELECT g::date FROM generate_series(v_ini, v_fin, interval '1 day') g
                         WHERE q.periodicidad = 'DIARIA'
                            OR EXISTS (
                                SELECT 1 FROM gesta.asistencia_local al
                                 WHERE al.local_id = r.local_id
                                   AND al.fecha = g::date
                                   AND al.tipo_incidencia IN ('PRESENTE', 'NEGATIVA_PAGO')
                            )
                    LOOP
                        IF EXISTS (
                            SELECT 1 FROM gesta.cargo cp
                             WHERE cp.local_id = r.local_id
                               AND cp.concepto = 'PENALIZACION'
                               AND cp.estado <> 'CANCELADO'
                               AND date_trunc('month', cp.periodo_inicio)::date = date_trunc('month', v_dia)::date
                        ) THEN
                            v_ya := v_ya + 1;
                            CONTINUE;
                        END IF;
                        SELECT * INTO q_sub FROM gesta.fn_calcular_cuota(r.local_id, v_dia);
                        v_motivo_dia := CASE WHEN q_sub.tarifa_id IS NULL THEN 'SIN_TARIFA'
                                             WHEN q_sub.metodo IN ('POR_M2','CUOTA_BASE_MAS_EXCEDENTE') AND q_sub.area_m2 IS NULL THEN 'SIN_AREA'
                                             WHEN q_sub.metodo = 'POR_METRO_LINEAL' AND q_sub.metros_lineales IS NULL THEN 'SIN_METROS_LINEALES'
                                             WHEN q_sub.unidad = 'UMA' AND q_sub.uma_aplicada IS NULL THEN 'SIN_UMA' END;
                        IF v_motivo_dia IS NOT NULL THEN
                            INSERT INTO gesta.lote_cargos_omitido (lote_id, mercado_id, local_id, motivo)
                            VALUES (v_lote, p_mercado, r.local_id, v_motivo_dia) ON CONFLICT DO NOTHING;
                            GET DIAGNOSTICS v_n = ROW_COUNT;
                            IF v_n = 1 THEN
                                v_omit := jsonb_set(v_omit, ARRAY[v_motivo_dia], to_jsonb(COALESCE((v_omit->>v_motivo_dia)::int, 0) + 1));
                                v_tot := v_tot + 1;
                            END IF;
                            CONTINUE;
                        END IF;
                        IF q_sub.periodicidad = 'DIARIA' AND NOT q_sub.incluir_en_lote THEN
                            v_diaria := v_diaria + 1;
                            CONTINUE;
                        END IF;
                        INSERT INTO gesta.cargo (
                            local_id, concesion_id, tarifa_id, concepto, periodo_inicio, periodo_fin,
                            area_m2_aplicada, metros_lineales_aplicados, metodo_calculo, valor_tarifa_aplicado,
                            unidad_valor_aplicada, valor_uma_aplicado, cuota_unidad_aplicada, periodicidad,
                            unidades, monto_total
                        )
                        VALUES (
                            r.local_id, t.id, q_sub.tarifa_id, 'DERECHO_PISO', v_dia, v_dia,
                            q_sub.area_m2, q_sub.metros_lineales, q_sub.metodo, q_sub.valor,
                            q_sub.unidad, q_sub.uma_aplicada, q_sub.monto, q_sub.periodicidad,
                            1, ROUND(q_sub.monto, 2)
                        )
                        ON CONFLICT DO NOTHING;
                        GET DIAGNOSTICS v_n = ROW_COUNT;
                        IF v_n = 1 THEN
                            v_gen := v_gen + 1;
                            v_suma_lote := v_suma_lote + ROUND(q_sub.monto, 2);
                        ELSE
                            v_ya := v_ya + 1;
                        END IF;
                    END LOOP;
                ELSE
                    v_cursor := CASE q.periodicidad
                                    WHEN 'SEMANAL' THEN date_trunc('week', v_ini)::date
                                    WHEN 'MENSUAL' THEN date_trunc('month', v_ini)::date
                                    ELSE date_trunc('year', v_ini)::date
                                END;
                    WHILE v_cursor <= v_fin LOOP
                        v_fin_bloque := CASE q.periodicidad
                                            WHEN 'SEMANAL' THEN (v_cursor + interval '1 week' - interval '1 day')::date
                                            WHEN 'MENSUAL' THEN (v_cursor + interval '1 month' - interval '1 day')::date
                                            ELSE (v_cursor + interval '1 year' - interval '1 day')::date
                                        END;
                        v_t_ini := GREATEST(v_ini, v_cursor);
                        v_t_fin := LEAST(v_fin, v_fin_bloque);

                        IF NOT EXISTS (
                            SELECT 1 FROM gesta.cargo cp
                             WHERE cp.local_id = r.local_id
                               AND cp.concepto = 'PENALIZACION'
                               AND cp.estado <> 'CANCELADO'
                               AND daterange(date_trunc('month', cp.periodo_inicio)::date,
                                             (date_trunc('month', cp.periodo_inicio) + interval '1 month' - interval '1 day')::date, '[]')
                                   && daterange(v_t_ini, v_t_fin, '[]')
                        ) THEN
                            SELECT * INTO q_sub FROM gesta.fn_calcular_cuota(r.local_id, v_t_ini);
                            IF q_sub.monto IS NOT NULL THEN
                                v_unid := gesta.fn_unidades_periodo(q_sub.periodicidad, v_t_ini, v_t_fin, r.local_id);
                                v_monto := ROUND(q_sub.monto * v_unid, 2);
                                IF v_unid > 0 AND v_monto > 0 THEN
                                    INSERT INTO gesta.cargo (
                                        local_id, concesion_id, tarifa_id, concepto, periodo_inicio, periodo_fin,
                                        area_m2_aplicada, metros_lineales_aplicados, metodo_calculo, valor_tarifa_aplicado,
                                        unidad_valor_aplicada, valor_uma_aplicado, cuota_unidad_aplicada, periodicidad,
                                        unidades, monto_total
                                    )
                                    VALUES (
                                        r.local_id, t.id, q_sub.tarifa_id, 'DERECHO_PISO', v_t_ini, v_t_fin,
                                        q_sub.area_m2, q_sub.metros_lineales, q_sub.metodo, q_sub.valor,
                                        q_sub.unidad, q_sub.uma_aplicada, q_sub.monto, q_sub.periodicidad,
                                        ROUND(v_unid, 2), v_monto
                                    )
                                    ON CONFLICT DO NOTHING;
                                    GET DIAGNOSTICS v_n = ROW_COUNT;
                                    IF v_n = 1 THEN
                                        v_gen := v_gen + 1;
                                        v_suma_lote := v_suma_lote + v_monto;
                                    ELSE
                                        v_ya := v_ya + 1;
                                    END IF;
                                END IF;
                            END IF;
                        ELSE
                            v_ya := v_ya + 1;
                        END IF;

                        v_cursor := (v_fin_bloque + 1);
                    END LOOP;
                END IF;
            ELSE
                INSERT INTO gesta.lote_cargos_omitido (lote_id, mercado_id, local_id, motivo)
                VALUES (v_lote, p_mercado, r.local_id, v_motivo) ON CONFLICT DO NOTHING;
                GET DIAGNOSTICS v_n = ROW_COUNT;
                IF v_n = 1 THEN
                    v_omit := jsonb_set(v_omit, ARRAY[v_motivo], to_jsonb(COALESCE((v_omit->>v_motivo)::int, 0) + 1));
                    v_tot := v_tot + 1;
                END IF;
            END IF;
        END LOOP;
        IF NOT v_tiene AND r.estatus = 'OCUPADO' THEN
            INSERT INTO gesta.lote_cargos_omitido (lote_id, mercado_id, local_id, motivo)
            VALUES (v_lote, p_mercado, r.local_id, 'SIN_CONCESION') ON CONFLICT DO NOTHING;
            v_omit := jsonb_set(v_omit, ARRAY['SIN_CONCESION'], to_jsonb(COALESCE((v_omit->>'SIN_CONCESION')::int, 0) + 1));
            v_tot := v_tot + 1;
        END IF;
    END LOOP;

    PERFORM set_config('gesta.en_lote_cargos', '0', true);
    UPDATE gesta.lote_cargos SET generados = v_gen, omitidos = v_tot WHERE id = v_lote;

    v_resumen := jsonb_build_object(
        'lote_id', v_lote, 'mercado_id', p_mercado,
        'periodo_inicio', p_inicio, 'periodo_fin', p_fin,
        'generados', v_gen, 'monto_total_generado', v_suma_lote,
        'ya_existentes', v_ya, 'cobro_inmediato_diaria', v_diaria,
        'omitidos', v_omit, 'total_omitidos', v_tot
    );

    PERFORM gesta.fn_auditoria_agregar('lote_cargos', v_lote::text, 'LOTE', v_usr, NULL, v_resumen, p_mercado, NULL);
    RETURN v_resumen;
END $$;


ALTER FUNCTION gesta.fn_generar_cargos(p_mercado bigint, p_inicio date, p_fin date) OWNER TO gesta_owner;

--
-- TOC entry 859 (class 1255 OID 21086)
-- Name: fn_generar_recargos(bigint, date); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.fn_generar_recargos(p_mercado bigint, p_fecha date DEFAULT NULL::date) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $$
DECLARE
    v_usr uuid := gesta.app_usuario();
    v_mun bigint;
    v_fecha date;
    v_tiene_regla boolean;
    v_total_insertados integer := 0;
    v_filas integer := 0;
    v_fecha_limite date;
    v_mes_ini date;
    v_mes_fin date;
    v_mes_cur date;
    v_fecha_rec date;
    v_base_insoluta numeric(12,2);
    v_rec_prev_insoluto numeric(12,2);
    v_rec_acumulado numeric(12,2);
    v_tope_cargo numeric(12,2);
    v_monto_recargo numeric(12,2);
    r_cg record;
    rm record;
BEGIN
    IF v_usr IS NULL THEN
        RAISE EXCEPTION 'Se requiere un usuario identificado (app.usuario_id)';
    END IF;
    SELECT municipio_id INTO v_mun FROM gesta.mercado WHERE id = p_mercado;
    IF v_mun IS NULL THEN
        RAISE EXCEPTION 'El mercado % no existe', p_mercado;
    END IF;
    IF NOT gesta.app_es_admin(p_mercado)
       AND NOT gesta.app_tiene_rol('TESORERIA', p_mercado)
       AND NOT gesta.app_es_sistema()
       AND v_usr <> '00000000-0000-0000-0000-000000000001'::uuid THEN
        RAISE EXCEPTION 'No tiene permisos para generar recargos en el mercado %', p_mercado;
    END IF;

    v_fecha := COALESCE(p_fecha, gesta.fn_hoy_local(p_mercado));

    SELECT EXISTS (
        SELECT 1 FROM gesta.regla_mora r
         WHERE r.activo
           AND r.municipio_id = v_mun
           AND (r.mercado_id IS NULL OR r.mercado_id = p_mercado)
           AND v_fecha >= r.vigente_desde
           AND v_fecha <= COALESCE(r.vigente_hasta, 'infinity'::date)
    ) INTO v_tiene_regla;

    IF NOT v_tiene_regla THEN
        RAISE EXCEPTION 'RN-FIS-04: No existe regla_mora activa y vigente para el mercado % (municipio %) en la fecha %; configure la regla de mora con Tesorería', p_mercado, v_mun, v_fecha;
    END IF;

    FOR r_cg IN
        SELECT cg.id, cg.local_id, cg.concesion_id, cg.concepto, cg.periodicidad,
               cg.periodo_inicio, cg.periodo_fin, cg.monto_total, cg.monto_pagado
          FROM gesta.cargo cg
          JOIN gesta.local_comercial lc ON lc.id = cg.local_id
         WHERE lc.mercado_id = p_mercado
           AND cg.concepto IN ('DERECHO_PISO', 'PENALIZACION')
           AND cg.estado IN ('PENDIENTE', 'PARCIAL')
           AND (cg.monto_total - cg.monto_pagado) > 0
         ORDER BY cg.periodo_inicio ASC, cg.generado_en ASC
    LOOP
        SELECT r.porcentaje_recargo, r.dias_gracia, r.tipo_calculo, r.tope_maximo_pct
          INTO rm
          FROM gesta.regla_mora r
         WHERE r.activo
           AND r.municipio_id = v_mun
           AND (r.mercado_id IS NULL OR r.mercado_id = p_mercado)
           AND v_fecha >= r.vigente_desde
           AND v_fecha <= COALESCE(r.vigente_hasta, 'infinity'::date)
         ORDER BY (r.mercado_id IS NOT NULL) DESC, r.vigente_desde DESC, r.id DESC
         LIMIT 1;

        v_fecha_limite := CASE
            WHEN r_cg.periodicidad = 'MENSUAL' AND r_cg.concepto IN ('DERECHO_PISO', 'PENALIZACION')
            THEN r_cg.periodo_inicio + GREATEST(rm.dias_gracia - 1, 0)
            ELSE r_cg.periodo_fin + rm.dias_gracia
        END;

        IF v_fecha <= v_fecha_limite THEN
            CONTINUE;
        END IF;

        v_mes_ini := date_trunc('month', v_fecha_limite + 1)::date;
        v_mes_fin := date_trunc('month', v_fecha)::date;
        v_mes_cur := v_mes_ini;

        -- Relleno retroactivo mes a mes para todos los meses vencidos desde que inició la mora hasta v_fecha
        WHILE v_mes_cur <= v_mes_fin LOOP
            v_fecha_rec := GREATEST(
                v_fecha_limite + 1,
                LEAST(
                    (v_mes_cur + GREATEST(rm.dias_gracia, 1) - 1)::date,
                    (v_mes_cur + interval '1 month' - interval '1 day')::date
                )
            );
            IF v_mes_cur = v_mes_fin AND v_fecha < v_fecha_rec THEN
                v_fecha_rec := v_fecha;
            END IF;

            IF v_fecha_rec <= v_fecha AND NOT EXISTS (
                SELECT 1 FROM gesta.cargo rc
                 WHERE rc.cargo_origen_id = r_cg.id
                   AND rc.concepto = 'RECARGO'
                   AND rc.estado <> 'CANCELADO'
                   AND date_trunc('month', rc.periodo_inicio)::date = v_mes_cur
            ) THEN
                SELECT r.porcentaje_recargo, r.dias_gracia, r.tipo_calculo, r.tope_maximo_pct
                  INTO rm
                  FROM gesta.regla_mora r
                 WHERE r.activo
                   AND r.municipio_id = v_mun
                   AND (r.mercado_id IS NULL OR r.mercado_id = p_mercado)
                   AND (
                       (v_fecha_rec >= r.vigente_desde AND v_fecha_rec <= COALESCE(r.vigente_hasta, 'infinity'::date))
                       OR (v_fecha >= r.vigente_desde AND v_fecha <= COALESCE(r.vigente_hasta, 'infinity'::date))
                   )
                 ORDER BY (v_fecha_rec >= r.vigente_desde AND v_fecha_rec <= COALESCE(r.vigente_hasta, 'infinity'::date)) DESC,
                          (r.mercado_id IS NOT NULL) DESC,
                          r.vigente_desde DESC,
                          r.id DESC
                 LIMIT 1;

                SELECT COALESCE(SUM(rc.monto_total), 0),
                       COALESCE(SUM(GREATEST(rc.monto_total - rc.monto_pagado, 0)), 0)
                  INTO v_rec_acumulado, v_rec_prev_insoluto
                  FROM gesta.cargo rc
                 WHERE rc.cargo_origen_id = r_cg.id
                   AND rc.concepto = 'RECARGO'
                   AND rc.estado <> 'CANCELADO';

                v_tope_cargo := ROUND(r_cg.monto_total * rm.tope_maximo_pct / 100.0, 2);
                v_base_insoluta := GREATEST(r_cg.monto_total - r_cg.monto_pagado, 0)
                                   + CASE WHEN rm.tipo_calculo = 'COMPUESTO' THEN v_rec_prev_insoluto ELSE 0 END;

                v_monto_recargo := LEAST(
                    ROUND(v_base_insoluta * rm.porcentaje_recargo / 100.0, 2),
                    GREATEST(v_tope_cargo - v_rec_acumulado, 0)
                );

                IF v_monto_recargo > 0 THEN
                    INSERT INTO gesta.cargo (
                        local_id, concesion_id, concepto, periodo_inicio, periodo_fin,
                        unidades, monto_total, cargo_origen_id
                    )
                    VALUES (
                        r_cg.local_id, r_cg.concesion_id, 'RECARGO', v_fecha_rec, v_fecha_rec,
                        1, v_monto_recargo, r_cg.id
                    )
                    ON CONFLICT DO NOTHING;
                    GET DIAGNOSTICS v_filas = ROW_COUNT;
                    v_total_insertados := v_total_insertados + v_filas;
                END IF;
            END IF;

            v_mes_cur := (v_mes_cur + interval '1 month')::date;
        END LOOP;
    END LOOP;

    RETURN v_total_insertados;
END $$;


ALTER FUNCTION gesta.fn_generar_recargos(p_mercado bigint, p_fecha date) OWNER TO gesta_owner;

--
-- TOC entry 392 (class 1255 OID 21050)
-- Name: fn_hash_auditoria(text, text, text, text, uuid, jsonb, jsonb, timestamp with time zone, bigint, bigint); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.fn_hash_auditoria(p_prev text, p_tabla text, p_registro text, p_accion text, p_usuario uuid, p_antes jsonb, p_despues jsonb, p_ts timestamp with time zone, p_mercado bigint, p_municipio bigint) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'gesta', 'public'
    AS $$
    SELECT encode(
        public.digest(
            jsonb_build_array(
                COALESCE(p_prev, ''),
                p_tabla,
                COALESCE(p_registro, ''),
                p_accion,
                COALESCE(p_usuario::text, ''),
                COALESCE(p_antes, 'null'::jsonb),
                COALESCE(p_despues, 'null'::jsonb),
                COALESCE(p_mercado::text, ''),
                COALESCE(p_municipio::text, ''),
                to_char(p_ts AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US')
            )::text,
            'sha256'
        ),
        'hex'
    )
$$;


ALTER FUNCTION gesta.fn_hash_auditoria(p_prev text, p_tabla text, p_registro text, p_accion text, p_usuario uuid, p_antes jsonb, p_despues jsonb, p_ts timestamp with time zone, p_mercado bigint, p_municipio bigint) OWNER TO gesta_owner;

--
-- TOC entry 356 (class 1255 OID 41231)
-- Name: fn_hash_cobro_canonico(uuid, uuid, uuid, uuid, text, numeric, timestamp with time zone, numeric, gesta.forma_pago); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.fn_hash_cobro_canonico(p_pago_id uuid, p_local uuid, p_cobrador uuid, p_dispositivo uuid, p_folio text, p_monto numeric, p_fecha timestamp with time zone, p_unidades numeric DEFAULT 1, p_forma gesta.forma_pago DEFAULT 'EFECTIVO'::gesta.forma_pago) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER PARALLEL SAFE
    SET search_path TO 'gesta', 'public'
    AS $$
DECLARE
    v_usr uuid := gesta.app_usuario();
    d gesta.dispositivo%ROWTYPE;
BEGIN
    IF p_dispositivo IS NULL THEN
        RAISE EXCEPTION 'RN-FIS-06: Se requiere p_dispositivo para calcular el sello HMAC-SHA256 del cobro';
    END IF;

    SELECT * INTO d FROM gesta.dispositivo WHERE id = p_dispositivo;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'El dispositivo % no existe', p_dispositivo;
    END IF;

    IF NOT (
        gesta.app_es_sistema()
        OR (v_usr IS NOT NULL AND d.usuario_id = v_usr)
        OR (d.mercado_id IS NOT NULL AND gesta.app_es_admin(d.mercado_id))
    ) THEN
        RAISE EXCEPTION 'No tiene permisos para generar sellos HMAC con el dispositivo %', p_dispositivo;
    END IF;

    RETURN gesta.fn_hash_cobro_canonico(
        p_pago_id, p_local, p_cobrador, p_dispositivo,
        p_folio, p_monto, p_fecha, p_unidades, p_forma, d.secreto_hmac
    );
END $$;


ALTER FUNCTION gesta.fn_hash_cobro_canonico(p_pago_id uuid, p_local uuid, p_cobrador uuid, p_dispositivo uuid, p_folio text, p_monto numeric, p_fecha timestamp with time zone, p_unidades numeric, p_forma gesta.forma_pago) OWNER TO gesta_owner;

--
-- TOC entry 362 (class 1255 OID 41286)
-- Name: fn_hash_cobro_canonico(uuid, uuid, uuid, uuid, text, numeric, timestamp with time zone, numeric, gesta.forma_pago, bytea); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.fn_hash_cobro_canonico(p_pago_id uuid, p_local uuid, p_cobrador uuid, p_dispositivo uuid, p_folio text, p_monto numeric, p_fecha timestamp with time zone, p_unidades numeric, p_forma gesta.forma_pago, p_secreto_hmac bytea) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'gesta', 'public'
    AS $$
    SELECT encode(
        public.hmac(
            convert_to(
                gesta.fn_payload_cobro_canonico(
                    p_pago_id, p_local, p_cobrador, p_dispositivo,
                    p_folio, p_monto, p_fecha, p_unidades, p_forma
                ),
                'UTF8'
            ),
            p_secreto_hmac,
            'sha256'
        ),
        'hex'
    )
$$;


ALTER FUNCTION gesta.fn_hash_cobro_canonico(p_pago_id uuid, p_local uuid, p_cobrador uuid, p_dispositivo uuid, p_folio text, p_monto numeric, p_fecha timestamp with time zone, p_unidades numeric, p_forma gesta.forma_pago, p_secreto_hmac bytea) OWNER TO gesta_owner;

