--
-- TOC entry 1193 (class 1255 OID 41027)
-- Name: fn_importar_pagos_excel(bigint, jsonb, text, gesta.canal_cobro); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.fn_importar_pagos_excel(p_mercado bigint, p_filas jsonb, p_nombre_archivo text DEFAULT NULL::text, p_canal gesta.canal_cobro DEFAULT 'IMPORTACION_EXCEL'::gesta.canal_cobro) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $$
DECLARE
    v_usr uuid := gesta.app_usuario();
    v_lote_id uuid;
    v_hash_arch text;
    v_item jsonb;
    v_idx integer := 0;
    v_local uuid;
    v_num_local text;
    v_folio text;
    v_monto numeric(12,2);
    v_fecha timestamptz;
    v_forma gesta.forma_pago;
    v_hash_fila text;
    v_lote_row gesta.lote_importacion_pagos%ROWTYPE;
BEGIN
    IF v_usr IS NULL THEN
        RAISE EXCEPTION 'Se requiere un usuario identificado (app.usuario_id)';
    END IF;
    IF p_mercado IS NULL OR NOT EXISTS (SELECT 1 FROM gesta.mercado WHERE id = p_mercado) THEN
        RAISE EXCEPTION 'El mercado % no existe', p_mercado;
    END IF;
    IF NOT gesta.app_tiene_rol('TESORERIA', p_mercado) AND NOT gesta.app_es_admin(p_mercado) THEN
        RAISE EXCEPTION 'Solo TESORERIA o el Administrador del mercado % pueden importar pagos', p_mercado;
    END IF;
    IF p_filas IS NULL OR jsonb_typeof(p_filas) <> 'array' THEN
        RAISE EXCEPTION 'p_filas debe ser un arreglo JSONB de pagos a importar';
    END IF;

    v_hash_arch := encode(public.digest(p_filas::text, 'sha256'), 'hex');

    INSERT INTO gesta.lote_importacion_pagos (
        mercado_id, canal, nombre_archivo, hash_archivo, ejecutado_por
    )
    VALUES (
        p_mercado, p_canal, NULLIF(btrim(p_nombre_archivo), ''), v_hash_arch, v_usr
    )
    RETURNING id INTO v_lote_id;

    FOR v_item IN SELECT value FROM jsonb_array_elements(p_filas) LOOP
        v_idx := v_idx + 1;
        BEGIN
            v_local := NULLIF(btrim(v_item->>'local_id'), '')::uuid;
            v_num_local := NULLIF(btrim(v_item->>'numero_local'), '');
            IF v_local IS NULL AND v_num_local IS NOT NULL THEN
                SELECT id INTO v_local
                  FROM gesta.local_comercial
                 WHERE mercado_id = p_mercado AND numero_local = v_num_local;
            END IF;
            IF v_local IS NULL THEN
                RAISE EXCEPTION 'Local comercial no encontrado en fila %', v_idx;
            END IF;

            v_folio := v_item->>'folio';
            v_monto := (v_item->>'monto')::numeric;
            v_fecha := COALESCE((v_item->>'fecha_pago')::timestamptz, (v_item->>'fecha')::timestamptz);
            v_forma := COALESCE(NULLIF(btrim(v_item->>'forma_pago'), '')::gesta.forma_pago, 'EFECTIVO'::gesta.forma_pago);
            v_hash_fila := NULLIF(btrim(v_item->>'hash_fila'), '');

            IF v_hash_fila IS NULL THEN
                v_hash_fila := encode(
                    public.digest(
                        concat_ws(
                            '|',
                            'CAJA_EXCEL',
                            p_mercado::text,
                            upper(btrim(COALESCE(v_folio, ''))),
                            gesta.fn_fecha_local(p_mercado, v_fecha)::text,
                            ROUND(v_monto, 2)::text
                        ),
                        'sha256'
                    ),
                    'hex'
                );
            END IF;

            PERFORM gesta.fn_registrar_pago_caja(
                v_local, v_folio, v_monto, v_fecha, v_forma, p_canal, v_lote_id, v_hash_fila
            );
        EXCEPTION WHEN OTHERS THEN
            UPDATE gesta.lote_importacion_pagos
               SET total_filas = total_filas + 1,
                   rechazados = rechazados + 1,
                   detalle_incidencias = detalle_incidencias || jsonb_build_array(
                       jsonb_build_object(
                           'fila', v_idx,
                           'folio', v_item->>'folio',
                           'resultado', 'RECHAZADO',
                           'error', SQLERRM
                       )
                   )
             WHERE id = v_lote_id;
        END;
    END LOOP;

    SELECT * INTO v_lote_row FROM gesta.lote_importacion_pagos WHERE id = v_lote_id;
    RETURN jsonb_build_object(
        'lote_id', v_lote_row.id,
        'mercado_id', v_lote_row.mercado_id,
        'canal', v_lote_row.canal,
        'hash_archivo', v_lote_row.hash_archivo,
        'total_filas', v_lote_row.total_filas,
        'insertados', v_lote_row.insertados,
        'duplicados_omitidos', v_lote_row.duplicados_omitidos,
        'rechazados', v_lote_row.rechazados,
        'monto_total_importado', v_lote_row.monto_total_importado,
        'detalle_incidencias', v_lote_row.detalle_incidencias
    );
END $$;


ALTER FUNCTION gesta.fn_importar_pagos_excel(p_mercado bigint, p_filas jsonb, p_nombre_archivo text, p_canal gesta.canal_cobro) OWNER TO gesta_owner;

--
-- TOC entry 1155 (class 1255 OID 21087)
-- Name: fn_jornadas_sin_liquidar(uuid, bigint); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.fn_jornadas_sin_liquidar(p_cobrador uuid, p_mercado bigint) RETURNS TABLE(fecha_local date, pagos bigint, monto numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $$
BEGIN
    IF app_usuario() IS NULL THEN
        RAISE EXCEPTION 'Se requiere un usuario identificado (app.usuario_id)';
    END IF;
    IF app_usuario() IS DISTINCT FROM p_cobrador AND NOT app_es_admin(p_mercado) AND NOT app_tiene_rol('TESORERIA', p_mercado) THEN
        RAISE EXCEPTION 'No tiene permiso para consultar las jornadas del cobrador %', p_cobrador;
    END IF;
    RETURN QUERY
    SELECT fn_fecha_local(p_mercado, p.fecha_pago), COUNT(*), SUM(p.monto)
      FROM pago p
     WHERE p.cobrador_id = p_cobrador AND p.mercado_id = p_mercado AND p.estado = 'VIGENTE'
       AND p.forma_pago = 'EFECTIVO' AND p.corte_caja_id IS NULL
       AND fn_fecha_local(p_mercado, p.fecha_pago) < fn_hoy_local(p_mercado)
     GROUP BY 1 ORDER BY 1;
END $$;


ALTER FUNCTION gesta.fn_jornadas_sin_liquidar(p_cobrador uuid, p_mercado bigint) OWNER TO gesta_owner;

--
-- TOC entry 1102 (class 1255 OID 21156)
-- Name: fn_login_obtener(public.citext); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.fn_login_obtener(p_username public.citext) RETURNS TABLE(id uuid, password_hash text, activo boolean, debe_cambiar_pass boolean, intentos_fallidos smallint, bloqueado_hasta timestamp with time zone, mfa_habilitado boolean, mfa_secreto_cifrado bytea)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $$
BEGIN
    IF NOT gesta.app_es_auth() THEN
        RAISE EXCEPTION 'Violación de seguridad: función exclusiva del servicio de autenticación (gesta_auth)';
    END IF;

    RETURN QUERY
    SELECT u.id,
           CASE
               WHEN u.activo AND (u.bloqueado_hasta IS NULL OR u.bloqueado_hasta <= now())
               THEN u.password_hash
               ELSE NULL
           END AS password_hash,
           u.activo,
           u.debe_cambiar_pass,
           u.intentos_fallidos,
           u.bloqueado_hasta,
           u.mfa_habilitado,
           CASE
               WHEN u.activo AND (u.bloqueado_hasta IS NULL OR u.bloqueado_hasta <= now()) AND u.mfa_habilitado
               THEN u.mfa_secreto_cifrado
               ELSE NULL
           END AS mfa_secreto_cifrado
      FROM gesta.usuario u
     WHERE u.username = p_username
       AND u.id <> '00000000-0000-0000-0000-000000000001'::uuid;
END $$;


ALTER FUNCTION gesta.fn_login_obtener(p_username public.citext) OWNER TO gesta_owner;

--
-- TOC entry 1310 (class 1255 OID 21157)
-- Name: fn_login_resultado(uuid, boolean, integer, interval); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.fn_login_resultado(p_usuario uuid, p_exito boolean, p_max_intentos integer DEFAULT 5, p_bloqueo interval DEFAULT '00:15:00'::interval) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $$
DECLARE
    v_activo boolean;
    v_bloqueado_hasta timestamptz;
    v_max integer := LEAST(GREATEST(COALESCE(p_max_intentos, 5), 3), 5);
    v_bloq interval := GREATEST(COALESCE(p_bloqueo, '00:15:00'::interval), '00:15:00'::interval);
BEGIN
    IF NOT gesta.app_es_auth() THEN
        RAISE EXCEPTION 'Violación de seguridad: función exclusiva del servicio de autenticación (gesta_auth)';
    END IF;

    IF p_usuario IS NULL OR p_usuario = '00000000-0000-0000-0000-000000000001'::uuid THEN
        RAISE EXCEPTION 'Usuario inválido para registro de resultado de autenticación';
    END IF;

    SELECT u.activo, u.bloqueado_hasta
      INTO v_activo, v_bloqueado_hasta
      FROM gesta.usuario u
     WHERE u.id = p_usuario
       FOR UPDATE;

    IF NOT FOUND THEN
        RETURN;
    END IF;

    IF p_exito THEN
        IF NOT v_activo OR (v_bloqueado_hasta IS NOT NULL AND v_bloqueado_hasta > now()) THEN
            RAISE EXCEPTION 'No se puede autenticar ni desbloquear una cuenta inactiva o con bloqueo temporal vigente';
        END IF;
        UPDATE gesta.usuario
           SET intentos_fallidos = 0,
               bloqueado_hasta = NULL,
               ultimo_acceso = now()
         WHERE id = p_usuario;
    ELSE
        UPDATE gesta.usuario
           SET intentos_fallidos = LEAST(intentos_fallidos + 1, 32000)::smallint,
               bloqueado_hasta = CASE
                   WHEN intentos_fallidos + 1 >= v_max THEN GREATEST(COALESCE(bloqueado_hasta, now()), now() + v_bloq)
                   ELSE bloqueado_hasta
               END
         WHERE id = p_usuario;
    END IF;
END $$;


ALTER FUNCTION gesta.fn_login_resultado(p_usuario uuid, p_exito boolean, p_max_intentos integer, p_bloqueo interval) OWNER TO gesta_owner;

--
-- TOC entry 363 (class 1255 OID 41230)
-- Name: fn_payload_cobro_canonico(uuid, uuid, uuid, uuid, text, numeric, timestamp with time zone, numeric, gesta.forma_pago); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.fn_payload_cobro_canonico(p_pago_id uuid, p_local uuid, p_cobrador uuid, p_dispositivo uuid, p_folio text, p_monto numeric, p_fecha timestamp with time zone, p_unidades numeric DEFAULT 1, p_forma gesta.forma_pago DEFAULT 'EFECTIVO'::gesta.forma_pago) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'gesta', 'public'
    AS $$
    SELECT concat_ws(
        '|',
        lower(p_pago_id::text),
        lower(p_local::text),
        lower(COALESCE(p_cobrador::text, '')),
        lower(COALESCE(p_dispositivo::text, '')),
        upper(btrim(COALESCE(p_folio, ''))),
        to_char(ROUND(p_monto, 2), 'FM999999999990.00'),
        to_char(ROUND(COALESCE(p_unidades, 1), 2), 'FM999999990.00'),
        p_forma::text,
        to_char(p_fecha AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')
    )
$$;


ALTER FUNCTION gesta.fn_payload_cobro_canonico(p_pago_id uuid, p_local uuid, p_cobrador uuid, p_dispositivo uuid, p_folio text, p_monto numeric, p_fecha timestamp with time zone, p_unidades numeric, p_forma gesta.forma_pago) OWNER TO gesta_owner;

--
-- TOC entry 1358 (class 1255 OID 21088)
-- Name: fn_puede_abrir_jornada(uuid, bigint); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.fn_puede_abrir_jornada(p_cobrador uuid, p_mercado bigint) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $$
BEGIN
    IF app_usuario() IS NULL THEN
        RAISE EXCEPTION 'Se requiere un usuario identificado (app.usuario_id)';
    END IF;
    IF app_usuario() IS DISTINCT FROM p_cobrador AND NOT app_es_admin(p_mercado) AND NOT app_tiene_rol('TESORERIA', p_mercado) THEN
        RAISE EXCEPTION 'No tiene permiso para consultar las jornadas del cobrador %', p_cobrador;
    END IF;
    RETURN NOT EXISTS (SELECT 1 FROM fn_jornadas_sin_liquidar(p_cobrador, p_mercado));
END $$;


ALTER FUNCTION gesta.fn_puede_abrir_jornada(p_cobrador uuid, p_mercado bigint) OWNER TO gesta_owner;

--
-- TOC entry 803 (class 1255 OID 20967)
-- Name: fn_recalcular_cargo(uuid); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.fn_recalcular_cargo(p_cargo uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $$
DECLARE v_pagado numeric(12,2); v_total numeric(12,2); v_estado estado_cargo;
BEGIN
    SELECT monto_total, estado INTO v_total, v_estado FROM cargo WHERE id = p_cargo FOR UPDATE;
    SELECT COALESCE(SUM(d.monto_aplicado), 0) INTO v_pagado
      FROM pago_detalle d JOIN pago p ON p.id = d.pago_id
     WHERE d.cargo_id = p_cargo AND p.estado = 'VIGENTE';

    -- Acota monto_pagado a LEAST(v_pagado, v_total); el excedente en pago_detalle
    -- queda disponible de forma no destructiva en v_saldo_favor y det_efectivo
    UPDATE cargo SET
        monto_pagado = LEAST(v_pagado, v_total),
        estado = CASE WHEN v_estado = 'CANCELADO'  THEN v_estado
                      WHEN v_pagado >= v_total     THEN 'PAGADO'::estado_cargo
                      WHEN v_pagado = 0            THEN 'PENDIENTE'::estado_cargo
                      ELSE 'PARCIAL'::estado_cargo END
    WHERE id = p_cargo;
END $$;


ALTER FUNCTION gesta.fn_recalcular_cargo(p_cargo uuid) OWNER TO gesta_owner;

--
-- TOC entry 1352 (class 1255 OID 41232)
-- Name: fn_registrar_cobro_campo(uuid, uuid, uuid, uuid, text, numeric, timestamp with time zone, text, numeric, gesta.forma_pago, public.geometry, date); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.fn_registrar_cobro_campo(p_pago_id uuid, p_local uuid, p_cobrador uuid, p_dispositivo uuid, p_folio text, p_monto_cobrado numeric, p_fecha timestamp with time zone, p_hash_offline text, p_unidades numeric DEFAULT 1, p_forma gesta.forma_pago DEFAULT 'EFECTIVO'::gesta.forma_pago, p_ubicacion public.geometry DEFAULT NULL::public.geometry, p_fecha_inicio_cargo date DEFAULT NULL::date) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $_$
DECLARE
    v_usr uuid := gesta.app_usuario();
    v_id_existente uuid;
    v_id_conflicto uuid;
    v_id_insertado uuid;
    v_mercado bigint;
    v_modelo gesta.modelo_cobro;
    v_estatus gesta.estatus_local;
    v_dias_max smallint;
    q record;
    q_dia record;
    v_cargo uuid;
    v_concesion uuid;
    v_titular uuid;
    v_conc_ini date;
    v_conc_fin date;
    v_dia_corte date;
    v_dia_cargo date;
    v_dia_iter date;
    v_calc numeric(12,2);
    v_rev boolean := false;
    v_motivo text := '';
    v_canal gesta.canal_cobro;
    v_unid numeric;
    v_folio text;
    v_serie_esperada text;
    v_sufijo_consecutivo text;
    v_consecutivo bigint;
    v_fecha_disp timestamptz;
    v_fecha_efectiva timestamptz;
    v_fecha_ok boolean := true;
    d gesta.dispositivo%ROWTYPE;
    v_hash text;
    v_payload text;
    v_hash_esperado text;
    v_ubic public.geometry(Point, 4326);
    r_pend record;
    v_restante numeric(12,2);
    v_abono numeric(12,2);
    v_p_ini date;
    v_p_fin date;
    v_n_per integer;
    v_idx integer;
    v_aplicados_paso2 integer := 0;
    v_est_act gesta.estado_cargo;
    v_saldo_act numeric(12,2);
    v_res_ap text;
BEGIN
    -- 1. Autenticación de usuario y validación de rol al inicio (antes de consultar pagos)
    IF v_usr IS NULL OR p_cobrador IS NULL OR v_usr IS DISTINCT FROM p_cobrador THEN
        RAISE EXCEPTION 'El cobrador indicado no coincide con el usuario autenticado';
    END IF;

    IF p_pago_id IS NULL THEN
        RAISE EXCEPTION 'RN-12: El identificador UUID del pago (p_pago_id) generado en el dispositivo es obligatorio';
    END IF;

    IF p_local IS NULL THEN
        RAISE EXCEPTION 'El local comercial (p_local) es obligatorio';
    END IF;

    SELECT lc.mercado_id, lc.estatus, m.modelo_cobro, mu.dias_max_antiguedad_cobro
      INTO v_mercado, v_estatus, v_modelo, v_dias_max
      FROM gesta.local_comercial lc
      JOIN gesta.mercado m ON m.id = lc.mercado_id
      JOIN gesta.municipio mu ON mu.id = m.municipio_id
     WHERE lc.id = p_local;

    IF v_mercado IS NULL THEN
        RAISE EXCEPTION 'El local % no existe', p_local;
    END IF;

    IF gesta.app_tiene_rol('ADMINISTRADOR', v_mercado) THEN
        v_canal := 'CAMPO_ADMINISTRADOR';
    ELSIF gesta.app_tiene_rol('INSPECTOR', v_mercado) THEN
        v_canal := 'CAMPO_INSPECTOR';
    ELSE
        RAISE EXCEPTION 'El usuario no tiene permiso de cobro en el mercado %', v_mercado;
    END IF;

    IF v_modelo = 'POLITICA_FISCAL_CAJAS' THEN
        RAISE EXCEPTION 'Hallazgo 3.1 / RN-FIS: El mercado % opera bajo el modelo POLITICA_FISCAL_CAJAS; no se permite registrar cobros en campo', v_mercado;
    END IF;

    v_hash := lower(NULLIF(btrim(p_hash_offline), ''));
    IF v_hash IS NULL OR v_hash !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION 'RN-FIS-06: el cobro requiere hash_offline válido (sello HMAC-SHA256 hexadecimal de 64 caracteres)';
    END IF;

    -- 2. Bloqueo transaccional por pago_id y hash_offline + búsqueda de idempotencia acotada al mismo cobrador y mercado
    PERFORM pg_advisory_xact_lock(hashtextextended('cobro_id:' || p_pago_id::text, 0));
    PERFORM pg_advisory_xact_lock(hashtextextended('cobro_hash:' || v_hash, 0));

    SELECT p.id INTO v_id_existente
      FROM gesta.pago p
     WHERE (p.id = p_pago_id OR p.hash_offline = v_hash)
       AND p.cobrador_id = p_cobrador
       AND p.mercado_id = v_mercado
     LIMIT 1;
    IF v_id_existente IS NOT NULL THEN
        RETURN v_id_existente;
    END IF;

    SELECT pc.id INTO v_id_conflicto
      FROM gesta.pago_conflicto_folio pc
     WHERE (pc.pago_id_recibido = p_pago_id OR pc.hash_offline = v_hash)
       AND pc.cobrador_id = p_cobrador
       AND pc.mercado_id = v_mercado
     LIMIT 1;
    IF v_id_conflicto IS NOT NULL THEN
        RETURN p_pago_id;
    END IF;

    IF EXISTS (
        SELECT 1 FROM gesta.pago p
         WHERE p.id = p_pago_id OR p.hash_offline = v_hash
    ) OR EXISTS (
        SELECT 1 FROM gesta.pago_conflicto_folio pc
         WHERE pc.pago_id_recibido = p_pago_id OR pc.hash_offline = v_hash
    ) THEN
        RAISE EXCEPTION 'RN-12 / RN-FIS-06: Identificador o sello de pago no válido para el cobrador y mercado actual';
    END IF;

    IF p_monto_cobrado IS NULL OR p_monto_cobrado <= 0 THEN
        RAISE EXCEPTION 'El monto cobrado debe ser mayor a cero';
    END IF;
    IF p_unidades IS NULL OR p_unidades <= 0 THEN
        RAISE EXCEPTION 'Las unidades cobradas deben ser mayores a cero';
    END IF;
    v_unid := ROUND(p_unidades, 2);

    IF p_fecha IS NULL THEN
        RAISE EXCEPTION 'RN-FIS-06: La fecha y hora UTC de cobro del dispositivo (p_fecha) es obligatoria para verificar el sello digital';
    END IF;
    v_fecha_disp := p_fecha;

    -- 3. Validación estricta de dispositivo, prefijo serie_folio y consecutivo (CU-18 / CU-19)
    IF p_dispositivo IS NULL THEN
        RAISE EXCEPTION 'CU-18: Todo cobro en campo requiere un dispositivo móvil registrado (p_dispositivo)';
    END IF;

    SELECT * INTO d FROM gesta.dispositivo WHERE id = p_dispositivo FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'CU-18: El dispositivo % no existe en el padrón', p_dispositivo;
    END IF;
    IF NOT d.activo THEN
        RAISE EXCEPTION 'CU-18: El dispositivo % se encuentra inactivo', p_dispositivo;
    END IF;
    IF d.usuario_id <> p_cobrador THEN
        RAISE EXCEPTION 'CU-18: El dispositivo % pertenece a otro usuario cobrador', p_dispositivo;
    END IF;
    IF d.mercado_id IS NOT NULL AND d.mercado_id <> v_mercado THEN
        RAISE EXCEPTION 'CU-18: El dispositivo % está asignado a otro mercado (%)', p_dispositivo, d.mercado_id;
    END IF;

    v_folio := upper(NULLIF(btrim(p_folio), ''));
    IF v_folio IS NULL OR length(v_folio) > 40 THEN
        RAISE EXCEPTION 'CU-18: El folio del cobro es obligatorio y no debe exceder 40 caracteres';
    END IF;

    v_serie_esperada := upper(btrim(d.serie_folio));
    IF left(v_folio, length(v_serie_esperada) + 1) <> (v_serie_esperada || '-') THEN
        RAISE EXCEPTION 'CU-18 / CU-19: El folio (%) no coincide con el prefijo de serie del dispositivo (%-CONSECUTIVO)', v_folio, v_serie_esperada;
    END IF;

    v_sufijo_consecutivo := substring(v_folio FROM length(v_serie_esperada) + 2);
    IF v_sufijo_consecutivo IS NULL OR v_sufijo_consecutivo !~ '^[0-9]{1,12}$' THEN
        RAISE EXCEPTION 'CU-18 / CU-19: El consecutivo del folio (%) debe ser numérico entero positivo después del prefijo %-', v_folio, v_serie_esperada;
    END IF;

    v_consecutivo := v_sufijo_consecutivo::bigint;
    IF v_consecutivo <= 0 THEN
        RAISE EXCEPTION 'CU-18 / CU-19: El consecutivo del folio (%) debe ser mayor a cero', v_folio;
    END IF;

    -- 4. Construcción del payload canónico y verificación criptográfica HMAC-SHA256 con clave del dispositivo
    v_payload := gesta.fn_payload_cobro_canonico(
        p_pago_id, p_local, p_cobrador, p_dispositivo,
        v_folio, p_monto_cobrado, v_fecha_disp, v_unid, p_forma
    );
    v_hash_esperado := gesta.fn_hash_cobro_canonico(
        p_pago_id, p_local, p_cobrador, p_dispositivo,
        v_folio, p_monto_cobrado, v_fecha_disp, v_unid, p_forma, d.secreto_hmac
    );

    IF public.digest(convert_to(v_hash, 'UTF8'), 'sha256')
       IS DISTINCT FROM public.digest(convert_to(v_hash_esperado, 'UTF8'), 'sha256') THEN
        RAISE EXCEPTION 'RN-FIS-06: Firma criptográfica HMAC-SHA256 (hash_offline) inválida para el dispositivo %', p_dispositivo;
    END IF;

    -- 5. Normalización de ubicación GPS
    IF p_ubicacion IS NULL THEN
        v_rev := true;
        v_motivo := v_motivo || 'CU-18 5a: Cobro en campo registrado sin señal GPS. ';
        v_ubic := NULL;
    ELSE
        v_ubic := public.ST_Force2D(
            CASE WHEN public.ST_SRID(p_ubicacion) = 0 THEN public.ST_SetSRID(p_ubicacion, 4326)
                 WHEN public.ST_SRID(p_ubicacion) <> 4326 THEN public.ST_Transform(p_ubicacion, 4326)
                 ELSE p_ubicacion END
        );
    END IF;

    -- 6. Bloqueo de folio/mercado, re-verificación de idempotencia post-lock y detección de conflicto de folio (CU-19 2a / 2b)
    PERFORM pg_advisory_xact_lock(hashtextextended('folio_mercado:' || v_mercado::text || ':' || v_folio, 0));

    SELECT p.id INTO v_id_existente
      FROM gesta.pago p
     WHERE (p.id = p_pago_id OR p.hash_offline = v_hash)
       AND p.cobrador_id = p_cobrador
       AND p.mercado_id = v_mercado
     LIMIT 1;
    IF v_id_existente IS NOT NULL THEN
        RETURN v_id_existente;
    END IF;

    SELECT pc.id INTO v_id_conflicto
      FROM gesta.pago_conflicto_folio pc
     WHERE (pc.pago_id_recibido = p_pago_id OR pc.hash_offline = v_hash)
       AND pc.cobrador_id = p_cobrador
       AND pc.mercado_id = v_mercado
     LIMIT 1;
    IF v_id_conflicto IS NOT NULL THEN
        RETURN p_pago_id;
    END IF;

    SELECT id INTO v_id_existente
      FROM gesta.pago
     WHERE (mercado_id = v_mercado AND folio = v_folio)
        OR (dispositivo_id = p_dispositivo AND consecutivo_dispositivo = v_consecutivo)
     LIMIT 1;

    IF v_id_existente IS NOT NULL AND v_id_existente <> p_pago_id THEN
        INSERT INTO gesta.pago_conflicto_folio (
            pago_id_recibido, pago_id_existente, mercado_id, local_id, cobrador_id,
            dispositivo_id, folio, consecutivo_dispositivo, monto, forma_pago,
            fecha_dispositivo, hash_offline, payload_offline, ubicacion_cobro, motivo_conflicto
        )
        VALUES (
            p_pago_id, v_id_existente, v_mercado, p_local, p_cobrador,
            p_dispositivo, v_folio, v_consecutivo, ROUND(p_monto_cobrado, 2), p_forma,
            v_fecha_disp, v_hash, v_payload, v_ubic,
            format('CU-19 2b: Folio %s (consecutivo %s) duplicado con pago_id distinto (%s vs existente %s)',
                   v_folio, v_consecutivo, p_pago_id, v_id_existente)
        )
        ON CONFLICT (pago_id_recibido, hash_offline) DO NOTHING;

        UPDATE gesta.pago
           SET requiere_revision = true,
               motivo_revision = COALESCE(motivo_revision || '; ', '')
                                 || format('CU-19 2b: Conflicto de folio duplicado (%s) recibido con id distinto (%s)', v_folio, p_pago_id)
         WHERE id = v_id_existente;

        RETURN CASE
            WHEN EXISTS (
                SELECT 1 FROM gesta.pago p
                 WHERE p.id = v_id_existente
                   AND p.cobrador_id = p_cobrador
                   AND p.mercado_id = v_mercado
            ) THEN v_id_existente
            ELSE p_pago_id
        END;
    END IF;

    IF v_consecutivo > d.ultimo_consecutivo + 1 THEN
        v_rev := true;
        v_motivo := v_motivo || format('Salto en secuencia de folios del dispositivo %s: anterior %s, recibido %s. ',
                                       v_serie_esperada, d.ultimo_consecutivo, v_consecutivo);
    END IF;

    PERFORM set_config('gesta.dispositivo_autorizado', p_dispositivo::text, true);
    UPDATE gesta.dispositivo
       SET ultimo_consecutivo = GREATEST(ultimo_consecutivo, v_consecutivo),
           ultima_sincronizacion = now()
     WHERE id = p_dispositivo;
    PERFORM set_config('gesta.dispositivo_autorizado', '', true);

    -- 7. Validación de la fecha del dispositivo
    IF v_fecha_disp > now() + interval '5 minutes' THEN
        v_fecha_ok := false;
        v_fecha_efectiva := now();
        v_rev := true;
        v_motivo := v_motivo || format('Fecha del dispositivo en el futuro (%s): se aplicó fecha del servidor (%s) para periodo y corte. ',
                                       v_fecha_disp, v_fecha_efectiva);
    ELSIF v_fecha_disp < now() - make_interval(days => v_dias_max) THEN
        v_fecha_ok := false;
        v_fecha_efectiva := now();
        v_rev := true;
        v_motivo := v_motivo || format('Fecha del dispositivo fuera de ventana (> %s días: %s): se aplicó fecha del servidor (%s) para periodo y corte. ',
                                       v_dias_max, v_fecha_disp, v_fecha_efectiva);
    ELSE
        v_fecha_efectiva := v_fecha_disp;
    END IF;

    v_dia_corte := gesta.fn_fecha_local(v_mercado, v_fecha_efectiva);
    v_dia_cargo := COALESCE(p_fecha_inicio_cargo, v_dia_corte);

    IF EXISTS (
        SELECT 1 FROM gesta.pago pe
         WHERE pe.cobrador_id = p_cobrador
           AND pe.mercado_id = v_mercado
           AND pe.estado = 'VIGENTE'
           AND pe.forma_pago = 'EFECTIVO'
           AND pe.corte_caja_id IS NULL
           AND gesta.fn_fecha_local(v_mercado, pe.fecha_pago) < v_dia_corte
    ) THEN
        v_rev := true;
        v_motivo := v_motivo || 'RN-FIS-05: cobro con efectivo de jornadas anteriores sin liquidar (corte pendiente). ';
    END IF;

    SELECT id, titular_persona_id, fecha_inicio, fecha_fin
      INTO v_concesion, v_titular, v_conc_ini, v_conc_fin
      FROM gesta.concesion
     WHERE local_id = p_local
       AND estado IN ('VIGENTE', 'SUSPENDIDA', 'CEDIDA')
       AND fecha_inicio <= v_dia_cargo
       AND COALESCE(fecha_fin, 'infinity'::date) >= v_dia_cargo
     ORDER BY (estado = 'VIGENTE') DESC, es_temporal_feria DESC, fecha_inicio DESC
     LIMIT 1;

    SELECT * INTO q FROM gesta.fn_calcular_cuota(p_local, v_dia_cargo);
    IF q.periodicidad = 'POR_VISITA' AND v_estatus NOT IN ('BAJA', 'DESOCUPADO') THEN
        INSERT INTO gesta.asistencia_local (local_id, fecha, registrado_por, tipo_incidencia, ubicacion)
        VALUES (p_local, v_dia_cargo, p_cobrador, 'PRESENTE', v_ubic)
        ON CONFLICT (local_id, fecha) DO UPDATE SET tipo_incidencia = 'PRESENTE';
        SELECT * INTO q FROM gesta.fn_calcular_cuota(p_local, v_dia_cargo);
    END IF;

    IF q.periodicidad = 'DIARIA' AND v_estatus NOT IN ('BAJA', 'DESOCUPADO') THEN
        PERFORM gesta.fn_aplicar_penalizacion_morosidad_diaria(p_local, v_dia_cargo);
    END IF;

    IF q.monto IS NULL THEN
        v_rev := true;
        v_motivo := v_motivo || 'Sin tarifa, UMA del mercado, área o metros lineales aplicables: pago conservado sin cargo. ';
        v_calc := 0;
    ELSE
        v_calc := ROUND(q.monto * v_unid, 2);
        IF ROUND(p_monto_cobrado, 2) <> v_calc AND NOT EXISTS (
            SELECT 1 FROM gesta.cargo
             WHERE local_id = p_local
               AND estado IN ('PENDIENTE', 'PARCIAL')
               AND (
                   (v_concesion IS NOT NULL AND (concesion_id = v_concesion OR (concesion_id IS NULL AND periodo_inicio >= v_conc_ini AND periodo_fin <= COALESCE(v_conc_fin, 'infinity'::date))))
                OR (v_concesion IS NULL AND concesion_id IS NULL)
               )
        ) THEN
            v_rev := true;
            v_motivo := v_motivo || format('Diferencia servidor/dispositivo: calculado %s vs cobrado %s. ', v_calc, ROUND(p_monto_cobrado, 2));
        END IF;
    END IF;

    INSERT INTO gesta.pago (
        id, mercado_id, local_id, persona_pagador_id, cobrador_id, dispositivo_id,
        canal, folio, folio_impreso, consecutivo_dispositivo, monto, forma_pago,
        fecha_pago, fecha_dispositivo, sincronizado_en, ubicacion_cobro,
        requiere_revision, motivo_revision, hash_offline, payload_offline
    )
    VALUES (
        p_pago_id, v_mercado, p_local, v_titular, p_cobrador, p_dispositivo,
        v_canal, v_folio, v_folio, v_consecutivo, ROUND(p_monto_cobrado, 2), p_forma,
        v_fecha_efectiva, v_fecha_disp, now(), v_ubic,
        v_rev, NULLIF(btrim(v_motivo), ''), v_hash, v_payload
    )
    ON CONFLICT DO NOTHING
    RETURNING id INTO v_id_insertado;

    IF v_id_insertado IS NULL THEN
        SELECT p.id INTO v_id_existente
          FROM gesta.pago p
         WHERE (p.id = p_pago_id OR p.hash_offline = v_hash)
           AND p.cobrador_id = p_cobrador
           AND p.mercado_id = v_mercado
         LIMIT 1;
        IF v_id_existente IS NOT NULL THEN
            RETURN v_id_existente;
        END IF;
        RAISE EXCEPTION 'RN-12 / RN-FIS-06: Conflicto de concurrencia o colisión de identificador/sello al registrar el pago %', p_pago_id;
    END IF;

    -- Paso 1: Prelación estricta acotada al rango de la concesión vigente (RN-08)
    v_restante := ROUND(p_monto_cobrado, 2);
    FOR r_pend IN
        SELECT id
          FROM gesta.cargo
         WHERE local_id = p_local
           AND estado IN ('PENDIENTE', 'PARCIAL')
           AND (
               (v_concesion IS NOT NULL AND (concesion_id = v_concesion OR (concesion_id IS NULL AND periodo_inicio >= v_conc_ini AND periodo_fin <= COALESCE(v_conc_fin, 'infinity'::date))))
            OR (v_concesion IS NULL AND concesion_id IS NULL)
           )
         ORDER BY (concepto = 'RECARGO') ASC,
                  periodo_inicio ASC,
                  generado_en ASC
    LOOP
        EXIT WHEN v_restante <= 0;
        SELECT estado, GREATEST(monto_total - monto_pagado, 0)
          INTO v_est_act, v_saldo_act
          FROM gesta.cargo
         WHERE id = r_pend.id;

        IF v_est_act NOT IN ('PENDIENTE', 'PARCIAL') OR v_saldo_act <= 0 THEN
            CONTINUE;
        END IF;

        v_abono := LEAST(v_restante, v_saldo_act);
        IF v_abono > 0 THEN
            v_res_ap := gesta.fn_aplicar_pago(p_pago_id, r_pend.id, v_abono);
            IF v_res_ap IN ('APLICADO', 'APLICADO_PARCIAL') THEN
                v_restante := v_restante - v_abono;
            END IF;
        END IF;
    END LOOP;

    -- Paso 2: Generar cargos del periodo a partir de v_dia_cargo
    IF v_restante > 0 AND v_calc > 0 AND v_estatus NOT IN ('BAJA', 'DESOCUPADO') THEN
        v_n_per := GREATEST(CEIL(v_unid)::int, 1);

        IF q.periodicidad = 'DIARIA' THEN
            FOR v_idx IN 0..(v_n_per + 6) LOOP
                EXIT WHEN v_restante <= 0 OR v_aplicados_paso2 >= v_n_per;
                v_dia_iter := (v_dia_cargo + (v_idx * interval '1 day'))::date;
                EXIT WHEN v_conc_fin IS NOT NULL AND v_dia_iter > v_conc_fin;
                v_cargo := NULL;

                SELECT id INTO v_cargo FROM gesta.cargo
                 WHERE local_id = p_local AND estado <> 'CANCELADO'
                   AND (
                       (v_concesion IS NOT NULL AND (concesion_id = v_concesion OR (concesion_id IS NULL AND periodo_inicio >= v_conc_ini AND periodo_fin <= COALESCE(v_conc_fin, 'infinity'::date))))
                    OR (v_concesion IS NULL AND concesion_id IS NULL)
                   )
                   AND (
                       (concepto = 'DERECHO_PISO' AND v_dia_iter BETWEEN periodo_inicio AND periodo_fin)
                    OR (concepto = 'PENALIZACION' AND date_trunc('month', periodo_inicio)::date = date_trunc('month', v_dia_iter)::date)
                   )
                 ORDER BY (concepto = 'PENALIZACION') DESC, periodo_inicio DESC
                 LIMIT 1;

                IF v_cargo IS NULL THEN
                    SELECT * INTO q_dia FROM gesta.fn_calcular_cuota(p_local, v_dia_iter);
                    IF q_dia.monto IS NOT NULL AND q_dia.monto > 0 THEN
                        BEGIN
                            INSERT INTO gesta.cargo (
                                local_id, concesion_id, tarifa_id, concepto, periodo_inicio, periodo_fin,
                                area_m2_aplicada, metros_lineales_aplicados, metodo_calculo, valor_tarifa_aplicado,
                                unidad_valor_aplicada, valor_uma_aplicado, cuota_unidad_aplicada, periodicidad,
                                unidades, monto_total
                            )
                            VALUES (
                                p_local, v_concesion, q_dia.tarifa_id, 'DERECHO_PISO', v_dia_iter, v_dia_iter,
                                q_dia.area_m2, q_dia.metros_lineales, q_dia.metodo, q_dia.valor,
                                q_dia.unidad, q_dia.uma_aplicada, q_dia.monto, q_dia.periodicidad,
                                1, ROUND(q_dia.monto, 2)
                            )
                            RETURNING id INTO v_cargo;
                        EXCEPTION WHEN exclusion_violation THEN
                            SELECT id INTO v_cargo FROM gesta.cargo
                             WHERE local_id = p_local AND concepto = 'DERECHO_PISO' AND estado <> 'CANCELADO'
                               AND daterange(periodo_inicio, periodo_fin, '[]') && daterange(v_dia_iter, v_dia_iter, '[]')
                             LIMIT 1;
                        END;
                    END IF;
                END IF;

                IF v_cargo IS NOT NULL THEN
                    SELECT estado, GREATEST(monto_total - monto_pagado, 0)
                      INTO v_est_act, v_saldo_act
                      FROM gesta.cargo
                     WHERE id = v_cargo;

                    IF v_est_act IN ('PENDIENTE', 'PARCIAL') AND v_saldo_act > 0 THEN
                        v_abono := LEAST(v_restante, v_saldo_act);
                        v_res_ap := gesta.fn_aplicar_pago(p_pago_id, v_cargo, v_abono);
                        IF v_res_ap IN ('APLICADO', 'APLICADO_PARCIAL') THEN
                            v_restante := v_restante - v_abono;
                            v_aplicados_paso2 := v_aplicados_paso2 + 1;
                        END IF;
                    END IF;
                END IF;
            END LOOP;
        ELSE
            SELECT id INTO v_cargo FROM gesta.cargo
             WHERE local_id = p_local AND estado <> 'CANCELADO'
               AND (
                   (v_concesion IS NOT NULL AND (concesion_id = v_concesion OR (concesion_id IS NULL AND periodo_inicio >= v_conc_ini AND periodo_fin <= COALESCE(v_conc_fin, 'infinity'::date))))
                OR (v_concesion IS NULL AND concesion_id IS NULL)
               )
               AND (
                   (concepto = 'DERECHO_PISO' AND v_dia_cargo BETWEEN periodo_inicio AND periodo_fin)
                OR (concepto = 'PENALIZACION' AND date_trunc('month', periodo_inicio)::date = date_trunc('month', v_dia_cargo)::date)
               )
             ORDER BY (concepto = 'PENALIZACION') DESC, periodo_inicio DESC
             LIMIT 1;

            IF v_cargo IS NULL THEN
                IF q.periodicidad = 'POR_VISITA' THEN
                    v_p_ini := v_dia_cargo;
                    v_p_fin := v_dia_cargo;
                ELSIF q.periodicidad = 'SEMANAL' THEN
                    v_p_ini := date_trunc('week', v_dia_cargo)::date;
                    v_p_fin := (v_p_ini + (v_n_per * interval '1 week') - interval '1 day')::date;
                ELSIF q.periodicidad = 'MENSUAL' THEN
                    v_p_ini := date_trunc('month', v_dia_cargo)::date;
                    v_p_fin := (v_p_ini + (v_n_per * interval '1 month') - interval '1 day')::date;
                ELSE
                    v_p_ini := date_trunc('year', v_dia_cargo)::date;
                    v_p_fin := (v_p_ini + (v_n_per * interval '1 year') - interval '1 day')::date;
                END IF;

                IF v_conc_ini IS NOT NULL THEN v_p_ini := GREATEST(v_p_ini, v_conc_ini); END IF;
                IF v_conc_fin IS NOT NULL THEN v_p_fin := LEAST(v_p_fin, v_conc_fin); END IF;

                IF v_p_fin >= v_p_ini THEN
                    BEGIN
                        INSERT INTO gesta.cargo (
                            local_id, concesion_id, tarifa_id, concepto, periodo_inicio, periodo_fin,
                            area_m2_aplicada, metros_lineales_aplicados, metodo_calculo, valor_tarifa_aplicado,
                            unidad_valor_aplicada, valor_uma_aplicado, cuota_unidad_aplicada, periodicidad,
                            unidades, monto_total
                        )
                        VALUES (
                            p_local, v_concesion, q.tarifa_id, 'DERECHO_PISO', v_p_ini, v_p_fin,
                            q.area_m2, q.metros_lineales, q.metodo, q.valor,
                            q.unidad, q.uma_aplicada, q.monto, q.periodicidad,
                            v_unid, v_calc
                        )
                        RETURNING id INTO v_cargo;
                    EXCEPTION WHEN exclusion_violation THEN
                        SELECT id INTO v_cargo FROM gesta.cargo
                         WHERE local_id = p_local AND concepto = 'DERECHO_PISO' AND estado <> 'CANCELADO'
                           AND daterange(periodo_inicio, periodo_fin, '[]') && daterange(v_p_ini, v_p_fin, '[]')
                         LIMIT 1;
                    END;
                END IF;
            END IF;

            IF v_cargo IS NOT NULL THEN
                SELECT estado, GREATEST(monto_total - monto_pagado, 0)
                  INTO v_est_act, v_saldo_act
                  FROM gesta.cargo
                 WHERE id = v_cargo;

                IF v_est_act IN ('PENDIENTE', 'PARCIAL') AND v_saldo_act > 0 THEN
                    v_abono := LEAST(v_restante, v_saldo_act);
                    v_res_ap := gesta.fn_aplicar_pago(p_pago_id, v_cargo, v_abono);
                    IF v_res_ap IN ('APLICADO', 'APLICADO_PARCIAL') THEN
                        v_restante := v_restante - v_abono;
                    END IF;
                END IF;
            END IF;
        END IF;
    ELSIF v_restante > 0 AND v_estatus IN ('BAJA', 'DESOCUPADO') THEN
        UPDATE gesta.pago
           SET requiere_revision = true,
               motivo_revision = COALESCE(motivo_revision || '; ', '')
                                 || 'Pago en campo para local en estatus ' || v_estatus
         WHERE id = p_pago_id;
    END IF;

    IF v_restante > 0 THEN
        UPDATE gesta.pago
           SET requiere_revision = true,
               motivo_revision = CASE
                   WHEN motivo_revision LIKE '%saldo a favor%' THEN motivo_revision
                   ELSE COALESCE(motivo_revision || '; ', '')
                        || CASE WHEN v_restante = ROUND(p_monto_cobrado, 2)
                                THEN 'Cargo ya cubierto: pago sin aplicar (saldo a favor)'
                                ELSE 'Excedente sin aplicar (saldo a favor)' END
               END
         WHERE id = p_pago_id;
    END IF;

    RETURN p_pago_id;
END $_$;


ALTER FUNCTION gesta.fn_registrar_cobro_campo(p_pago_id uuid, p_local uuid, p_cobrador uuid, p_dispositivo uuid, p_folio text, p_monto_cobrado numeric, p_fecha timestamp with time zone, p_hash_offline text, p_unidades numeric, p_forma gesta.forma_pago, p_ubicacion public.geometry, p_fecha_inicio_cargo date) OWNER TO gesta_owner;

--
-- TOC entry 720 (class 1255 OID 41255)
-- Name: fn_registrar_deposito_hacienda(bigint, date, numeric, character varying, uuid[], date, date, text); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.fn_registrar_deposito_hacienda(p_mercado bigint, p_fecha_deposito date, p_monto_depositado numeric, p_referencia character varying, p_pagos_ids uuid[], p_periodo_inicio date DEFAULT NULL::date, p_periodo_fin date DEFAULT NULL::date, p_justificacion_diferencia text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $_$
DECLARE
    v_usr uuid := gesta.app_usuario();
    v_dep_id uuid := gen_random_uuid();
    v_suma_pagos numeric(12,2);
    v_n_pagos integer;
BEGIN
    IF v_usr IS NULL THEN
        RAISE EXCEPTION 'Se requiere un usuario identificado (app.usuario_id)';
    END IF;
    IF NOT gesta.app_es_admin(p_mercado) AND NOT gesta.app_tiene_rol('TESORERIA', p_mercado) THEN
        RAISE EXCEPTION 'CU-23: Solo el Administrador del mercado % o TESORERIA pueden registrar depósitos a Hacienda', p_mercado;
    END IF;
    IF p_monto_depositado IS NULL OR p_monto_depositado <= 0 THEN
        RAISE EXCEPTION 'CU-23: El monto depositado debe ser mayor a cero';
    END IF;
    IF p_pagos_ids IS NULL OR cardinality(p_pagos_ids) = 0 THEN
        RAISE EXCEPTION 'CU-23: Debe seleccionar al menos un pago en efectivo vigente para vincular al depósito';
    END IF;

    SELECT COALESCE(SUM(p.monto), 0), COUNT(*)
      INTO v_suma_pagos, v_n_pagos
      FROM gesta.pago p
     WHERE p.id = ANY (p_pagos_ids)
       AND p.mercado_id = p_mercado
       AND p.estado = 'VIGENTE'
       AND p.forma_pago = 'EFECTIVO'
       AND p.deposito_id IS NULL
       AND (p.canal IN ('CAJA_POLITICA_FISCAL', 'IMPORTACION_EXCEL') OR p.corte_caja_id IS NOT NULL);

    IF v_n_pagos <> cardinality(ARRAY(SELECT DISTINCT unnest(p_pagos_ids))) THEN
        RAISE EXCEPTION 'CU-23 / RN-16: Uno o más pagos seleccionados no existen, pertenecen a otro mercado, ya fueron depositados, no son en EFECTIVO vigente o no han liquidado su corte de caja diario';
    END IF;

    IF ROUND(p_monto_depositado, 2) <> v_suma_pagos
       AND (p_justificacion_diferencia IS NULL OR length(btrim(p_justificacion_diferencia)) = 0) THEN
        RAISE EXCEPTION 'CU-23 3a: El monto depositado ($%) difiere de la suma de los pagos seleccionados ($%); debe proporcionar justificacion_diferencia',
                        ROUND(p_monto_depositado, 2), v_suma_pagos;
    END IF;

    INSERT INTO gesta.deposito_hacienda (
        id, mercado_id, fecha_deposito, periodo_inicio, periodo_fin,
        monto_depositado, referencia, depositado_por, justificacion_diferencia
    )
    VALUES (
        v_dep_id, p_mercado, p_fecha_deposito, p_periodo_inicio, p_periodo_fin,
        ROUND(p_monto_depositado, 2), NULLIF(btrim(p_referencia), ''), v_usr,
        NULLIF(btrim(p_justificacion_diferencia), '')
    );

    UPDATE gesta.pago
       SET deposito_id = v_dep_id
     WHERE id = ANY (p_pagos_ids);

    RETURN v_dep_id;
END $_$;


ALTER FUNCTION gesta.fn_registrar_deposito_hacienda(p_mercado bigint, p_fecha_deposito date, p_monto_depositado numeric, p_referencia character varying, p_pagos_ids uuid[], p_periodo_inicio date, p_periodo_fin date, p_justificacion_diferencia text) OWNER TO gesta_owner;

--
-- TOC entry 545 (class 1255 OID 41236)
-- Name: fn_registrar_pago_caja(uuid, text, numeric, timestamp with time zone, gesta.forma_pago, gesta.canal_cobro, uuid, text); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.fn_registrar_pago_caja(p_local uuid, p_folio text, p_monto numeric, p_fecha timestamp with time zone DEFAULT now(), p_forma gesta.forma_pago DEFAULT 'EFECTIVO'::gesta.forma_pago, p_canal gesta.canal_cobro DEFAULT 'CAJA_POLITICA_FISCAL'::gesta.canal_cobro, p_lote_id uuid DEFAULT NULL::uuid, p_hash_fila text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $$
DECLARE
    v_usr uuid := gesta.app_usuario();
    v_pago_id uuid := gen_random_uuid();
    v_pago_exist gesta.pago%ROWTYPE;
    v_mercado bigint;
    v_modelo gesta.modelo_cobro;
    v_estatus gesta.estatus_local;
    v_dias_max smallint;
    v_concesion uuid;
    v_titular uuid;
    v_conc_ini date;
    v_conc_fin date;
    v_fecha timestamptz;
    v_dia date;
    v_folio text;
    v_payload text;
    v_hash text;
    v_rev boolean := false;
    v_motivo text := '';
    v_restante numeric(12,2);
    v_abono numeric(12,2);
    v_est_act gesta.estado_cargo;
    v_saldo_act numeric(12,2);
    v_res_ap text;
    v_cargo uuid;
    v_p_ini date;
    v_p_fin date;
    v_unid_per numeric;
    v_monto_cargo numeric(12,2);
    q record;
    r_pend record;
BEGIN
    IF v_usr IS NULL THEN
        RAISE EXCEPTION 'Se requiere un usuario identificado (app.usuario_id)';
    END IF;
    IF p_canal NOT IN ('CAJA_POLITICA_FISCAL', 'IMPORTACION_EXCEL') THEN
        RAISE EXCEPTION 'Canal % inválido para cobro en caja/importación; utilice CAJA_POLITICA_FISCAL o IMPORTACION_EXCEL', p_canal;
    END IF;
    IF p_monto IS NULL OR p_monto <= 0 THEN
        RAISE EXCEPTION 'El monto del pago debe ser mayor a cero';
    END IF;
    IF p_fecha IS NULL THEN
        RAISE EXCEPTION 'La fecha de pago es obligatoria';
    END IF;

    v_folio := NULLIF(btrim(p_folio), '');
    IF v_folio IS NULL OR length(v_folio) > 40 THEN
        RAISE EXCEPTION 'CU-25: El folio oficial es obligatorio (máx. 40 caracteres) para registrar pagos de caja o importación Excel';
    END IF;

    SELECT lc.mercado_id, lc.estatus, m.modelo_cobro, mu.dias_max_antiguedad_cobro
      INTO v_mercado, v_estatus, v_modelo, v_dias_max
      FROM gesta.local_comercial lc
      JOIN gesta.mercado m ON m.id = lc.mercado_id
      JOIN gesta.municipio mu ON mu.id = m.municipio_id
     WHERE lc.id = p_local;

    IF v_mercado IS NULL THEN
        RAISE EXCEPTION 'El local % no existe', p_local;
    END IF;
    IF v_modelo = 'ADMINISTRACION_DIRECTA' THEN
        RAISE EXCEPTION 'Hallazgo 3.1 / RN-FIS: El mercado % opera exclusivamente bajo el modelo ADMINISTRACION_DIRECTA; no se permite el cobro por caja ni importación de Política Fiscal', v_mercado;
    END IF;

    IF NOT gesta.app_tiene_rol('TESORERIA', v_mercado)
       AND NOT gesta.app_es_admin(v_mercado) THEN
        RAISE EXCEPTION 'Solo TESORERIA o el Administrador del mercado % pueden registrar pagos de caja/Excel', v_mercado;
    END IF;

    v_fecha := p_fecha;
    IF v_fecha > now() + interval '5 minutes' THEN
        RAISE EXCEPTION 'Fecha de pago inválida: no se permiten fechas en el futuro (%)', v_fecha;
    END IF;
    IF v_fecha < now() - make_interval(days => v_dias_max) THEN
        RAISE EXCEPTION 'Fecha de pago fuera del límite permitido: excede la antigüedad máxima de % días configurada para el municipio (%)', v_dias_max, v_fecha;
    END IF;

    v_dia := gesta.fn_fecha_local(v_mercado, v_fecha);
    v_payload := concat_ws(
        '|',
        'CAJA_EXCEL',
        v_mercado::text,
        upper(v_folio),
        v_dia::text,
        ROUND(p_monto, 2)::text
    );
    v_hash := encode(
        public.digest(convert_to(v_payload, 'UTF8'), 'sha256'),
        'hex'
    );

    IF p_hash_fila IS NOT NULL AND btrim(p_hash_fila) <> '' THEN
        IF lower(btrim(p_hash_fila)) <> v_hash THEN
            RAISE EXCEPTION 'El hash_fila proporcionado (%) no coincide con el SHA-256 del payload canónico de caja/Excel (%)', lower(btrim(p_hash_fila)), v_hash;
        END IF;
    END IF;

    PERFORM pg_advisory_xact_lock(hashtextextended('pago_caja:' || v_mercado::text || ':' || upper(v_folio), 0));

    SELECT * INTO v_pago_exist
      FROM gesta.pago p
     WHERE p.hash_offline = v_hash
        OR (p.mercado_id = v_mercado AND upper(btrim(p.folio)) = upper(v_folio))
     LIMIT 1;

    IF FOUND THEN
        IF v_pago_exist.mercado_id = v_mercado
           AND v_pago_exist.local_id = p_local
           AND upper(btrim(v_pago_exist.folio)) = upper(v_folio)
           AND gesta.fn_fecha_local(v_mercado, v_pago_exist.fecha_pago) = v_dia
           AND v_pago_exist.monto = ROUND(p_monto, 2) THEN
            RETURN v_pago_exist.id;
        ELSE
            RAISE EXCEPTION 'CU-25: Conflicto de llave natural en mercado %: el folio % ya existe asociado a otro local, fecha o monto', v_mercado, v_folio;
        END IF;
    END IF;

    SELECT id, titular_persona_id, fecha_inicio, fecha_fin
      INTO v_concesion, v_titular, v_conc_ini, v_conc_fin
      FROM gesta.concesion
     WHERE local_id = p_local
       AND estado IN ('VIGENTE', 'SUSPENDIDA', 'CEDIDA')
       AND fecha_inicio <= v_dia
       AND COALESCE(fecha_fin, 'infinity'::date) >= v_dia
     ORDER BY (estado = 'VIGENTE') DESC, fecha_inicio DESC
     LIMIT 1;

    SELECT * INTO q FROM gesta.fn_calcular_cuota(p_local, v_dia);
    IF q.periodicidad = 'DIARIA' AND v_estatus NOT IN ('BAJA', 'DESOCUPADO') THEN
        PERFORM gesta.fn_aplicar_penalizacion_morosidad_diaria(p_local, v_dia);
    END IF;

    INSERT INTO gesta.pago (
        id, mercado_id, local_id, persona_pagador_id, cobrador_id, canal,
        folio, folio_impreso, hash_offline, payload_offline, monto,
        forma_pago, fecha_pago, sincronizado_en, requiere_revision, motivo_revision
    )
    VALUES (
        v_pago_id, v_mercado, p_local, v_titular, v_usr, p_canal,
        v_folio, v_folio, v_hash, v_payload, ROUND(p_monto, 2),
        p_forma, v_fecha, now(), v_rev, NULLIF(btrim(v_motivo), '')
    );

    v_restante := ROUND(p_monto, 2);
    FOR r_pend IN
        SELECT id
          FROM gesta.cargo
         WHERE local_id = p_local
           AND estado IN ('PENDIENTE', 'PARCIAL')
           AND (
               (v_concesion IS NOT NULL AND (concesion_id = v_concesion OR (concesion_id IS NULL AND periodo_inicio >= v_conc_ini AND periodo_fin <= COALESCE(v_conc_fin, 'infinity'::date))))
            OR (v_concesion IS NULL AND concesion_id IS NULL)
           )
         ORDER BY (concepto = 'RECARGO') ASC,
                  periodo_inicio ASC,
                  generado_en ASC
    LOOP
        EXIT WHEN v_restante <= 0;
        SELECT estado, GREATEST(monto_total - monto_pagado, 0)
          INTO v_est_act, v_saldo_act
          FROM gesta.cargo WHERE id = r_pend.id;
        IF v_est_act NOT IN ('PENDIENTE', 'PARCIAL') OR v_saldo_act <= 0 THEN CONTINUE; END IF;
        v_abono := LEAST(v_restante, v_saldo_act);
        IF v_abono > 0 THEN
            v_res_ap := gesta.fn_aplicar_pago(v_pago_id, r_pend.id, v_abono);
            IF v_res_ap IN ('APLICADO', 'APLICADO_PARCIAL') THEN
                v_restante := v_restante - v_abono;
            END IF;
        END IF;
    END LOOP;

    IF v_restante > 0 AND v_estatus NOT IN ('BAJA', 'DESOCUPADO') AND q.monto IS NOT NULL AND q.monto > 0 THEN
        SELECT id INTO v_cargo FROM gesta.cargo
         WHERE local_id = p_local AND estado <> 'CANCELADO'
           AND (
               (v_concesion IS NOT NULL AND (concesion_id = v_concesion OR (concesion_id IS NULL AND periodo_inicio >= v_conc_ini AND periodo_fin <= COALESCE(v_conc_fin, 'infinity'::date))))
            OR (v_concesion IS NULL AND concesion_id IS NULL)
           )
           AND (
               (concepto = 'DERECHO_PISO' AND v_dia BETWEEN periodo_inicio AND periodo_fin)
            OR (concepto = 'PENALIZACION' AND date_trunc('month', periodo_inicio)::date = date_trunc('month', v_dia)::date)
           )
         ORDER BY (concepto = 'PENALIZACION') DESC, periodo_inicio DESC
         LIMIT 1;

        IF v_cargo IS NULL THEN
            IF q.periodicidad IN ('DIARIA', 'POR_VISITA') THEN
                v_p_ini := v_dia; v_p_fin := v_dia;
            ELSIF q.periodicidad = 'SEMANAL' THEN
                v_p_ini := date_trunc('week', v_dia)::date;
                v_p_fin := (v_p_ini + interval '1 week' - interval '1 day')::date;
            ELSIF q.periodicidad = 'MENSUAL' THEN
                v_p_ini := date_trunc('month', v_dia)::date;
                v_p_fin := (v_p_ini + interval '1 month' - interval '1 day')::date;
            ELSE
                v_p_ini := date_trunc('year', v_dia)::date;
                v_p_fin := (v_p_ini + interval '1 year' - interval '1 day')::date;
            END IF;

            IF v_conc_ini IS NOT NULL THEN v_p_ini := GREATEST(v_p_ini, v_conc_ini); END IF;
            IF v_conc_fin IS NOT NULL THEN v_p_fin := LEAST(v_p_fin, v_conc_fin); END IF;

            IF v_p_fin >= v_p_ini THEN
                v_unid_per := CASE WHEN q.periodicidad IN ('DIARIA', 'POR_VISITA') THEN 1
                                   ELSE gesta.fn_unidades_periodo(q.periodicidad, v_p_ini, v_p_fin, p_local) END;
                v_monto_cargo := ROUND(q.monto * v_unid_per, 2);
                IF v_unid_per > 0 AND v_monto_cargo > 0 THEN
                    BEGIN
                        INSERT INTO gesta.cargo (
                            local_id, concesion_id, tarifa_id, concepto, periodo_inicio, periodo_fin,
                            area_m2_aplicada, metros_lineales_aplicados, metodo_calculo, valor_tarifa_aplicado,
                            unidad_valor_aplicada, valor_uma_aplicado, cuota_unidad_aplicada, periodicidad,
                            unidades, monto_total
                        )
                        VALUES (
                            p_local, v_concesion, q.tarifa_id, 'DERECHO_PISO', v_p_ini, v_p_fin,
                            q.area_m2, q.metros_lineales, q.metodo, q.valor,
                            q.unidad, q.uma_aplicada, q.monto, q.periodicidad,
                            ROUND(v_unid_per, 2), v_monto_cargo
                        )
                        RETURNING id INTO v_cargo;
                    EXCEPTION WHEN exclusion_violation THEN
                        SELECT id INTO v_cargo FROM gesta.cargo
                         WHERE local_id = p_local AND concepto = 'DERECHO_PISO' AND estado <> 'CANCELADO'
                           AND daterange(periodo_inicio, periodo_fin, '[]') && daterange(v_p_ini, v_p_fin, '[]')
                         LIMIT 1;
                    END;
                END IF;
            END IF;
        END IF;

        IF v_cargo IS NOT NULL THEN
            SELECT estado, GREATEST(monto_total - monto_pagado, 0)
              INTO v_est_act, v_saldo_act
              FROM gesta.cargo WHERE id = v_cargo;
            IF v_est_act IN ('PENDIENTE', 'PARCIAL') AND v_saldo_act > 0 THEN
                v_abono := LEAST(v_restante, v_saldo_act);
                v_res_ap := gesta.fn_aplicar_pago(v_pago_id, v_cargo, v_abono);
                IF v_res_ap IN ('APLICADO', 'APLICADO_PARCIAL') THEN
                    v_restante := v_restante - v_abono;
                END IF;
            END IF;
        END IF;
    END IF;

    IF v_restante > 0 THEN
        UPDATE gesta.pago
           SET requiere_revision = true,
               motivo_revision = CASE
                   WHEN motivo_revision LIKE '%saldo a favor%' THEN motivo_revision
                   ELSE COALESCE(motivo_revision || '; ', '')
                        || CASE WHEN v_restante = ROUND(p_monto, 2)
                                THEN 'Pago en caja/Excel sin cargo aplicable (saldo a favor)'
                                ELSE 'Excedente en caja/Excel sin aplicar (saldo a favor)' END
               END
         WHERE id = v_pago_id;
    END IF;

    RETURN v_pago_id;
END $$;


ALTER FUNCTION gesta.fn_registrar_pago_caja(p_local uuid, p_folio text, p_monto numeric, p_fecha timestamp with time zone, p_forma gesta.forma_pago, p_canal gesta.canal_cobro, p_lote_id uuid, p_hash_fila text) OWNER TO gesta_owner;

--
-- TOC entry 824 (class 1255 OID 41240)
-- Name: fn_registrar_permiso_feria_express(uuid, uuid, bigint, date, smallint, uuid, uuid, text, numeric, text, gesta.forma_pago, public.geometry, timestamp with time zone); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.fn_registrar_permiso_feria_express(p_local uuid, p_titular_persona uuid, p_giro_id bigint, p_fecha_inicio date, p_dias smallint, p_pago_id uuid, p_dispositivo uuid, p_folio text, p_monto_cobrado numeric, p_hash_offline text, p_forma gesta.forma_pago DEFAULT 'EFECTIVO'::gesta.forma_pago, p_ubicacion public.geometry DEFAULT NULL::public.geometry, p_fecha_cobro timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $$
DECLARE
    v_usr uuid := gesta.app_usuario();
    v_mercado bigint;
    v_mun bigint;
    v_modelo gesta.modelo_cobro;
    v_tipo_esp gesta.tipo_espacio;
    v_geom_local public.geometry;
    v_ubic_norm public.geometry(Point, 4326);
    v_geom_eval public.geometry;
    v_zona_conflicto text;
    v_fecha_fin date;
    v_concesion_id uuid;
    v_ts_cobro timestamptz;
    v_dia_iter date;
    v_cargo_id uuid;
    q_feria record;
BEGIN
    IF v_usr IS NULL THEN
        RAISE EXCEPTION 'Se requiere un usuario identificado (app.usuario_id)';
    END IF;
    IF p_fecha_inicio IS NULL THEN
        RAISE EXCEPTION 'Art. 34 Ley de Ingresos: La fecha de inicio (p_fecha_inicio) del permiso de feria es obligatoria';
    END IF;
    IF p_dias IS NULL OR p_dias < 1 OR p_dias > 30 THEN
        RAISE EXCEPTION 'Art. 34 Ley de Ingresos: La temporalidad del permiso de feria o festividad debe ser de 1 a 30 días naturales';
    END IF;

    SELECT lc.mercado_id, m.municipio_id, m.modelo_cobro, lc.tipo_espacio, lc.geom
      INTO v_mercado, v_mun, v_modelo, v_tipo_esp, v_geom_local
      FROM gesta.local_comercial lc
      JOIN gesta.mercado m ON m.id = lc.mercado_id
     WHERE lc.id = p_local;

    IF v_mercado IS NULL THEN
        RAISE EXCEPTION 'El espacio comercial % no existe', p_local;
    END IF;
    IF v_modelo = 'POLITICA_FISCAL_CAJAS' THEN
        RAISE EXCEPTION 'Hallazgo 3.1 / RN-FIS: El mercado % opera bajo el modelo POLITICA_FISCAL_CAJAS; no permite expedir cobros de feria en campo', v_mercado;
    END IF;
    IF NOT gesta.app_es_admin(v_mercado) AND NOT gesta.app_tiene_rol('INSPECTOR', v_mercado) THEN
        RAISE EXCEPTION 'No tiene permisos para expedir permisos temporales de feria en el mercado %', v_mercado;
    END IF;

    IF p_ubicacion IS NOT NULL THEN
        v_ubic_norm := public.ST_Force2D(
            CASE WHEN public.ST_SRID(p_ubicacion) = 0 THEN public.ST_SetSRID(p_ubicacion, 4326)
                 WHEN public.ST_SRID(p_ubicacion) <> 4326 THEN public.ST_Transform(p_ubicacion, 4326)
                 ELSE p_ubicacion END
        );
    END IF;

    IF v_geom_local IS NULL AND v_ubic_norm IS NULL THEN
        RAISE EXCEPTION 'RN-PAD-03 / RN-PAD-04: Para expedir un permiso temporal de feria se requiere georreferenciación (polígono del espacio o ubicación GPS en campo)';
    END IF;

    -- Validación de restricciones espaciales PostGIS sobre la geometría del espacio y la ubicación GPS
    FOR v_geom_eval IN
        SELECT g FROM unnest(ARRAY[v_geom_local, v_ubic_norm::public.geometry]) AS g
         WHERE g IS NOT NULL
    LOOP
        IF v_tipo_esp = 'FIJO' AND EXISTS (
            SELECT 1 FROM gesta.zona_restringida z
             WHERE z.municipio_id = v_mun
               AND z.tipo = 'PRIMER_CUADRO'
               AND public.ST_Intersects(z.geom, v_geom_eval)
        ) THEN
            RAISE EXCEPTION 'RN-PAD-04: Prohibido expedir permiso en modalidad FIJO dentro del polígono del Primer Cuadro';
        END IF;

        SELECT z.tipo::text || COALESCE(' (' || z.nombre || ')', '')
          INTO v_zona_conflicto
          FROM gesta.zona_restringida z
         WHERE z.municipio_id = v_mun
           AND z.tipo <> 'PRIMER_CUADRO'
           AND public.ST_DWithin(z.geom, v_geom_eval, 0.002)
           AND public.ST_DWithin(z.geom::public.geography, v_geom_eval::public.geography, 100)
         LIMIT 1;

        IF v_zona_conflicto IS NOT NULL THEN
            RAISE EXCEPTION 'RN-PAD-03: Prohibido expedir permiso temporal de feria a menos de 100 m de zona restringida: %', v_zona_conflicto;
        END IF;
    END LOOP;

    v_fecha_fin := (p_fecha_inicio + (p_dias - 1));

    SELECT id INTO v_concesion_id
      FROM gesta.concesion
     WHERE local_id = p_local
       AND titular_persona_id = p_titular_persona
       AND es_temporal_feria
       AND fecha_inicio = p_fecha_inicio
       AND fecha_fin = v_fecha_fin
       AND estado = 'VIGENTE'
     LIMIT 1;

    IF v_concesion_id IS NULL THEN
        INSERT INTO gesta.concesion (
            local_id, titular_persona_id, giro_id, estado, es_formal,
            es_temporal_feria, fecha_inicio, fecha_fin, observaciones
        )
        VALUES (
            p_local, p_titular_persona, p_giro_id, 'VIGENTE', false,
            true, p_fecha_inicio, v_fecha_fin, 'Permiso temporal de feria/festividad expedido en campo (Art. 34)'
        )
        RETURNING id INTO v_concesion_id;
    END IF;

    -- Generación explícita de los cargos del permiso desde p_fecha_inicio hasta v_fecha_fin
    SELECT * INTO q_feria FROM gesta.fn_calcular_cuota(p_local, p_fecha_inicio);
    IF q_feria.monto IS NOT NULL AND q_feria.monto > 0 THEN
        IF q_feria.periodicidad IN ('DIARIA', 'POR_VISITA') THEN
            FOR v_dia_iter IN
                SELECT g::date FROM generate_series(p_fecha_inicio, v_fecha_fin, interval '1 day') AS g
            LOOP
                IF q_feria.periodicidad = 'POR_VISITA' THEN
                    INSERT INTO gesta.asistencia_local (local_id, fecha, registrado_por, tipo_incidencia, ubicacion)
                    VALUES (p_local, v_dia_iter, v_usr, 'PRESENTE', v_ubic_norm)
                    ON CONFLICT (local_id, fecha) DO UPDATE SET tipo_incidencia = 'PRESENTE';
                END IF;

                SELECT * INTO q_feria FROM gesta.fn_calcular_cuota(p_local, v_dia_iter);
                IF q_feria.monto IS NOT NULL AND q_feria.monto > 0 THEN
                    BEGIN
                        INSERT INTO gesta.cargo (
                            local_id, concesion_id, tarifa_id, concepto, periodo_inicio, periodo_fin,
                            area_m2_aplicada, metros_lineales_aplicados, metodo_calculo, valor_tarifa_aplicado,
                            unidad_valor_aplicada, valor_uma_aplicado, cuota_unidad_aplicada, periodicidad,
                            unidades, monto_total
                        )
                        VALUES (
                            p_local, v_concesion_id, q_feria.tarifa_id, 'DERECHO_PISO', v_dia_iter, v_dia_iter,
                            q_feria.area_m2, q_feria.metros_lineales, q_feria.metodo, q_feria.valor,
                            q_feria.unidad, q_feria.uma_aplicada, ROUND(q_feria.monto, 2), q_feria.periodicidad,
                            1, ROUND(q_feria.monto, 2)
                        )
                        ON CONFLICT DO NOTHING;
                    EXCEPTION WHEN exclusion_violation THEN
                        NULL;
                    END;
                END IF;
            END LOOP;
        ELSE
            BEGIN
                INSERT INTO gesta.cargo (
                    local_id, concesion_id, tarifa_id, concepto, periodo_inicio, periodo_fin,
                    area_m2_aplicada, metros_lineales_aplicados, metodo_calculo, valor_tarifa_aplicado,
                    unidad_valor_aplicada, valor_uma_aplicado, cuota_unidad_aplicada, periodicidad,
                    unidades, monto_total
                )
                VALUES (
                    p_local, v_concesion_id, q_feria.tarifa_id, 'DERECHO_PISO', p_fecha_inicio, v_fecha_fin,
                    q_feria.area_m2, q_feria.metros_lineales, q_feria.metodo, q_feria.valor,
                    q_feria.unidad, q_feria.uma_aplicada, ROUND(q_feria.monto, 2), q_feria.periodicidad,
                    p_dias::numeric, ROUND(q_feria.monto * p_dias, 2)
                )
                ON CONFLICT DO NOTHING;
            EXCEPTION WHEN exclusion_violation THEN
                NULL;
            END;
        END IF;
    END IF;

    v_ts_cobro := COALESCE(p_fecha_cobro, now());

    RETURN gesta.fn_registrar_cobro_campo(
        p_pago_id,
        p_local,
        v_usr,
        p_dispositivo,
        p_folio,
        p_monto_cobrado,
        v_ts_cobro,
        p_hash_offline,
        p_dias::numeric,
        p_forma,
        v_ubic_norm,
        p_fecha_inicio
    );
END $$;


ALTER FUNCTION gesta.fn_registrar_permiso_feria_express(p_local uuid, p_titular_persona uuid, p_giro_id bigint, p_fecha_inicio date, p_dias smallint, p_pago_id uuid, p_dispositivo uuid, p_folio text, p_monto_cobrado numeric, p_hash_offline text, p_forma gesta.forma_pago, p_ubicacion public.geometry, p_fecha_cobro timestamp with time zone) OWNER TO gesta_owner;

--
-- TOC entry 301 (class 1255 OID 40973)
-- Name: fn_resolver_revision_pago(uuid, text); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.fn_resolver_revision_pago(p_pago uuid, p_motivo text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $$
DECLARE
    v gesta.pago%ROWTYPE;
    v_usr uuid := gesta.app_usuario();
BEGIN
    IF v_usr IS NULL THEN
        RAISE EXCEPTION 'Se requiere un usuario identificado (app.usuario_id)';
    END IF;
    IF p_motivo IS NULL OR btrim(p_motivo) = '' THEN
        RAISE EXCEPTION 'El motivo de resolución de la revisión es obligatorio';
    END IF;

    SELECT * INTO v FROM gesta.pago WHERE id = p_pago FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'El pago % no existe', p_pago;
    END IF;
    IF NOT v.requiere_revision THEN
        RAISE EXCEPTION 'El pago % no se encuentra marcado para revisión', p_pago;
    END IF;
    IF NOT gesta.app_autoriza_ajuste_fiscal(v.mercado_id) THEN
        RAISE EXCEPTION 'RN-FIS-05: Solo TESORERIA o un Administrador Municipal puede resolver pagos en revisión';
    END IF;
    IF v.cobrador_id IS NOT NULL AND v.cobrador_id = v_usr THEN
        RAISE EXCEPTION 'RN-FIS-05: Segregación de funciones: el cobrador que registró el pago no puede resolver su propia revisión';
    END IF;

    PERFORM set_config('gesta.revision_pago_autorizada', v.id::text, true);
    UPDATE gesta.pago
       SET requiere_revision = false,
           motivo_revision = COALESCE(motivo_revision || ' | ', '')
                             || 'RESUELTO (' || to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI"Z"')
                             || ' por ' || v_usr::text || '): ' || btrim(p_motivo)
     WHERE id = p_pago;
    PERFORM set_config('gesta.revision_pago_autorizada', '', true);
END $$;


ALTER FUNCTION gesta.fn_resolver_revision_pago(p_pago uuid, p_motivo text) OWNER TO gesta_owner;

--
-- TOC entry 1111 (class 1255 OID 41092)
-- Name: fn_reubicar_local(uuid, bigint, bigint, character varying, public.geometry, text, character varying); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.fn_reubicar_local(p_local uuid, p_nuevo_mercado bigint, p_nueva_zona bigint, p_nuevo_numero character varying, p_nueva_geom public.geometry, p_motivo text, p_numero_expediente character varying DEFAULT NULL::character varying) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $$
DECLARE
    v_usr uuid := gesta.app_usuario();
    v_loc gesta.local_comercial%ROWTYPE;
    v_conc gesta.concesion%ROWTYPE;
    v_tiene_conc boolean := false;
    v_tiene_movs boolean := false;
    v_dest_mercado bigint;
    v_dest_numero varchar(20);
    v_nuevo_local_id uuid;
    v_hoy date;
    r_sup record;
BEGIN
    IF v_usr IS NULL THEN
        RAISE EXCEPTION 'Se requiere un usuario identificado (app.usuario_id)';
    END IF;
    IF p_motivo IS NULL OR btrim(p_motivo) = '' THEN
        RAISE EXCEPTION 'El motivo formal de la reubicación es obligatorio';
    END IF;

    SELECT * INTO v_loc FROM gesta.local_comercial WHERE id = p_local FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'El local % no existe', p_local;
    END IF;

    v_dest_mercado := COALESCE(p_nuevo_mercado, v_loc.mercado_id);
    v_dest_numero := COALESCE(NULLIF(btrim(p_nuevo_numero), ''), v_loc.numero_local);

    IF NOT gesta.app_es_admin(v_loc.mercado_id) OR NOT gesta.app_es_admin(v_dest_mercado) THEN
        RAISE EXCEPTION 'Se requiere permiso de ADMINISTRADOR sobre el mercado origen (%) y destino (%) para ejecutar la reubicación formal', v_loc.mercado_id, v_dest_mercado;
    END IF;

    v_tiene_movs := EXISTS (SELECT 1 FROM gesta.cargo WHERE local_id = v_loc.id)
                 OR EXISTS (SELECT 1 FROM gesta.pago WHERE local_id = v_loc.id)
                 OR EXISTS (SELECT 1 FROM gesta.cargo_ajuste WHERE local_id = v_loc.id)
                 OR EXISTS (SELECT 1 FROM gesta.lote_cargos_omitido WHERE local_id = v_loc.id);

    IF v_dest_mercado = v_loc.mercado_id OR NOT v_tiene_movs THEN
        PERFORM set_config('gesta.reubicacion_autorizada', v_loc.id::text, true);
        UPDATE gesta.local_comercial
           SET mercado_id = v_dest_mercado,
               zona_id = p_nueva_zona,
               numero_local = v_dest_numero,
               geom = COALESCE(p_nueva_geom, geom),
               notas = COALESCE(notas || ' | ', '') || 'Reubicado formalmente: ' || btrim(p_motivo)
         WHERE id = v_loc.id;
        PERFORM set_config('gesta.reubicacion_autorizada', '', true);

        v_nuevo_local_id := v_loc.id;
    ELSE
        -- Si cambia de mercado y existen movimientos financieros históricos, el local origen conserva
        -- su mercado_id inmutable (pasa a BAJA) y se crea un nuevo registro en el mercado destino
        v_hoy := gesta.fn_hoy_local(v_loc.mercado_id);
        SELECT * INTO v_conc
          FROM gesta.concesion
         WHERE local_id = v_loc.id
           AND estado IN ('VIGENTE', 'SUSPENDIDA')
         ORDER BY (estado = 'VIGENTE') DESC, fecha_inicio DESC
         LIMIT 1
         FOR UPDATE;
        v_tiene_conc := FOUND;

        IF v_tiene_conc THEN
            UPDATE gesta.concesion
               SET estado = 'CEDIDA',
                   fecha_fin = GREATEST(v_hoy - 1, fecha_inicio),
                   observaciones = COALESCE(observaciones || ' | ', '') || 'Cerrada por reubicación formal a mercado ' || v_dest_mercado
             WHERE id = v_conc.id;
        END IF;

        UPDATE gesta.local_comercial
           SET estatus = 'BAJA',
               notas = COALESCE(notas || ' | ', '') || 'Baja por reubicación formal a mercado ' || v_dest_mercado || ': ' || btrim(p_motivo)
         WHERE id = v_loc.id;

        INSERT INTO gesta.local_comercial (
            mercado_id, zona_id, numero_local, nombre_comercial, folio_tarjeton,
            tipo_espacio, estatus, giro_observado_id, geom, area_oficial_m2,
            area_oficial_motivo, metros_lineales, notas
        )
        VALUES (
            v_dest_mercado, p_nueva_zona, v_dest_numero, v_loc.nombre_comercial, v_loc.folio_tarjeton,
            v_loc.tipo_espacio, CASE WHEN v_tiene_conc THEN 'OCUPADO'::gesta.estatus_local ELSE 'DESOCUPADO'::gesta.estatus_local END,
            v_loc.giro_observado_id, COALESCE(p_nueva_geom, v_loc.geom), v_loc.area_oficial_m2,
            v_loc.area_oficial_motivo, v_loc.metros_lineales,
            'Creado por reubicación formal desde local ' || v_loc.id || ': ' || btrim(p_motivo)
        )
        RETURNING id INTO v_nuevo_local_id;

        IF v_tiene_conc THEN
            INSERT INTO gesta.concesion (
                local_id, titular_persona_id, ocupante_persona_id, giro_id, estado,
                es_formal, es_temporal_feria, numero_expediente, fecha_dictamen,
                fecha_inicio, fecha_fin, observaciones
            )
            VALUES (
                v_nuevo_local_id, v_conc.titular_persona_id, v_conc.ocupante_persona_id, v_conc.giro_id, v_conc.estado,
                v_conc.es_formal, v_conc.es_temporal_feria, COALESCE(NULLIF(btrim(p_numero_expediente), ''), v_conc.numero_expediente),
                v_conc.fecha_dictamen, v_hoy,
                CASE WHEN v_conc.fecha_fin IS NOT NULL AND v_conc.fecha_fin >= v_hoy THEN v_conc.fecha_fin ELSE NULL END,
                'Continuidad de concesión por reubicación administrativa desde local ' || v_loc.id
            )
            RETURNING * INTO v_conc;

            FOR r_sup IN
                SELECT persona_id, parentesco
                  FROM gesta.concesion_suplente
                 WHERE concesion_id = (
                     SELECT id FROM gesta.concesion
                      WHERE local_id = v_loc.id
                      ORDER BY creado_en DESC LIMIT 1
                 )
            LOOP
                INSERT INTO gesta.concesion_suplente (concesion_id, persona_id, parentesco)
                VALUES (v_conc.id, r_sup.persona_id, r_sup.parentesco)
                ON CONFLICT DO NOTHING;
            END LOOP;
        END IF;
    END IF;

    INSERT INTO gesta.reubicacion_local (
        local_origen_id, local_destino_id, mercado_id, mercado_origen_id, mercado_destino_id,
        zona_origen_id, zona_destino_id, numero_local_origen, numero_local_destino,
        geom_anterior, geom_nueva, numero_expediente, motivo, autorizado_por
    )
    VALUES (
        v_loc.id, v_nuevo_local_id, v_loc.mercado_id, v_loc.mercado_id, v_dest_mercado,
        v_loc.zona_id, p_nueva_zona, v_loc.numero_local, v_dest_numero,
        v_loc.geom, COALESCE(p_nueva_geom, v_loc.geom),
        NULLIF(btrim(p_numero_expediente), ''), btrim(p_motivo), v_usr
    );

    RETURN v_nuevo_local_id;
END $$;


ALTER FUNCTION gesta.fn_reubicar_local(p_local uuid, p_nuevo_mercado bigint, p_nueva_zona bigint, p_nuevo_numero character varying, p_nueva_geom public.geometry, p_motivo text, p_numero_expediente character varying) OWNER TO gesta_owner;

--
-- TOC entry 395 (class 1255 OID 21158)
-- Name: fn_sesion_emitir(uuid, uuid, text, timestamp with time zone, inet, text); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.fn_sesion_emitir(p_usuario uuid, p_dispositivo uuid, p_token_hash text, p_expira timestamp with time zone, p_ip inet, p_user_agent text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $$
DECLARE
    v_id uuid;
BEGIN
    IF NOT gesta.app_es_auth() THEN
        RAISE EXCEPTION 'Violación de seguridad: función exclusiva del servicio de autenticación (gesta_auth)';
    END IF;

    IF p_usuario IS NULL
       OR p_usuario = '00000000-0000-0000-0000-000000000001'::uuid
       OR NOT EXISTS (
           SELECT 1 FROM gesta.usuario u
            WHERE u.id = p_usuario
              AND u.activo
              AND (u.bloqueado_hasta IS NULL OR u.bloqueado_hasta <= now())
       ) THEN
        RAISE EXCEPTION 'No se puede emitir sesión para un usuario inexistente, inactivo, bloqueado o de sistema';
    END IF;

    IF p_dispositivo IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM gesta.dispositivo d
         WHERE d.id = p_dispositivo
           AND d.usuario_id = p_usuario
           AND d.activo
    ) THEN
        RAISE EXCEPTION 'No se puede emitir sesión: el dispositivo % no existe, está inactivo o pertenece a otro usuario', p_dispositivo;
    END IF;

    INSERT INTO gesta.sesion_refresh (usuario_id, dispositivo_id, token_hash, expira_en, ip, user_agent)
    VALUES (p_usuario, p_dispositivo, p_token_hash, p_expira, p_ip, p_user_agent)
    RETURNING id INTO v_id;

    RETURN v_id;
END $$;


ALTER FUNCTION gesta.fn_sesion_emitir(p_usuario uuid, p_dispositivo uuid, p_token_hash text, p_expira timestamp with time zone, p_ip inet, p_user_agent text) OWNER TO gesta_owner;

--
-- TOC entry 891 (class 1255 OID 21160)
-- Name: fn_sesion_revocar(text); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.fn_sesion_revocar(p_token_hash text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $$
BEGIN
    IF NOT gesta.app_es_auth() THEN
        RAISE EXCEPTION 'Violación de seguridad: función exclusiva del servicio de autenticación (gesta_auth)';
    END IF;

    UPDATE gesta.sesion_refresh
       SET revocado_en = now()
     WHERE token_hash = p_token_hash
       AND revocado_en IS NULL;
    RETURN FOUND;
END $$;


ALTER FUNCTION gesta.fn_sesion_revocar(p_token_hash text) OWNER TO gesta_owner;

--
-- TOC entry 1060 (class 1255 OID 21159)
-- Name: fn_sesion_validar(text); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.fn_sesion_validar(p_token_hash text) RETURNS TABLE(sesion_id uuid, usuario_id uuid, dispositivo_id uuid, expira_en timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $$
BEGIN
    IF NOT gesta.app_es_auth() THEN
        RAISE EXCEPTION 'Violación de seguridad: función exclusiva del servicio de autenticación (gesta_auth)';
    END IF;

    RETURN QUERY
    SELECT s.id, s.usuario_id, s.dispositivo_id, s.expira_en
      FROM gesta.sesion_refresh s
      JOIN gesta.usuario u ON u.id = s.usuario_id
      LEFT JOIN gesta.dispositivo d ON d.id = s.dispositivo_id
     WHERE s.token_hash = p_token_hash
       AND s.revocado_en IS NULL
       AND s.expira_en > now()
       AND u.activo
       AND (u.bloqueado_hasta IS NULL OR u.bloqueado_hasta <= now())
       AND (s.dispositivo_id IS NULL OR (d.activo AND d.usuario_id = s.usuario_id));
END $$;


ALTER FUNCTION gesta.fn_sesion_validar(p_token_hash text) OWNER TO gesta_owner;

--
-- TOC entry 915 (class 1255 OID 20313)
-- Name: fn_uma_sugerida(date); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.fn_uma_sugerida(p_fecha date) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $$
    SELECT valor_diario FROM uma_oficial
     WHERE vigente_desde <= p_fecha AND p_fecha < (vigente_desde + interval '1 year')::date
     ORDER BY vigente_desde DESC LIMIT 1
$$;


ALTER FUNCTION gesta.fn_uma_sugerida(p_fecha date) OWNER TO gesta_owner;

--
-- TOC entry 1394 (class 1255 OID 20603)
-- Name: fn_unidades_periodo(gesta.periodicidad, date, date, uuid); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.fn_unidades_periodo(p_per gesta.periodicidad, p_inicio date, p_fin date, p_local uuid DEFAULT NULL::uuid) RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $$
DECLARE
    v_meses numeric := 0;
    v_cur date;
    v_fin_mes date;
    v_tramo_ini date;
    v_tramo_fin date;
    v_dias_mes numeric;
BEGIN
    IF p_fin < p_inicio THEN RETURN 0; END IF;

    IF p_local IS NOT NULL
       AND NOT gesta.app_es_sistema()
       AND NOT gesta.app_opera_en_local(p_local)
       AND NOT gesta.app_es_locatario_de(p_local) THEN
        RAISE EXCEPTION 'No tiene permisos para consultar asistencias o unidades de periodo del local %', p_local;
    END IF;

    IF p_per = 'DIARIA'  THEN RETURN (p_fin - p_inicio + 1); END IF;
    IF p_per = 'SEMANAL' THEN RETURN CEIL((p_fin - p_inicio + 1) / 7.0); END IF;
    IF p_per = 'POR_VISITA' THEN
        IF p_local IS NULL THEN RETURN 0; END IF;
        RETURN (SELECT COUNT(*) FROM gesta.asistencia_local
                 WHERE local_id = p_local
                   AND fecha BETWEEN p_inicio AND p_fin
                   AND tipo_incidencia IN ('PRESENTE', 'NEGATIVA_PAGO'));
    END IF;

    v_cur := date_trunc('month', p_inicio)::date;
    WHILE v_cur <= p_fin LOOP
        v_fin_mes := (v_cur + interval '1 month' - interval '1 day')::date;
        v_dias_mes := (v_fin_mes - v_cur + 1);
        v_tramo_ini := GREATEST(p_inicio, v_cur);
        v_tramo_fin := LEAST(p_fin, v_fin_mes);
        v_meses := v_meses + ((v_tramo_fin - v_tramo_ini + 1)::numeric / v_dias_mes);
        v_cur := (v_cur + interval '1 month')::date;
    END LOOP;

    IF p_per = 'MENSUAL' THEN RETURN ROUND(v_meses, 4); END IF;
    RETURN ROUND(v_meses / 12.0, 4);
END $$;


ALTER FUNCTION gesta.fn_unidades_periodo(p_per gesta.periodicidad, p_inicio date, p_fin date, p_local uuid) OWNER TO gesta_owner;

--
-- TOC entry 461 (class 1255 OID 21162)
-- Name: fn_usuario_set_mfa(boolean, bytea); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.fn_usuario_set_mfa(p_habilitado boolean, p_secreto bytea) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $$
BEGIN
    IF app_usuario() IS NULL THEN RAISE EXCEPTION 'Se requiere un usuario identificado'; END IF;
    UPDATE usuario SET mfa_habilitado = p_habilitado, mfa_secreto_cifrado = p_secreto WHERE id = app_usuario();
END $$;


