--
-- TOC entry 814 (class 1255 OID 21161)
-- Name: fn_usuario_set_password(uuid, text); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.fn_usuario_set_password(p_usuario uuid, p_hash text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $$
BEGIN
    IF app_usuario() IS NULL THEN RAISE EXCEPTION 'Se requiere un usuario identificado'; END IF;
    IF p_usuario <> app_usuario() AND NOT app_admin_gestiona_usuario(p_usuario) THEN
        RAISE EXCEPTION 'No tiene permiso para cambiar la contraseña de ese usuario';
    END IF;
    UPDATE usuario SET password_hash = p_hash, debe_cambiar_pass = (p_usuario <> app_usuario()),
                       intentos_fallidos = 0, bloqueado_hasta = NULL
     WHERE id = p_usuario;
END $$;


ALTER FUNCTION gesta.fn_usuario_set_password(p_usuario uuid, p_hash text) OWNER TO gesta_owner;

--
-- TOC entry 374 (class 1255 OID 20312)
-- Name: fn_valor_uma(date, bigint); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.fn_valor_uma(p_fecha date, p_mercado bigint) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER PARALLEL SAFE
    SET search_path TO 'gesta', 'public'
    AS $$
    SELECT CASE
        WHEN gesta.app_es_sistema()
          OR gesta.app_opera_en_mercado(p_mercado)
          OR EXISTS (
              SELECT 1
                FROM gesta.local_comercial lc
               WHERE lc.mercado_id = p_mercado
                 AND lc.id = ANY (gesta.app_locales_locatario_activo())
          )
        THEN COALESCE(
            (SELECT valor_diario FROM gesta.uma_mercado
              WHERE mercado_id = p_mercado
                AND vigente_desde <= p_fecha
                AND p_fecha < (vigente_desde + interval '1 year')::date
              ORDER BY vigente_desde DESC LIMIT 1),
            (SELECT valor_diario FROM gesta.uma_oficial
              WHERE vigente_desde <= p_fecha
                AND p_fecha < (vigente_desde + interval '1 year')::date
              ORDER BY vigente_desde DESC LIMIT 1)
        )
        ELSE NULL
    END
$$;


ALTER FUNCTION gesta.fn_valor_uma(p_fecha date, p_mercado bigint) OWNER TO gesta_owner;

--
-- TOC entry 1025 (class 1255 OID 20436)
-- Name: fn_vencer_concesiones(); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.fn_vencer_concesiones() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $$
DECLARE
    n integer;
BEGIN
    IF gesta.app_usuario() IS NULL
       OR (NOT gesta.app_es_admin_cualquiera()
           AND gesta.app_usuario() <> '00000000-0000-0000-0000-000000000001'::uuid) THEN
        RAISE EXCEPTION 'Solo un administrador o el proceso batch (sistema) pueden vencer concesiones';
    END IF;
    UPDATE gesta.concesion c
       SET estado = 'VENCIDA'
      FROM gesta.local_comercial lc
     WHERE lc.id = c.local_id
       AND c.estado = ANY (gesta.fn_estados_concesion_proceso('CIERRE_VENCIMIENTO'))
       AND c.fecha_fin IS NOT NULL
       AND c.fecha_fin < gesta.fn_hoy_local(lc.mercado_id)
       AND (gesta.app_usuario() = '00000000-0000-0000-0000-000000000001'::uuid
            OR gesta.app_es_admin(lc.mercado_id));
    GET DIAGNOSTICS n = ROW_COUNT;
    RETURN n;
END $$;


ALTER FUNCTION gesta.fn_vencer_concesiones() OWNER TO gesta_owner;

--
-- TOC entry 620 (class 1255 OID 21053)
-- Name: fn_verificar_cadena_auditoria(); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.fn_verificar_cadena_auditoria() RETURNS TABLE(id bigint, motivo text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $$
    WITH x AS (
        SELECT a.*, lag(a.hash) OVER (PARTITION BY a.mercado_id ORDER BY a.id) AS hash_esperado_prev
          FROM auditoria a
    )
    SELECT x.id,
           CASE WHEN x.hash_prev IS DISTINCT FROM x.hash_esperado_prev THEN 'enlace roto'
                ELSE 'huella alterada' END
      FROM x
     WHERE (x.hash_prev IS DISTINCT FROM x.hash_esperado_prev
            OR x.hash <> fn_hash_auditoria(x.hash_prev, x.tabla, x.registro_id, x.accion, x.usuario_id,
                                           x.datos_antes, x.datos_despues, x.ocurrido_en, x.mercado_id, x.municipio_id))
       AND (
           (x.mercado_id IS NOT NULL AND (app_es_admin(x.mercado_id) OR app_tiene_rol('TESORERIA', x.mercado_id)))
        OR (x.mercado_id IS NULL AND x.municipio_id IS NOT NULL AND app_es_admin_municipio(x.municipio_id))
        OR (x.mercado_id IS NULL AND x.municipio_id IS NULL AND EXISTS (
            SELECT 1 FROM municipio mu WHERE app_es_admin_municipio(mu.id)
        ))
        OR app_es_sistema()
       )
$$;


ALTER FUNCTION gesta.fn_verificar_cadena_auditoria() OWNER TO gesta_owner;

--
-- TOC entry 975 (class 1255 OID 41325)
-- Name: fn_verificar_conexion_segura(); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.fn_verificar_conexion_segura() RETURNS TABLE(rol_sesion name, rol_actual name, es_superusuario boolean, ignora_rls boolean, rol_permitido_backend boolean, tablas_rls_forzado integer)
    LANGUAGE sql STABLE SECURITY DEFINER PARALLEL SAFE
    SET search_path TO 'gesta', 'public', 'pg_catalog'
    AS $$
    SELECT
        session_user::name AS rol_sesion,
        current_user::name AS rol_actual,
        r.rolsuper AS es_superusuario,
        r.rolbypassrls AS ignora_rls,
        (
            NOT r.rolsuper
            AND NOT r.rolbypassrls
            AND (
                pg_has_role(session_user, 'gesta_app', 'USAGE')
                OR pg_has_role(session_user, 'gesta_auth', 'USAGE')
                OR pg_has_role(session_user, 'gesta_batch', 'USAGE')
            )
        ) AS rol_permitido_backend,
        (
            SELECT count(*)::integer
              FROM pg_class c
              JOIN pg_namespace n ON n.oid = c.relnamespace
             WHERE n.nspname = 'gesta'
               AND c.relkind = 'r'
               AND c.relrowsecurity
               AND c.relforcerowsecurity
        ) AS tablas_rls_forzado
      FROM pg_roles r
     WHERE r.rolname = session_user
$$;


ALTER FUNCTION gesta.fn_verificar_conexion_segura() OWNER TO gesta_owner;

