--
-- TOC entry 608 (class 1255 OID 32795)
-- Name: trg_asistencia_protege(); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.trg_asistencia_protege() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'Inmutabilidad probatoria (Art. 20 Fracc. XXVIII): los registros de asistencia e incidencias en campo no se eliminan';
    END IF;
    IF NEW.ubicacion IS NOT NULL THEN
        NEW.ubicacion := ST_Force2D(CASE WHEN ST_SRID(NEW.ubicacion) = 0 THEN ST_SetSRID(NEW.ubicacion, 4326)
                                         WHEN ST_SRID(NEW.ubicacion) <> 4326 THEN ST_Transform(NEW.ubicacion, 4326)
                                         ELSE NEW.ubicacion END);
    END IF;
    IF TG_OP = 'UPDATE' THEN
        IF NEW.local_id IS DISTINCT FROM OLD.local_id OR NEW.fecha IS DISTINCT FROM OLD.fecha THEN
            RAISE EXCEPTION 'El local y la fecha de un registro de asistencia son inmutables';
        END IF;
        IF OLD.tipo_incidencia = 'PRESENTE' AND NEW.tipo_incidencia <> 'PRESENTE'
           AND EXISTS (
               SELECT 1 FROM cargo c
                WHERE c.local_id = OLD.local_id
                  AND c.periodicidad = 'POR_VISITA'
                  AND c.estado <> 'CANCELADO'
                  AND OLD.fecha BETWEEN c.periodo_inicio AND c.periodo_fin
           ) THEN
            RAISE EXCEPTION 'No se puede cambiar a ausencia una visita que ya generó un cargo activo de derecho de piso';
        END IF;
    END IF;
    RETURN NEW;
END $$;


ALTER FUNCTION gesta.trg_asistencia_protege() OWNER TO gesta_owner;

--
-- TOC entry 858 (class 1255 OID 21052)
-- Name: trg_auditoria(); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.trg_auditoria() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $$
DECLARE
    v_exigir boolean := (TG_NARGS > 0 AND TG_ARGV[0] = 'exigir');
    v_excl text[] := '{}';
    v_old jsonb; v_new jsonb; d_old jsonb; d_new jsonb;
    v_usr uuid; v_reg text; v_row jsonb; v_merc bigint; v_mun bigint;
    v_pii text; v_gcol text;
BEGIN
    v_old := CASE WHEN TG_OP <> 'INSERT' THEN to_jsonb(OLD) END;
    v_new := CASE WHEN TG_OP <> 'DELETE' THEN to_jsonb(NEW) END;

    IF TG_TABLE_NAME = 'cargo' AND TG_OP = 'INSERT'
       AND current_setting('gesta.en_lote_cargos', true) = '1' THEN
        IF EXISTS (
            SELECT 1 FROM gesta.lote_cargos lc
            JOIN gesta.local_comercial l ON l.mercado_id = lc.mercado_id
           WHERE l.id = (v_new->>'local_id')::uuid
             AND lc.creado_en = transaction_timestamp()
        ) THEN
            RETURN NULL;
        END IF;
    END IF;

    IF TG_NARGS > 1 THEN
        SELECT array_agg(a) INTO v_excl FROM unnest(TG_ARGV) WITH ORDINALITY t(a, i) WHERE i > 1;
    END IF;

    v_usr := gesta.app_usuario();
    IF v_usr IS NULL AND v_exigir THEN
        RAISE EXCEPTION 'Operación auditada sin usuario: ejecutar SET LOCAL app.usuario_id (tabla %)', TG_TABLE_NAME;
    END IF;

    FOREACH v_gcol IN ARRAY ARRAY['geom','geom_limite','ubicacion_cobro','ubicacion'] LOOP
        IF (v_old IS NOT NULL AND v_old ? v_gcol) OR (v_new IS NOT NULL AND v_new ? v_gcol) THEN
            IF v_old IS NOT NULL THEN
                v_old := v_old || jsonb_build_object(v_gcol || '_md5',
                    CASE WHEN v_old->>v_gcol IS NOT NULL THEN md5(v_old->>v_gcol) END);
            END IF;
            IF v_new IS NOT NULL THEN
                v_new := v_new || jsonb_build_object(v_gcol || '_md5',
                    CASE WHEN v_new->>v_gcol IS NOT NULL THEN md5(v_new->>v_gcol) END);
            END IF;
        END IF;
    END LOOP;

    IF TG_TABLE_NAME = 'persona' THEN
        FOREACH v_pii IN ARRAY ARRAY['curp','rfc','domicilio','telefono','correo'] LOOP
            IF v_old IS NOT NULL AND v_old ? v_pii THEN
                v_old := v_old || jsonb_build_object(v_pii || '_sha256',
                    CASE WHEN v_old->>v_pii IS NOT NULL THEN encode(public.digest(v_old->>v_pii, 'sha256'), 'hex') END);
            END IF;
            IF v_new IS NOT NULL AND v_new ? v_pii THEN
                v_new := v_new || jsonb_build_object(v_pii || '_sha256',
                    CASE WHEN v_new->>v_pii IS NOT NULL THEN encode(public.digest(v_new->>v_pii, 'sha256'), 'hex') END);
            END IF;
        END LOOP;
    ELSIF TG_TABLE_NAME = 'usuario' THEN
        FOREACH v_pii IN ARRAY ARRAY['password_hash','mfa_secreto_cifrado'] LOOP
            IF v_old IS NOT NULL AND v_old ? v_pii THEN
                v_old := v_old || jsonb_build_object(v_pii || '_sha256',
                    CASE WHEN v_old->>v_pii IS NOT NULL THEN encode(public.digest(v_old->>v_pii, 'sha256'), 'hex') END);
            END IF;
            IF v_new IS NOT NULL AND v_new ? v_pii THEN
                v_new := v_new || jsonb_build_object(v_pii || '_sha256',
                    CASE WHEN v_new->>v_pii IS NOT NULL THEN encode(public.digest(v_new->>v_pii, 'sha256'), 'hex') END);
            END IF;
        END LOOP;
    ELSIF TG_TABLE_NAME = 'dispositivo' THEN
        IF v_old IS NOT NULL AND v_old ? 'secreto_hmac' THEN
            v_old := v_old || jsonb_build_object('secreto_hmac_sha256',
                CASE WHEN v_old->>'secreto_hmac' IS NOT NULL THEN encode(public.digest(v_old->>'secreto_hmac', 'sha256'), 'hex') END);
        END IF;
        IF v_new IS NOT NULL AND v_new ? 'secreto_hmac' THEN
            v_new := v_new || jsonb_build_object('secreto_hmac_sha256',
                CASE WHEN v_new->>'secreto_hmac' IS NOT NULL THEN encode(public.digest(v_new->>'secreto_hmac', 'sha256'), 'hex') END);
        END IF;
    END IF;

    IF v_old IS NOT NULL THEN v_old := v_old - v_excl; END IF;
    IF v_new IS NOT NULL THEN v_new := v_new - v_excl; END IF;

    v_row := COALESCE(v_new, v_old);
    v_reg := COALESCE(
        v_row->>'id',
        CASE WHEN v_row ? 'vigente_desde' AND v_row ? 'mercado_id'
             THEN (v_row->>'mercado_id') || ':' || (v_row->>'vigente_desde') END,
        CASE WHEN v_row ? 'pago_id' AND v_row ? 'cargo_id'
             THEN (v_row->>'pago_id') || ':' || (v_row->>'cargo_id') END
    );

    IF TG_TABLE_NAME = 'mercado' THEN
        v_merc := (v_row->>'id')::bigint; v_mun := (v_row->>'municipio_id')::bigint;
    ELSIF TG_TABLE_NAME = 'municipio' THEN
        v_mun := (v_row->>'id')::bigint;
    ELSIF TG_TABLE_NAME = 'persona' THEN
        v_merc := (v_row->>'mercado_alta_id')::bigint;
    ELSE
        v_merc := (v_row->>'mercado_id')::bigint;
        v_mun := (v_row->>'municipio_id')::bigint;
        IF v_merc IS NULL AND v_mun IS NULL THEN
            IF (v_row->>'local_id') IS NOT NULL THEN
                SELECT mercado_id INTO v_merc FROM local_comercial WHERE id = (v_row->>'local_id')::uuid;
            ELSIF TG_TABLE_NAME = 'concesion_suplente' THEN
                SELECT lc.mercado_id INTO v_merc FROM concesion c JOIN local_comercial lc ON lc.id = c.local_id
                 WHERE c.id = (v_row->>'concesion_id')::uuid;
            ELSIF (v_row->>'pago_id') IS NOT NULL THEN
                SELECT mercado_id INTO v_merc FROM pago WHERE id = (v_row->>'pago_id')::uuid;
            ELSIF TG_TABLE_NAME = 'usuario' THEN
                IF (v_row->>'persona_id') IS NOT NULL THEN
                    SELECT mercado_alta_id INTO v_merc FROM persona WHERE id = (v_row->>'persona_id')::uuid;
                END IF;
                IF v_merc IS NULL AND v_mun IS NULL THEN
                    SELECT ur.mercado_id, ur.municipio_id INTO v_merc, v_mun
                      FROM usuario_rol ur
                     WHERE ur.usuario_id = COALESCE((v_row->>'id')::uuid, v_usr) AND ur.activo
                     ORDER BY (ur.mercado_id IS NOT NULL) DESC LIMIT 1;
                END IF;
            ELSIF TG_TABLE_NAME IN ('usuario_rol', 'dispositivo') AND (v_row->>'usuario_id') IS NOT NULL THEN
                SELECT p.mercado_alta_id INTO v_merc
                  FROM usuario u JOIN persona p ON p.id = u.persona_id
                 WHERE u.id = (v_row->>'usuario_id')::uuid;
                IF v_merc IS NULL AND v_mun IS NULL THEN
                    SELECT ur.mercado_id, ur.municipio_id INTO v_merc, v_mun
                      FROM usuario_rol ur
                     WHERE ur.usuario_id = COALESCE((v_row->>'usuario_id')::uuid, v_usr) AND ur.activo
                     ORDER BY (ur.mercado_id IS NOT NULL) DESC LIMIT 1;
                END IF;
            ELSIF TG_TABLE_NAME = 'documento' THEN
                IF (v_row->>'concesion_id') IS NOT NULL THEN
                    SELECT lc.mercado_id INTO v_merc FROM concesion c JOIN local_comercial lc ON lc.id = c.local_id WHERE c.id = (v_row->>'concesion_id')::uuid;
                ELSIF (v_row->>'traspaso_id') IS NOT NULL THEN
                    SELECT lc.mercado_id INTO v_merc FROM traspaso t JOIN local_comercial lc ON lc.id = t.local_id WHERE t.id = (v_row->>'traspaso_id')::uuid;
                ELSIF (v_row->>'deposito_id') IS NOT NULL THEN
                    SELECT mercado_id INTO v_merc FROM deposito_hacienda WHERE id = (v_row->>'deposito_id')::uuid;
                ELSIF (v_row->>'persona_id') IS NOT NULL THEN
                    SELECT mercado_alta_id INTO v_merc FROM persona WHERE id = (v_row->>'persona_id')::uuid;
                ELSIF (v_row->>'tarifa_id') IS NOT NULL THEN
                    SELECT mercado_id, municipio_id INTO v_merc, v_mun FROM tarifa WHERE id = (v_row->>'tarifa_id')::bigint;
                END IF;
            END IF;
        END IF;
    END IF;

    IF TG_OP = 'UPDATE' THEN
        SELECT COALESCE(jsonb_object_agg(e.key, e.value), '{}'),
               COALESCE(jsonb_object_agg(e.key, v_old->e.key), '{}')
          INTO d_new, d_old
          FROM jsonb_each(v_new) e
         WHERE v_old->e.key IS DISTINCT FROM e.value;
        IF d_new = '{}'::jsonb THEN RETURN NULL; END IF;
    ELSE
        d_old := v_old; d_new := v_new;
    END IF;

    PERFORM fn_auditoria_agregar(TG_TABLE_NAME, v_reg, TG_OP, v_usr, d_old, d_new, v_merc, v_mun);
    RETURN NULL;
END $$;


ALTER FUNCTION gesta.trg_auditoria() OWNER TO gesta_owner;

