--
-- TOC entry 1374 (class 1255 OID 24597)
-- Name: trg_cargo_inmutable(); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.trg_cargo_inmutable() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'Inmutabilidad financiera: los cargos no se eliminan; utilice fn_cancelar_cargo con motivo formal';
    END IF;
    IF OLD.estado = 'CANCELADO' AND NEW.estado IS DISTINCT FROM 'CANCELADO' THEN
        RAISE EXCEPTION 'Un cargo CANCELADO es histórico y no puede reactivarse';
    END IF;
    IF NEW.local_id IS DISTINCT FROM OLD.local_id
       OR NEW.concepto IS DISTINCT FROM OLD.concepto
       OR NEW.periodo_inicio IS DISTINCT FROM OLD.periodo_inicio
       OR NEW.periodo_fin IS DISTINCT FROM OLD.periodo_fin THEN
        RAISE EXCEPTION 'Los atributos fiscales base del cargo (local, concepto, periodo) son inmutables';
    END IF;

    -- Verifica TANTO la bandera de ejecución autorizada en sesión como la existencia del registro en cargo_ajuste
    IF (NEW.monto_total IS DISTINCT FROM OLD.monto_total
        OR (NEW.estado = 'CANCELADO' AND OLD.estado <> 'CANCELADO')) THEN
        IF current_setting('gesta.ajuste_autorizado', true) IS DISTINCT FROM NEW.id::text
           OR NOT EXISTS (
               SELECT 1 FROM gesta.cargo_ajuste ca
                WHERE ca.cargo_id = NEW.id
                  AND (
                      (NEW.estado = 'CANCELADO' AND ca.tipo = 'CANCELACION')
                   OR (NEW.monto_total IS DISTINCT FROM OLD.monto_total AND ca.tipo = 'AJUSTE' AND ca.monto_nuevo = NEW.monto_total)
                  )
           ) THEN
            RAISE EXCEPTION 'Todo ajuste de monto o cancelación de cargo debe realizarse exclusivamente vía fn_ajustar_cargo o fn_cancelar_cargo';
        END IF;
    END IF;
    RETURN NEW;
END $$;


ALTER FUNCTION gesta.trg_cargo_inmutable() OWNER TO gesta_owner;

--
-- TOC entry 850 (class 1255 OID 20434)
-- Name: trg_concesion_fin(); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.trg_concesion_fin() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $$
DECLARE
    v_hoy date;
    v_mercado_id bigint;
    v_municipio_id bigint;
    v_estatus_local gesta.estatus_local;
    v_p gesta.persona%ROWTYPE;
BEGIN
    SELECT lc.mercado_id, m.municipio_id, lc.estatus, gesta.fn_hoy_local(lc.mercado_id)
      INTO v_mercado_id, v_municipio_id, v_estatus_local, v_hoy
      FROM gesta.local_comercial lc
      JOIN gesta.mercado m ON m.id = lc.mercado_id
     WHERE lc.id = NEW.local_id
       FOR UPDATE OF lc;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'El local comercial % no existe', NEW.local_id;
    END IF;

    NEW.mercado_id := v_mercado_id;
    NEW.municipio_id := v_municipio_id;
    v_hoy := COALESCE(v_hoy, (now() AT TIME ZONE 'America/Mexico_City')::date);

    IF TG_OP = 'INSERT' AND NEW.fecha_inicio IS NULL THEN
        NEW.fecha_inicio := v_hoy;
    END IF;

    NEW.numero_expediente := NULLIF(btrim(NEW.numero_expediente), '');

    -- Exigir expediente y fecha de dictamen cuando la concesión sea formal (CU-12 / RN-04)
    IF NEW.es_formal THEN
        IF NEW.es_temporal_feria THEN
            RAISE EXCEPTION 'Art. 34: Los permisos temporales de feria no pueden marcarse como concesiones formales permanentes';
        END IF;
        IF NEW.numero_expediente IS NULL OR NEW.fecha_dictamen IS NULL THEN
            RAISE EXCEPTION 'CU-12 / RN-04: Toda concesión formal (es_formal = true) exige número de expediente y fecha de dictamen';
        END IF;
    END IF;

    -- Impedir crear o activar concesión VIGENTE (o SUSPENDIDA en alta) sobre un local en BAJA o EN_LITIGIO
    IF (NEW.estado = 'VIGENTE'
        OR (TG_OP = 'INSERT' AND gesta.fn_concesion_en_proceso(NEW.estado, 'OCUPACION_ACTIVA')))
       AND v_estatus_local IN ('BAJA', 'EN_LITIGIO') THEN
        RAISE EXCEPTION 'CU-12: No se puede crear ni mantener una concesión % sobre un local en estatus %', NEW.estado, v_estatus_local;
    END IF;

    -- Serialización explícita con advisory locks por municipio y titular/CURP/RFC (RN-PAD-01)
    PERFORM pg_advisory_xact_lock(hashtextextended('concesion_titular:' || v_municipio_id::text || ':' || NEW.titular_persona_id::text, 0));
    SELECT * INTO v_p FROM gesta.persona WHERE id = NEW.titular_persona_id FOR SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'La persona titular % no existe', NEW.titular_persona_id;
    END IF;
    IF v_p.curp IS NOT NULL THEN
        PERFORM pg_advisory_xact_lock(hashtextextended('concesion_curp:' || v_municipio_id::text || ':' || v_p.curp, 0));
    END IF;
    IF v_p.rfc IS NOT NULL THEN
        PERFORM pg_advisory_xact_lock(hashtextextended('concesion_rfc:' || v_municipio_id::text || ':' || v_p.rfc, 0));
    END IF;

    IF NEW.es_formal AND NOT NEW.es_temporal_feria AND v_p.curp IS NULL AND v_p.rfc IS NULL THEN
        RAISE EXCEPTION 'RN-PAD-01: Toda concesión formal permanente exige que la persona titular (%) tenga registrado CURP o RFC válido', NEW.titular_persona_id;
    END IF;

    -- Validación de unicidad personalísima acotada al municipio (RN-PAD-01 Semana 1)
    IF gesta.fn_concesion_en_proceso(NEW.estado, 'UNICIDAD_PADRON')
       AND NOT NEW.es_temporal_feria
       AND EXISTS (
           SELECT 1
             FROM gesta.concesion c
             JOIN gesta.persona p2 ON p2.id = c.titular_persona_id
            WHERE c.municipio_id = v_municipio_id
              AND c.estado = ANY (gesta.fn_estados_concesion_proceso('UNICIDAD_PADRON'))
              AND NOT c.es_temporal_feria
              AND c.id IS DISTINCT FROM NEW.id
              AND (
                  c.titular_persona_id = NEW.titular_persona_id
                  OR (v_p.curp IS NOT NULL AND p2.curp = v_p.curp)
                  OR (v_p.rfc  IS NOT NULL AND p2.rfc  = v_p.rfc)
              )
       ) THEN
        RAISE EXCEPTION 'RN-PAD-01: La persona titular (%) ya posee una concesión activa o suspendida en el padrón del municipio %',
                        NEW.titular_persona_id, v_municipio_id;
    END IF;

    -- Ajuste de fecha_fin al cerrar concesión (respetando el corte explícito de trg_traspaso_ejecuta)
    IF NEW.estado IN ('CEDIDA', 'REVOCADA', 'VENCIDA') THEN
        IF current_setting('gesta.traspaso_cierre_origen', true) IS DISTINCT FROM NEW.id::text THEN
            IF NEW.fecha_fin IS NULL
               OR (TG_OP = 'UPDATE'
                   AND gesta.fn_concesion_en_proceso(OLD.estado, 'OCUPACION_ACTIVA')
                   AND NEW.fecha_fin = OLD.fecha_fin
                   AND NEW.fecha_fin >= v_hoy) THEN
                IF NEW.estado IN ('CEDIDA', 'VENCIDA') AND v_hoy > NEW.fecha_inicio THEN
                    NEW.fecha_fin := v_hoy - 1;
                ELSE
                    NEW.fecha_fin := GREATEST(v_hoy, NEW.fecha_inicio);
                END IF;
            END IF;
        END IF;
    END IF;

    -- Si se inserta una nueva concesión que inicia el mismo día en que cerraba una concesión CEDIDA previa
    -- con rango mayor a un día, se recorta automáticamente la concesión CEDIDA previa a NEW.fecha_inicio - 1
    IF TG_OP = 'INSERT' AND NEW.estado <> 'REVOCADA' THEN
        PERFORM set_config('gesta.traspaso_cierre_origen', c.id::text, true),
                (
                    SELECT 1
                )
          FROM gesta.concesion c
         WHERE c.local_id = NEW.local_id
           AND c.estado = 'CEDIDA'
           AND c.fecha_fin = NEW.fecha_inicio
           AND c.fecha_inicio < NEW.fecha_inicio;

        UPDATE gesta.concesion c
           SET fecha_fin = NEW.fecha_inicio - 1
         WHERE c.local_id = NEW.local_id
           AND c.estado = 'CEDIDA'
           AND c.fecha_fin = NEW.fecha_inicio
           AND c.fecha_inicio < NEW.fecha_inicio;

        PERFORM set_config('gesta.traspaso_cierre_origen', '', true);
    END IF;

    IF NEW.estado <> 'REVOCADA'
       AND NOT (NEW.estado = 'CEDIDA' AND NEW.fecha_fin = NEW.fecha_inicio)
       AND EXISTS (
           SELECT 1 FROM gesta.concesion c
            WHERE c.local_id = NEW.local_id
              AND c.estado <> 'REVOCADA'
              AND NOT (c.estado = 'CEDIDA' AND c.fecha_fin = c.fecha_inicio)
              AND c.id IS DISTINCT FROM NEW.id
              AND daterange(c.fecha_inicio, c.fecha_fin, '[]') && daterange(NEW.fecha_inicio, NEW.fecha_fin, '[]')
       ) THEN
        RAISE EXCEPTION 'El periodo de la concesión (% a %) se traslapa con otra concesión no revocada en el mismo local',
                        NEW.fecha_inicio, COALESCE(NEW.fecha_fin::text, 'vigente');
    END IF;

    RETURN NEW;
END $$;


ALTER FUNCTION gesta.trg_concesion_fin() OWNER TO gesta_owner;

--
-- TOC entry 1163 (class 1255 OID 20495)
-- Name: trg_concesion_vinculo(); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.trg_concesion_vinculo() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $$
DECLARE
    v_mercado bigint;
BEGIN
    SELECT mercado_id INTO v_mercado FROM local_comercial WHERE id = NEW.local_id;
    PERFORM fn_vincular_persona(NEW.titular_persona_id, v_mercado);
    IF NEW.ocupante_persona_id IS NOT NULL THEN
        PERFORM fn_vincular_persona(NEW.ocupante_persona_id, v_mercado);
    END IF;

    IF NEW.estado = 'VIGENTE' THEN
        UPDATE local_comercial
           SET estatus = 'OCUPADO'
         WHERE id = NEW.local_id
           AND estatus IN ('DESOCUPADO', 'ABANDONADO');
    ELSIF NEW.estado IN ('VENCIDA', 'REVOCADA') THEN
        IF NOT EXISTS (
            SELECT 1 FROM concesion c
             WHERE c.local_id = NEW.local_id
               AND c.estado IN ('VIGENTE', 'SUSPENDIDA')
               AND c.id IS DISTINCT FROM NEW.id
        ) THEN
            UPDATE local_comercial
               SET estatus = 'DESOCUPADO'
             WHERE id = NEW.local_id
               AND estatus = 'OCUPADO';
        END IF;
    END IF;
    RETURN NULL;
END $$;


ALTER FUNCTION gesta.trg_concesion_vinculo() OWNER TO gesta_owner;

