--
-- TOC entry 1446 (class 1255 OID 41250)
-- Name: trg_deposito_conciliacion_valida(); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.trg_deposito_conciliacion_valida() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $_$
DECLARE
    v_dep_id uuid;
    v_dep_old_id uuid;
    v_id uuid;
    d gesta.deposito_hacienda%ROWTYPE;
    v_suma_pagos numeric(12,2);
    v_num_pagos integer;
BEGIN
    IF TG_TABLE_NAME = 'deposito_hacienda' THEN
        v_dep_id := NEW.id;
    ELSIF TG_TABLE_NAME = 'pago' THEN
        v_dep_id := NEW.deposito_id;
        IF TG_OP = 'UPDATE' AND OLD.deposito_id IS DISTINCT FROM NEW.deposito_id THEN
            v_dep_old_id := OLD.deposito_id;
        END IF;
    END IF;

    FOR v_id IN
        SELECT DISTINCT x FROM unnest(ARRAY[v_dep_id, v_dep_old_id]) AS x WHERE x IS NOT NULL
    LOOP
        SELECT * INTO d FROM gesta.deposito_hacienda WHERE id = v_id;
        IF NOT FOUND THEN
            CONTINUE;
        END IF;

        SELECT COALESCE(SUM(p.monto) FILTER (WHERE p.estado = 'VIGENTE'), 0),
               COUNT(*) FILTER (WHERE p.estado = 'VIGENTE')
          INTO v_suma_pagos, v_num_pagos
          FROM gesta.pago p
         WHERE p.deposito_id = d.id;

        IF v_num_pagos = 0 THEN
            RAISE EXCEPTION 'CU-23: El depósito % por $% no tiene pagos vigentes vinculados; vincule los pagos en la misma transacción',
                            d.id, d.monto_depositado;
        END IF;

        IF d.monto_depositado <> v_suma_pagos
           AND (d.justificacion_diferencia IS NULL OR length(btrim(d.justificacion_diferencia)) = 0) THEN
            RAISE EXCEPTION 'CU-23 3a: El monto depositado ($%) no cuadra con la suma de los pagos vigentes vinculados ($%, diferencia $%); es obligatorio registrar justificacion_diferencia',
                            d.monto_depositado, v_suma_pagos, (d.monto_depositado - v_suma_pagos);
        END IF;

        IF d.tarjeta_monto IS NOT NULL
           AND (d.monto_depositado <> d.tarjeta_monto OR v_suma_pagos <> d.tarjeta_monto)
           AND (d.justificacion_diferencia IS NULL OR length(btrim(d.justificacion_diferencia)) = 0) THEN
            RAISE EXCEPTION 'CU-24 5a: Existe diferencia entre el monto depositado ($%), la suma de pagos vinculados ($%) y la tarjeta informativa ($%); es obligatorio registrar justificacion_diferencia',
                            d.monto_depositado, v_suma_pagos, d.tarjeta_monto;
        END IF;
    END LOOP;

    RETURN NULL;
END $_$;


ALTER FUNCTION gesta.trg_deposito_conciliacion_valida() OWNER TO gesta_owner;

--
-- TOC entry 1253 (class 1255 OID 20965)
-- Name: trg_detalle_inmutable(); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.trg_detalle_inmutable() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $$
DECLARE
    v_pago_id uuid := CASE WHEN TG_OP = 'DELETE' THEN OLD.pago_id ELSE NEW.pago_id END;
    v_corte uuid;
    v_dep uuid;
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'Inmutabilidad financiera: prohibido eliminar registros de pago_detalle; cancele el pago o ajuste el cargo';
    END IF;

    SELECT corte_caja_id, deposito_id
      INTO v_corte, v_dep
      FROM gesta.pago
     WHERE id = v_pago_id;

    IF v_corte IS NOT NULL OR v_dep IS NOT NULL THEN
        IF current_setting('gesta.aplicacion_post_corte_autorizada', true) IS DISTINCT FROM v_pago_id::text THEN
            RAISE EXCEPTION 'RN-FIS-05: El pago % ya fue liquidado en corte de caja o depositado en Hacienda; no se permiten nuevas aplicaciones (INSERT) ni modificaciones (UPDATE) salvo flujo autorizado', v_pago_id;
        END IF;
    END IF;

    RETURN NEW;
END $$;


ALTER FUNCTION gesta.trg_detalle_inmutable() OWNER TO gesta_owner;

--
-- TOC entry 886 (class 1255 OID 20968)
