--
-- TOC entry 1350 (class 1255 OID 20963)
-- Name: trg_detalle_valida(); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.trg_detalle_valida() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $$
DECLARE
    v_pago pago%ROWTYPE;
    v_cargo cargo%ROWTYPE;
    v_suma numeric;
BEGIN
    SELECT * INTO v_pago  FROM pago  WHERE id = NEW.pago_id FOR UPDATE;
    SELECT * INTO v_cargo FROM cargo WHERE id = NEW.cargo_id FOR SHARE;

    IF v_pago.estado = 'CANCELADO' THEN
        RAISE EXCEPTION 'No se puede aplicar un pago cancelado (%)', NEW.pago_id;
    END IF;
    IF v_cargo.local_id <> v_pago.local_id THEN
        RAISE EXCEPTION 'El cargo % no pertenece al local del pago %', NEW.cargo_id, NEW.pago_id;
    END IF;
    IF v_cargo.estado = 'CANCELADO' THEN
        RAISE EXCEPTION 'No se puede aplicar un pago a un cargo cancelado (%)', NEW.cargo_id;
    END IF;

    -- Optimización O(1): evalúa la ventana únicamente sobre los otros cargos vinculados a NEW.pago_id
    WITH cargos_del_pago AS (
        SELECT pd0.cargo_id
          FROM gesta.pago_detalle pd0
         WHERE pd0.pago_id = NEW.pago_id
           AND pd0.cargo_id <> NEW.cargo_id
    ), det_efectivo AS (
        SELECT pd.pago_id,
               pd.cargo_id,
               CASE
                   WHEN cg.estado = 'CANCELADO'::gesta.estado_cargo THEN 0::numeric
                   ELSE GREATEST(
                       LEAST(
                           pd.monto_aplicado,
                           cg.monto_total - COALESCE(
                               SUM(pd.monto_aplicado) OVER (
                                   PARTITION BY pd.cargo_id
                                   ORDER BY p.fecha_pago ASC, pd.pago_id ASC
                                   ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING
                               ), 0::numeric
                           )
                       ), 0::numeric
                   )
               END AS aplicado_efectivo
          FROM gesta.pago_detalle pd
          JOIN cargos_del_pago cp ON cp.cargo_id = pd.cargo_id
          JOIN gesta.cargo cg     ON cg.id = pd.cargo_id
          JOIN gesta.pago p       ON p.id = pd.pago_id
         WHERE p.estado = 'VIGENTE'::gesta.estado_pago
    )
    SELECT COALESCE(SUM(aplicado_efectivo), 0)
      INTO v_suma
      FROM det_efectivo
     WHERE pago_id = NEW.pago_id;

    IF v_suma + NEW.monto_aplicado > v_pago.monto THEN
        RAISE EXCEPTION 'Lo aplicado (%) excede el monto disponible del pago (%)', v_suma + NEW.monto_aplicado, v_pago.monto;
    END IF;

    RETURN NEW;
END $$;


ALTER FUNCTION gesta.trg_detalle_valida() OWNER TO gesta_owner;

--
-- TOC entry 793 (class 1255 OID 41277)
-- Name: trg_dispositivo_protege(); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.trg_dispositivo_protege() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        IF EXISTS (SELECT 1 FROM gesta.pago p WHERE p.dispositivo_id = OLD.id)
           OR EXISTS (SELECT 1 FROM gesta.pago_conflicto_folio pc WHERE pc.dispositivo_id = OLD.id) THEN
            RAISE EXCEPTION 'Inmutabilidad de folios (CU-18): no se puede eliminar el dispositivo % porque registra pagos o conflictos históricos; desactívelo con fn_dispositivo_set_activo', OLD.id;
        END IF;
        RETURN OLD;
    END IF;

    NEW.serie_folio := upper(btrim(NEW.serie_folio));
    IF NEW.secreto_hmac IS NULL THEN
        NEW.secreto_hmac := public.gen_random_bytes(32);
    END IF;

    IF TG_OP = 'INSERT' THEN
        IF current_setting('gesta.dispositivo_autorizado', true) IS DISTINCT FROM NEW.id::text
           AND NOT gesta.app_es_sistema() THEN
            NEW.ultimo_consecutivo := 0;
            NEW.activo := true;
            NEW.ultima_sincronizacion := NULL;
        END IF;
        RETURN NEW;
    END IF;

    IF NEW.ultimo_consecutivo < OLD.ultimo_consecutivo THEN
        RAISE EXCEPTION 'Seguridad de folios (CU-18 / CU-19): no se permite disminuir ultimo_consecutivo del dispositivo % (actual %, intentado %)',
                        OLD.id, OLD.ultimo_consecutivo, NEW.ultimo_consecutivo;
    END IF;

    IF NEW.serie_folio IS DISTINCT FROM OLD.serie_folio THEN
        IF OLD.ultimo_consecutivo > 0
           OR EXISTS (SELECT 1 FROM gesta.pago p WHERE p.dispositivo_id = OLD.id)
           OR EXISTS (SELECT 1 FROM gesta.pago_conflicto_folio pc WHERE pc.dispositivo_id = OLD.id) THEN
            RAISE EXCEPTION 'Inmutabilidad de serie (CU-18): no se puede cambiar serie_folio (%) del dispositivo % porque ya registra pagos o consecutivos emitidos',
                            OLD.serie_folio, OLD.id;
        END IF;
    END IF;

    IF (NEW.ultimo_consecutivo IS DISTINCT FROM OLD.ultimo_consecutivo
        OR NEW.serie_folio IS DISTINCT FROM OLD.serie_folio
        OR NEW.activo IS DISTINCT FROM OLD.activo
        OR NEW.usuario_id IS DISTINCT FROM OLD.usuario_id
        OR NEW.mercado_id IS DISTINCT FROM OLD.mercado_id
        OR NEW.secreto_hmac IS DISTINCT FROM OLD.secreto_hmac
        OR NEW.ultima_sincronizacion IS DISTINCT FROM OLD.ultima_sincronizacion)
       AND current_setting('gesta.dispositivo_autorizado', true) IS DISTINCT FROM OLD.id::text
       AND NOT gesta.app_es_sistema() THEN
        RAISE EXCEPTION 'Seguridad de dispositivo: ultimo_consecutivo, serie_folio, activo y secreto_hmac solo pueden modificarse mediante funciones SECURITY DEFINER autorizadas';
    END IF;

    RETURN NEW;
END $$;


ALTER FUNCTION gesta.trg_dispositivo_protege() OWNER TO gesta_owner;

--
-- TOC entry 619 (class 1255 OID 41032)
-- Name: trg_documento_protege_dictamen(); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.trg_documento_protege_dictamen() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $$
DECLARE
    v_traspaso_id uuid := CASE WHEN TG_OP = 'DELETE' THEN OLD.traspaso_id ELSE OLD.traspaso_id END;
BEGIN
    IF OLD.tipo = 'DICTAMEN'::gesta.tipo_documento AND OLD.traspaso_id IS NOT NULL THEN
        IF (TG_OP = 'DELETE'
            OR NEW.tipo <> 'DICTAMEN'::gesta.tipo_documento
            OR NEW.traspaso_id IS DISTINCT FROM OLD.traspaso_id)
           AND EXISTS (
               SELECT 1 FROM gesta.traspaso t
                WHERE t.id = v_traspaso_id
                  AND (t.dictamen = 'APROBADO'::gesta.resultado_dictamen OR t.regularizado)
           )
           AND NOT EXISTS (
               SELECT 1 FROM gesta.documento d
                WHERE d.traspaso_id = v_traspaso_id
                  AND d.tipo = 'DICTAMEN'::gesta.tipo_documento
                  AND d.id <> OLD.id
           ) THEN
            RAISE EXCEPTION 'CU-13 / CU-14: No se puede eliminar ni desvincular el único documento DICTAMEN de un traspaso aprobado o regularizado (%)', v_traspaso_id;
        END IF;
    END IF;
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END $$;


ALTER FUNCTION gesta.trg_documento_protege_dictamen() OWNER TO gesta_owner;

--
-- TOC entry 921 (class 1255 OID 20362)
-- Name: trg_local_geometria(); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.trg_local_geometria() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $$
DECLARE
    v_tol numeric;
    v_mun bigint;
    v_geom_merc public.geometry;
    v_en_recinto boolean := false;
    v_reactiva boolean := false;
    v_tiene_3_ausencias_gps boolean := false;
    v_tiene_acta_abandono boolean := false;
BEGIN
    IF TG_OP = 'UPDATE' THEN
        v_reactiva := (OLD.estatus = 'BAJA' AND NEW.estatus <> 'BAJA');
        IF NEW.estatus IN ('BAJA', 'DESOCUPADO') AND OLD.estatus <> NEW.estatus THEN
            IF EXISTS (
                SELECT 1 FROM gesta.concesion c
                 WHERE c.local_id = NEW.id
                   AND c.estado = ANY (gesta.fn_estados_concesion_proceso('OCUPACION_ACTIVA'))
            ) THEN
                RAISE EXCEPTION 'CU-08: No se puede cambiar el local % a estatus % mientras tenga una concesión VIGENTE o SUSPENDIDA; revoque o venza primero la concesión', NEW.numero_local, NEW.estatus;
            END IF;
        END IF;
    END IF;

    -- CU-08 / Art. 20 Fracc. XXVIII: Cambiar a ABANDONADO exige >= 3 ausencias cerradas con GPS (>= 10 días continuos sin actividad) y acta/evidencia documental
    IF NEW.estatus = 'ABANDONADO' AND (TG_OP = 'INSERT' OR OLD.estatus <> 'ABANDONADO') THEN
        SELECT EXISTS (
            SELECT 1
              FROM gesta.asistencia_local a
             WHERE a.local_id = NEW.id
               AND a.tipo_incidencia = 'AUSENTE_CERRADO'
               AND a.ubicacion IS NOT NULL
               AND NOT EXISTS (
                   SELECT 1 FROM gesta.asistencia_local ap
                    WHERE ap.local_id = NEW.id
                      AND ap.tipo_incidencia = 'PRESENTE'
                      AND ap.fecha > a.fecha
               )
               AND NOT EXISTS (
                   SELECT 1 FROM gesta.pago pg
                    WHERE pg.local_id = NEW.id
                      AND pg.estado = 'VIGENTE'
                      AND gesta.fn_fecha_local(NEW.mercado_id, pg.fecha_pago) > a.fecha
               )
            HAVING COUNT(*) >= 3
               AND (MAX(a.fecha) - MIN(a.fecha)) >= 10
        ) INTO v_tiene_3_ausencias_gps;

        SELECT EXISTS (
            SELECT 1
              FROM gesta.documento d
             WHERE (
                   d.local_id = NEW.id
                   OR d.concesion_id IN (
                       SELECT c.id FROM gesta.concesion c WHERE c.local_id = NEW.id
                   )
               )
               AND d.tipo IN ('DICTAMEN'::gesta.tipo_documento, 'FOTO_LOCAL'::gesta.tipo_documento, 'OTRO'::gesta.tipo_documento)
               AND d.url IS NOT NULL
               AND length(btrim(d.url)) > 0
        ) INTO v_tiene_acta_abandono;

        IF NOT v_tiene_3_ausencias_gps OR NOT v_tiene_acta_abandono THEN
            RAISE EXCEPTION 'CU-08 / Art. 20 Fracc. XXVIII: No se puede declarar el local % como ABANDONADO sin acreditar al menos 3 visitas georreferenciadas (GPS) con local cerrado en un lapso >= 10 días continuos sin actividad ni pagos, y al menos un acta administrativa o evidencia documental registrada en documento', NEW.numero_local;
        END IF;
    END IF;

    IF NEW.geom IS NOT NULL THEN
        NEW.geom := public.ST_Force2D(
            CASE WHEN public.ST_SRID(NEW.geom) = 0 THEN public.ST_SetSRID(NEW.geom, 4326)
                 WHEN public.ST_SRID(NEW.geom) <> 4326 THEN public.ST_Transform(NEW.geom, 4326)
                 ELSE NEW.geom END
        );
        IF NOT public.ST_IsValid(NEW.geom) THEN
            RAISE EXCEPTION 'Polígono inválido en el local %: %', NEW.numero_local, public.ST_IsValidReason(NEW.geom);
        END IF;
        IF NEW.estatus <> 'BAJA' AND (
               TG_OP = 'INSERT'
            OR NEW.geom IS DISTINCT FROM OLD.geom
            OR NEW.tipo_espacio IS DISTINCT FROM OLD.tipo_espacio
            OR NEW.zona_id IS DISTINCT FROM OLD.zona_id
            OR v_reactiva
        ) THEN
            PERFORM pg_advisory_xact_lock(hashtextextended('local_geom:' || NEW.mercado_id::text, 0));
            SELECT m.tolerancia_traslape_m2, m.municipio_id, m.geom_limite
              INTO v_tol, v_mun, v_geom_merc
              FROM gesta.mercado m WHERE m.id = NEW.mercado_id;

            v_en_recinto := (
                NEW.tipo_espacio NOT IN ('VIA_PUBLICA', 'AMBULANTE')
                AND (
                    (v_geom_merc IS NOT NULL AND public.ST_Covers(v_geom_merc, NEW.geom))
                    OR (NEW.zona_id IS NOT NULL AND EXISTS (
                        SELECT 1 FROM gesta.zona_mercado zm
                         WHERE zm.id = NEW.zona_id AND zm.geom IS NOT NULL AND public.ST_Covers(zm.geom, NEW.geom)
                    ))
                )
            );

            IF (TG_OP = 'INSERT' OR NEW.geom IS DISTINCT FROM OLD.geom OR v_reactiva) AND EXISTS (
                SELECT 1 FROM gesta.local_comercial o
                WHERE o.mercado_id = NEW.mercado_id AND o.id <> NEW.id AND o.estatus <> 'BAJA'
                  AND o.geom IS NOT NULL AND o.geom && NEW.geom AND public.ST_Intersects(o.geom, NEW.geom)
                  AND public.ST_Area(public.ST_CollectionExtract(public.ST_Intersection(o.geom, NEW.geom), 3)::public.geography) > COALESCE(v_tol, 0.25)
            ) THEN
                RAISE EXCEPTION 'El polígono del local % se traslapa con otro local del mercado', NEW.numero_local;
            END IF;

            IF NOT v_en_recinto THEN
                IF NEW.tipo_espacio = 'FIJO' AND EXISTS (
                    SELECT 1 FROM gesta.zona_restringida z
                     WHERE z.municipio_id = v_mun AND z.tipo = 'PRIMER_CUADRO' AND public.ST_Intersects(z.geom, NEW.geom)) THEN
                    RAISE EXCEPTION 'RN-PAD-04: no se permite un comercio FIJO fuera de recinto municipal dentro del Primer Cuadro (local %)', NEW.numero_local;
                END IF;

                IF EXISTS (
                    SELECT 1 FROM gesta.zona_restringida z
                     WHERE z.municipio_id = v_mun
                       AND z.tipo <> 'PRIMER_CUADRO'
                       AND public.ST_DWithin(z.geom, NEW.geom, 0.002)
                       AND public.ST_DWithin(z.geom::public.geography, NEW.geom::public.geography, 100)) THEN
                    RAISE EXCEPTION 'RN-PAD-03: no se permite un permiso fuera de recinto municipal a menos de 100 m de escuela, hospital, templo, seguridad pública, edificio de gobierno o acceso a mercado (local %)', NEW.numero_local;
                END IF;
            END IF;
        END IF;
        NEW.area_calculada_m2 := ROUND(public.ST_Area(NEW.geom::public.geography)::numeric, 2);
        NEW.perimetro_m := ROUND(public.ST_Perimeter(NEW.geom::public.geography)::numeric, 2);
        NEW.centroide := public.ST_PointOnSurface(NEW.geom);
    ELSE
        NEW.area_calculada_m2 := NULL;
        NEW.perimetro_m := NULL;
        NEW.centroide := NULL;
    END IF;
    NEW.actualizado_en := now();
    RETURN NEW;
END $$;


ALTER FUNCTION gesta.trg_local_geometria() OWNER TO gesta_owner;

--
-- TOC entry 7710 (class 0 OID 0)
-- Dependencies: 921
-- Name: FUNCTION trg_local_geometria(); Type: COMMENT; Schema: gesta; Owner: gesta_owner
--

COMMENT ON FUNCTION gesta.trg_local_geometria() IS 'Valida inmutabilidad financiera de mercado_id, exigencia y contención en mercado.geom_limite y zona_mercado.geom, control de traslapes y aplicación sin excepciones de RN-PAD-03 (buffer 100 m) y RN-PAD-04 (prohibición de comercio FIJO en Primer Cuadro).';


--
-- TOC entry 428 (class 1255 OID 41085)
-- Name: trg_mercado_geometria(); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.trg_mercado_geometria() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $$
DECLARE
    v_otro_nombre text;
    v_zona_fuera text;
    v_local_fuera text;
BEGIN
    IF NEW.geom_limite IS NOT NULL THEN
        NEW.geom_limite := public.ST_Force2D(
            CASE WHEN public.ST_SRID(NEW.geom_limite) = 0 THEN public.ST_SetSRID(NEW.geom_limite, 4326)
                 WHEN public.ST_SRID(NEW.geom_limite) <> 4326 THEN public.ST_Transform(NEW.geom_limite, 4326)
                 ELSE NEW.geom_limite END
        );
        IF NOT public.ST_IsValid(NEW.geom_limite) THEN
            RAISE EXCEPTION 'CU-04: Polígono límite inválido en el mercado %: %', NEW.nombre, public.ST_IsValidReason(NEW.geom_limite);
        END IF;

        IF NEW.activo THEN
            PERFORM pg_advisory_xact_lock(hashtextextended('mercado_geom:' || NEW.municipio_id::text, 0));
            SELECT o.nombre INTO v_otro_nombre
              FROM gesta.mercado o
             WHERE o.municipio_id = NEW.municipio_id
               AND o.id IS DISTINCT FROM NEW.id
               AND o.activo
               AND o.geom_limite IS NOT NULL
               AND o.geom_limite && NEW.geom_limite
               AND public.ST_Intersects(o.geom_limite, NEW.geom_limite)
               AND public.ST_Area(public.ST_CollectionExtract(public.ST_Intersection(o.geom_limite, NEW.geom_limite), 3)::public.geography)
                   > LEAST(COALESCE(NEW.tolerancia_traslape_m2, 0.25), COALESCE(o.tolerancia_traslape_m2, 0.25))
             LIMIT 1;

            IF v_otro_nombre IS NOT NULL THEN
                RAISE EXCEPTION 'CU-04: El polígono límite del mercado % se traslapa con el mercado %', NEW.nombre, v_otro_nombre;
            END IF;
        END IF;
    END IF;

    IF TG_OP = 'UPDATE' AND NEW.geom_limite IS DISTINCT FROM OLD.geom_limite THEN
        IF NEW.geom_limite IS NULL AND (
            EXISTS (SELECT 1 FROM gesta.zona_mercado zm WHERE zm.mercado_id = NEW.id)
            OR EXISTS (SELECT 1 FROM gesta.local_comercial lc WHERE lc.mercado_id = NEW.id AND lc.estatus <> 'BAJA')
        ) THEN
            RAISE EXCEPTION 'CU-04: No se puede eliminar geom_limite del mercado % porque ya cuenta con zonas o locales activos registrados', NEW.nombre;
        END IF;

        IF NEW.geom_limite IS NOT NULL THEN
            SELECT zm.nombre INTO v_zona_fuera
              FROM gesta.zona_mercado zm
             WHERE zm.mercado_id = NEW.id
               AND zm.geom IS NOT NULL
               AND NOT public.ST_Covers(NEW.geom_limite, zm.geom)
             LIMIT 1;
            IF v_zona_fuera IS NOT NULL THEN
                RAISE EXCEPTION 'CU-04: El nuevo límite del mercado % deja fuera a la zona %', NEW.nombre, v_zona_fuera;
            END IF;

            SELECT lc.numero_local INTO v_local_fuera
              FROM gesta.local_comercial lc
             WHERE lc.mercado_id = NEW.id
               AND lc.estatus <> 'BAJA'
               AND lc.geom IS NOT NULL
               AND NOT public.ST_Covers(NEW.geom_limite, lc.geom)
             LIMIT 1;
            IF v_local_fuera IS NOT NULL THEN
                RAISE EXCEPTION 'CU-04: El nuevo límite del mercado % deja fuera al local comercial activo %', NEW.nombre, v_local_fuera;
            END IF;
        END IF;
    END IF;

    RETURN NEW;
END $$;


ALTER FUNCTION gesta.trg_mercado_geometria() OWNER TO gesta_owner;

--
-- TOC entry 1218 (class 1255 OID 41327)
-- Name: trg_municipio_valida_tz(); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.trg_municipio_valida_tz() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gesta', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_tz_canonica text;
BEGIN
    NEW.zona_horaria := NULLIF(btrim(NEW.zona_horaria), '');
    IF NEW.zona_horaria IS NULL THEN
        RAISE EXCEPTION 'La zona_horaria del municipio es obligatoria';
    END IF;

    SELECT tz.name
      INTO v_tz_canonica
      FROM pg_catalog.pg_timezone_names tz
     WHERE lower(tz.name) = lower(NEW.zona_horaria)
     LIMIT 1;

    IF v_tz_canonica IS NULL THEN
        RAISE EXCEPTION 'Zona horaria inválida (%) para el municipio %: no existe en pg_timezone_names',
                        NEW.zona_horaria, NEW.nombre;
    END IF;

    NEW.zona_horaria := v_tz_canonica;
    RETURN NEW;
END $$;


ALTER FUNCTION gesta.trg_municipio_valida_tz() OWNER TO gesta_owner;

--
-- TOC entry 551 (class 1255 OID 20957)
-- Name: trg_pago_corte_tardio(); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.trg_pago_corte_tardio() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $$
BEGIN
    IF NEW.corte_caja_id IS NULL AND NEW.cobrador_id IS NOT NULL AND EXISTS (
        SELECT 1 FROM corte_caja_diario c
         WHERE c.cobrador_id = NEW.cobrador_id AND c.mercado_id = NEW.mercado_id
           AND c.fecha_corte = fn_fecha_local(NEW.mercado_id, NEW.fecha_pago)) THEN
        NEW.requiere_revision := true;
        NEW.motivo_revision := COALESCE(NEW.motivo_revision || '; ', '') || 'Sincronizado después del corte de su día';
    END IF;
    RETURN NEW;
END $$;


