--

CREATE FUNCTION gesta.trg_pago_estado_recalcula() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $$
DECLARE r record;
BEGIN
    FOR r IN SELECT cargo_id FROM pago_detalle WHERE pago_id = NEW.id LOOP
        PERFORM fn_recalcular_cargo(r.cargo_id);
    END LOOP;
    RETURN NULL;
END $$;


