--
-- TOC entry 830 (class 1255 OID 20961)
-- Name: trg_pago_inmutable(); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.trg_pago_inmutable() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'Los pagos no se eliminan; cancelar con motivo vía fn_cancelar_pago';
    END IF;
    IF lower(btrim(NEW.hash_offline)) IS DISTINCT FROM lower(btrim(OLD.hash_offline))
       OR NEW.payload_offline IS DISTINCT FROM OLD.payload_offline
       OR NEW.fecha_dispositivo IS DISTINCT FROM OLD.fecha_dispositivo
       OR NEW.consecutivo_dispositivo IS DISTINCT FROM OLD.consecutivo_dispositivo THEN
        RAISE EXCEPTION 'RN-FIS-06: hash_offline, payload_offline, fecha_dispositivo y consecutivo_dispositivo son inmutables';
    END IF;
    IF OLD.estado = 'CANCELADO' AND NEW.estado IS DISTINCT FROM 'CANCELADO' THEN
        RAISE EXCEPTION 'Un pago CANCELADO no se puede reactivar; registre un pago nuevo';
    END IF;
    IF NEW.estado = 'CANCELADO' AND OLD.estado = 'VIGENTE' THEN
        IF current_setting('gesta.cancelacion_pago_autorizada', true) IS DISTINCT FROM OLD.id::text THEN
            RAISE EXCEPTION 'RN-FIS-05 / CU-20: La cancelación de pagos debe realizarse exclusivamente vía fn_cancelar_pago';
        END IF;
        IF NOT gesta.app_autoriza_ajuste_fiscal(NEW.mercado_id) THEN
            RAISE EXCEPTION 'RN-FIS-05 / CU-20: Solo TESORERIA o un Administrador Municipal autorizado puede cancelar un pago';
        END IF;
        IF OLD.cobrador_id IS NOT NULL AND OLD.cobrador_id = gesta.app_usuario() THEN
            RAISE EXCEPTION 'RN-FIS-05 / CU-20: Segregación de funciones: un cobrador no puede cancelar sus propios cobros';
        END IF;
    END IF;
    IF (OLD.requiere_revision AND NOT NEW.requiere_revision)
       OR (OLD.motivo_revision IS NOT NULL AND NEW.motivo_revision IS DISTINCT FROM OLD.motivo_revision AND NOT NEW.requiere_revision) THEN
        IF current_setting('gesta.revision_pago_autorizada', true) IS DISTINCT FROM OLD.id::text THEN
            RAISE EXCEPTION 'La resolución de pagos en revisión debe realizarse exclusivamente vía fn_resolver_revision_pago';
        END IF;
    END IF;
    IF OLD.motivo_revision IS NOT NULL
       AND NEW.requiere_revision
       AND NEW.motivo_revision IS DISTINCT FROM OLD.motivo_revision
       AND (NEW.motivo_revision IS NULL OR strpos(NEW.motivo_revision, OLD.motivo_revision) <> 1)
       AND current_setting('gesta.revision_pago_autorizada', true) IS DISTINCT FROM OLD.id::text THEN
        RAISE EXCEPTION 'El historial de motivo_revision no puede borrarse ni sobrescribirse';
    END IF;
    IF NEW.monto IS DISTINCT FROM OLD.monto OR NEW.mercado_id IS DISTINCT FROM OLD.mercado_id THEN
        RAISE EXCEPTION 'El monto y el mercado de un pago son inmutables (cobrado %); cancele con motivo y registre uno nuevo', OLD.monto;
    END IF;
    IF OLD.corte_caja_id IS NOT NULL AND NEW.corte_caja_id IS DISTINCT FROM OLD.corte_caja_id THEN
        RAISE EXCEPTION 'RN-FIS-05: el pago ya está liquidado en un corte de caja';
    END IF;
    IF OLD.deposito_id IS NOT NULL AND NEW.deposito_id IS DISTINCT FROM OLD.deposito_id THEN
        RAISE EXCEPTION 'Pago ya depositado: no se puede reasignar el depósito';
    END IF;
    IF (OLD.corte_caja_id IS NOT NULL OR OLD.deposito_id IS NOT NULL) AND (
           NEW.local_id IS DISTINCT FROM OLD.local_id
        OR NEW.cobrador_id IS DISTINCT FROM OLD.cobrador_id
        OR NEW.fecha_pago IS DISTINCT FROM OLD.fecha_pago
        OR NEW.folio IS DISTINCT FROM OLD.folio
    ) THEN
        RAISE EXCEPTION 'RN-FIS-05: pago ya liquidado en corte o depositado; sus atributos operativos son inmutables';
    END IF;
    RETURN NEW;
END $$;


ALTER FUNCTION gesta.trg_pago_inmutable() OWNER TO gesta_owner;

--
-- TOC entry 1409 (class 1255 OID 20955)
-- Name: trg_pago_valida(); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.trg_pago_valida() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $$
DECLARE
    v_mercado bigint;
    v_modelo gesta.modelo_cobro;
    v_disp_mercado bigint;
    v_disp_secreto bytea;
    v_fecha_loc date;
    v_hash_calc text;
BEGIN
    SELECT lc.mercado_id, m.modelo_cobro
      INTO v_mercado, v_modelo
      FROM gesta.local_comercial lc
      JOIN gesta.mercado m ON m.id = lc.mercado_id
     WHERE lc.id = NEW.local_id;

    IF v_mercado IS DISTINCT FROM NEW.mercado_id THEN
        RAISE EXCEPTION 'El mercado del pago (%) no coincide con el del local (%)', NEW.mercado_id, v_mercado;
    END IF;

    IF NEW.canal IN ('CAMPO_ADMINISTRADOR', 'CAMPO_INSPECTOR')
       AND v_modelo = 'POLITICA_FISCAL_CAJAS' THEN
        RAISE EXCEPTION 'Hallazgo 3.1 / RN-FIS: El mercado % opera bajo el modelo POLITICA_FISCAL_CAJAS; no admite cobros en campo (%)', NEW.mercado_id, NEW.canal;
    END IF;

    IF NEW.canal IN ('CAJA_POLITICA_FISCAL', 'IMPORTACION_EXCEL')
       AND v_modelo = 'ADMINISTRACION_DIRECTA' THEN
        RAISE EXCEPTION 'Hallazgo 3.1 / RN-FIS: El mercado % opera bajo el modelo ADMINISTRACION_DIRECTA; no admite cobros por caja ni importación de Política Fiscal (%)', NEW.mercado_id, NEW.canal;
    END IF;

    IF NEW.canal IN ('CAJA_POLITICA_FISCAL', 'IMPORTACION_EXCEL') THEN
        v_fecha_loc := gesta.fn_fecha_local(NEW.mercado_id, NEW.fecha_pago);
        IF NEW.payload_offline IS NULL OR btrim(NEW.payload_offline) = '' THEN
            NEW.payload_offline := concat_ws(
                '|',
                'CAJA_EXCEL',
                NEW.mercado_id::text,
                upper(btrim(NEW.folio)),
                v_fecha_loc::text,
                ROUND(NEW.monto, 2)::text
            );
        END IF;
        IF NEW.hash_offline IS NULL OR btrim(NEW.hash_offline) = '' THEN
            NEW.hash_offline := encode(
                public.digest(convert_to(NEW.payload_offline, 'UTF8'), 'sha256'),
                'hex'
            );
        END IF;
    END IF;

    IF NEW.hash_offline IS NULL OR btrim(NEW.hash_offline) = '' THEN
        RAISE EXCEPTION 'RN-FIS-06: hash_offline es obligatorio';
    END IF;
    NEW.hash_offline := lower(btrim(NEW.hash_offline));

    IF NEW.dispositivo_id IS NOT NULL THEN
        SELECT mercado_id, secreto_hmac
          INTO v_disp_mercado, v_disp_secreto
          FROM gesta.dispositivo
         WHERE id = NEW.dispositivo_id;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'El dispositivo % no existe', NEW.dispositivo_id;
        END IF;
        IF v_disp_mercado IS NOT NULL AND v_disp_mercado <> NEW.mercado_id THEN
            RAISE EXCEPTION 'El dispositivo pertenece a otro mercado';
        END IF;
    ELSIF NEW.canal IN ('CAMPO_ADMINISTRADOR', 'CAMPO_INSPECTOR') THEN
        RAISE EXCEPTION 'CU-18 / RN-FIS-06: Todo pago de campo requiere dispositivo_id para verificar su firma HMAC-SHA256';
    END IF;

    IF NEW.payload_offline IS NOT NULL AND btrim(NEW.payload_offline) <> '' THEN
        IF NEW.canal IN ('CAMPO_ADMINISTRADOR', 'CAMPO_INSPECTOR') THEN
            v_hash_calc := encode(
                public.hmac(convert_to(NEW.payload_offline, 'UTF8'), v_disp_secreto, 'sha256'),
                'hex'
            );
        ELSE
            v_hash_calc := encode(
                public.digest(convert_to(NEW.payload_offline, 'UTF8'), 'sha256'),
                'hex'
            );
        END IF;

        IF public.digest(convert_to(NEW.hash_offline, 'UTF8'), 'sha256')
           IS DISTINCT FROM public.digest(convert_to(v_hash_calc, 'UTF8'), 'sha256') THEN
            RAISE EXCEPTION 'RN-FIS-06: El sello hash_offline no es válido para el payload canónico del pago %', NEW.id;
        END IF;
    ELSIF TG_OP = 'INSERT' THEN
        RAISE EXCEPTION 'RN-FIS-06: Todo pago requiere almacenar su payload_offline canónico verificable';
    END IF;

    IF TG_OP = 'INSERT' AND NEW.corte_caja_id IS NOT NULL THEN
        RAISE EXCEPTION 'RN-FIS-05: Un pago no puede insertarse vinculado directamente a un corte de caja; utilice fn_cerrar_corte';
    END IF;

    IF TG_OP = 'UPDATE' AND NEW.corte_caja_id IS DISTINCT FROM OLD.corte_caja_id THEN
        IF NEW.corte_caja_id IS NULL
           OR current_setting('gesta.corte_autorizado', true) IS DISTINCT FROM NEW.corte_caja_id::text THEN
            RAISE EXCEPTION 'RN-FIS-05: La vinculación de pagos a un corte de caja debe realizarse exclusivamente vía fn_cerrar_corte';
        END IF;
    END IF;

    IF (NEW.corte_caja_id IS NOT NULL OR NEW.deposito_id IS NOT NULL) THEN
        IF NEW.estado = 'CANCELADO' AND (
               TG_OP = 'INSERT'
            OR NEW.corte_caja_id IS DISTINCT FROM OLD.corte_caja_id
            OR NEW.deposito_id IS DISTINCT FROM OLD.deposito_id
        ) THEN
            RAISE EXCEPTION 'No se puede vincular un pago CANCELADO a un corte de caja o depósito bancario';
        END IF;
        IF NEW.forma_pago <> 'EFECTIVO' THEN
            RAISE EXCEPTION 'Solo los pagos en EFECTIVO se integran a cortes de caja y depósitos de efectivo en Hacienda';
        END IF;
    END IF;

    IF NEW.deposito_id IS NOT NULL
       AND NEW.canal IN ('CAMPO_ADMINISTRADOR', 'CAMPO_INSPECTOR')
       AND NEW.corte_caja_id IS NULL THEN
        RAISE EXCEPTION 'RN-FIS-05: Todo cobro en efectivo en campo debe liquidar primero su corte de caja diario ciego antes de integrarse a un depósito en Hacienda';
    END IF;

    RETURN NEW;
END $$;


ALTER FUNCTION gesta.trg_pago_valida() OWNER TO gesta_owner;

