--
-- TOC entry 1421 (class 1255 OID 20108)
-- Name: trg_persona_normaliza(); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.trg_persona_normaliza() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $$
BEGIN
    NEW.curp             := NULLIF(upper(btrim(NEW.curp)), '');
    NEW.rfc              := NULLIF(upper(btrim(NEW.rfc)),  '');
    NEW.nombres          := NULLIF(btrim(NEW.nombres), '');
    NEW.apellido_paterno := NULLIF(btrim(NEW.apellido_paterno), '');
    NEW.apellido_materno := NULLIF(btrim(NEW.apellido_materno), '');
    NEW.razon_social     := NULLIF(btrim(NEW.razon_social), '');
    NEW.telefono         := NULLIF(btrim(NEW.telefono), '');
    NEW.domicilio        := NULLIF(btrim(NEW.domicilio), '');

    IF NEW.curp IS NOT NULL THEN
        PERFORM pg_advisory_xact_lock(hashtextextended('concesion_curp:' || NEW.curp, 0));
    END IF;
    IF NEW.rfc IS NOT NULL THEN
        PERFORM pg_advisory_xact_lock(hashtextextended('concesion_rfc:' || NEW.rfc, 0));
    END IF;

    RETURN NEW;
END $$;


ALTER FUNCTION gesta.trg_persona_normaliza() OWNER TO gesta_owner;

