--
-- TOC entry 668 (class 1255 OID 20524)
-- Name: trg_suplencia_limite(); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.trg_suplencia_limite() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $$
DECLARE n integer;
BEGIN
    PERFORM pg_advisory_xact_lock(hashtextextended('suplentes:' || NEW.concesion_id::text, 0));
    SELECT COUNT(*) INTO n FROM concesion_suplente
     WHERE concesion_id = NEW.concesion_id AND id IS DISTINCT FROM NEW.id;
    IF n >= 2 THEN
        RAISE EXCEPTION 'RN-PAD-02: la concesión ya tiene % suplentes; el máximo es 2 (familiares en primer grado)', n;
    END IF;
    RETURN NEW;
END $$;


ALTER FUNCTION gesta.trg_suplencia_limite() OWNER TO gesta_owner;

--
-- TOC entry 892 (class 1255 OID 20526)
-- Name: trg_suplente_titular(); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.trg_suplente_titular() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $$
DECLARE
    v_titular uuid;
    v_tipo_titular gesta.tipo_persona;
    v_tipo_suplente gesta.tipo_persona;
BEGIN
    NEW.parentesco := UPPER(BTRIM(NEW.parentesco));
    -- Homologación automática de sinónimos civiles al estándar normativo
    IF NEW.parentesco IN ('ESPOSO', 'ESPOSA', 'CONCUBINO', 'CONCUBINA') THEN
        NEW.parentesco := 'CONYUGE';
    END IF;

    SELECT c.titular_persona_id, pt.tipo_persona
      INTO v_titular, v_tipo_titular
      FROM concesion c
      JOIN persona pt ON pt.id = c.titular_persona_id
     WHERE c.id = NEW.concesion_id;

    IF v_titular = NEW.persona_id THEN
        RAISE EXCEPTION 'RN-PAD-02: el titular de la concesión no puede registrarse como su propio suplente';
    END IF;

    SELECT tipo_persona INTO v_tipo_suplente FROM persona WHERE id = NEW.persona_id;
    IF v_tipo_titular <> 'FISICA' OR v_tipo_suplente <> 'FISICA' THEN
        RAISE EXCEPTION 'RN-PAD-02: la suplencia por parentesco en primer grado aplica exclusivamente entre personas físicas';
    END IF;

    RETURN NEW;
END $$;


ALTER FUNCTION gesta.trg_suplente_titular() OWNER TO gesta_owner;

--
-- TOC entry 1165 (class 1255 OID 20528)
-- Name: trg_suplente_vinculo(); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.trg_suplente_vinculo() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $$
DECLARE v_mercado bigint;
BEGIN
    SELECT lc.mercado_id INTO v_mercado
      FROM concesion c JOIN local_comercial lc ON lc.id = c.local_id WHERE c.id = NEW.concesion_id;
    PERFORM fn_vincular_persona(NEW.persona_id, v_mercado);
    RETURN NULL;
END $$;


ALTER FUNCTION gesta.trg_suplente_vinculo() OWNER TO gesta_owner;

--
-- TOC entry 1100 (class 1255 OID 20493)
-- Name: trg_traspaso_ejecuta(); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.trg_traspaso_ejecuta() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $$
DECLARE
    o gesta.concesion%ROWTYPE;
    d gesta.concesion%ROWTYPE;
    v_p_dest gesta.persona%ROWTYPE;
    v_municipio_id bigint;
    v_ef date;
    v_new uuid;
    v_hoy date;
    v_dt record;
    v_cargo_dt uuid;
BEGIN
    SELECT m.municipio_id, gesta.fn_hoy_local(lc.mercado_id)
      INTO v_municipio_id, v_hoy
      FROM gesta.local_comercial lc
      JOIN gesta.mercado m ON m.id = lc.mercado_id
     WHERE lc.id = NEW.local_id;
    v_hoy := COALESCE(v_hoy, (now() AT TIME ZONE 'America/Mexico_City')::date);
    NEW.numero_expediente := NULLIF(btrim(NEW.numero_expediente), '');

    IF TG_OP = 'UPDATE' AND OLD.concesion_destino_id IS NOT NULL THEN
        IF NEW.local_id IS DISTINCT FROM OLD.local_id
           OR NEW.concesion_origen_id IS DISTINCT FROM OLD.concesion_origen_id
           OR NEW.concesion_destino_id IS DISTINCT FROM OLD.concesion_destino_id
           OR NEW.persona_origen_id IS DISTINCT FROM OLD.persona_origen_id
           OR NEW.persona_destino_id IS DISTINCT FROM OLD.persona_destino_id
           OR NEW.fecha_efectiva IS DISTINCT FROM OLD.fecha_efectiva THEN
            RAISE EXCEPTION 'Inmutabilidad de padrón: un traspaso ya ejecutado no puede alterar sus concesiones, personas, local ni fecha efectiva';
        END IF;
        IF OLD.cargo_traspaso_id IS NOT NULL AND (
               NEW.cargo_traspaso_id IS DISTINCT FROM OLD.cargo_traspaso_id
            OR NEW.cuota_base_uma IS DISTINCT FROM OLD.cuota_base_uma
        ) THEN
            RAISE EXCEPTION 'Inmutabilidad fiscal: el cargo por derecho de traspaso (%) y su cuota base en UMA no pueden alterarse', OLD.cargo_traspaso_id;
        END IF;
        IF NEW.dictamen IN ('PENDIENTE', 'RECHAZADO') AND OLD.dictamen = 'APROBADO' THEN
            RAISE EXCEPTION 'Un traspaso formal aprobado que ya generó concesión de destino no puede pasar a estado %', NEW.dictamen;
        END IF;
    END IF;

    IF NEW.tipo_tramite = 'INFORMAL_NOTIFICADO' THEN
        IF NEW.regularizado OR NEW.dictamen = 'APROBADO' THEN
            RAISE EXCEPTION 'CU-13 / CU-14: Un traspaso INFORMAL_NOTIFICADO no puede estar APROBADO ni regularizado sin pasar a trámite FORMAL con dictamen';
        END IF;
        NEW.dictamen := 'NO_APLICA';
    ELSIF TG_OP = 'UPDATE'
          AND OLD.tipo_tramite = 'INFORMAL_NOTIFICADO'
          AND NEW.tipo_tramite = 'FORMAL'
          AND NEW.dictamen = 'NO_APLICA' THEN
        NEW.dictamen := CASE WHEN NEW.regularizado THEN 'APROBADO'::gesta.resultado_dictamen
                             ELSE 'PENDIENTE'::gesta.resultado_dictamen END;
    END IF;

    IF NEW.regularizado AND NEW.dictamen <> 'APROBADO' THEN
        NEW.tipo_tramite := 'FORMAL';
        NEW.dictamen := 'APROBADO';
    END IF;

    -- Validación estricta de dictamen real para aprobar o regularizar (CU-13 / CU-14)
    IF NEW.dictamen = 'APROBADO' OR NEW.regularizado THEN
        IF NEW.tipo_tramite <> 'FORMAL' THEN
            RAISE EXCEPTION 'CU-13 / CU-14: Solo un trámite FORMAL puede tener dictamen APROBADO o marcarse como regularizado';
        END IF;
        IF NEW.numero_expediente IS NULL THEN
            RAISE EXCEPTION 'CU-13 / CU-14: El número de expediente es obligatorio para aprobar o regularizar un traspaso';
        END IF;
        IF NEW.fecha_dictamen IS NULL THEN
            RAISE EXCEPTION 'CU-13 / CU-14: La fecha de dictamen es obligatoria para aprobar o regularizar un traspaso';
        END IF;
        IF NOT EXISTS (
            SELECT 1 FROM gesta.documento doc
             WHERE doc.traspaso_id = NEW.id
               AND doc.tipo = 'DICTAMEN'::gesta.tipo_documento
               AND doc.url IS NOT NULL
               AND length(btrim(doc.url)) > 0
        ) THEN
            RAISE EXCEPTION 'CU-13 / CU-14: Para aprobar o regularizar el traspaso (%) es obligatorio adjuntar previamente el documento probatorio de tipo DICTAMEN', NEW.id;
        END IF;
    END IF;

    SELECT * INTO o FROM gesta.concesion WHERE id = NEW.concesion_origen_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'La concesión de origen % no existe', NEW.concesion_origen_id;
    END IF;
    IF o.es_temporal_feria THEN
        RAISE EXCEPTION 'Art. 14 / Art. 34: Los permisos temporales de ferias y festividades son estrictamente personales e intransferibles';
    END IF;
    IF o.local_id <> NEW.local_id THEN
        RAISE EXCEPTION 'La concesión de origen (%) no pertenece al local del traspaso (%)', NEW.concesion_origen_id, NEW.local_id;
    END IF;
    IF o.titular_persona_id <> NEW.persona_origen_id THEN
        RAISE EXCEPTION 'persona_origen no es la titular de la concesión de origen';
    END IF;

    IF NEW.concesion_destino_id IS NOT NULL THEN
        SELECT * INTO d FROM gesta.concesion WHERE id = NEW.concesion_destino_id;
        IF d.titular_persona_id <> NEW.persona_destino_id THEN
            RAISE EXCEPTION 'persona_destino no es la titular de la concesión de destino';
        END IF;
    END IF;

    IF NEW.concesion_destino_id IS NULL
       AND (NEW.dictamen = 'APROBADO' OR NEW.tipo_tramite = 'INFORMAL_NOTIFICADO') THEN
        IF o.estado <> 'VIGENTE' THEN
            RAISE EXCEPTION 'La concesión de origen no está vigente (estado %)', o.estado;
        END IF;

        SELECT * INTO v_p_dest FROM gesta.persona WHERE id = NEW.persona_destino_id FOR SHARE;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'La persona destino % no existe', NEW.persona_destino_id;
        END IF;

        IF EXISTS (
            SELECT 1
              FROM gesta.concesion c
              JOIN gesta.persona p2 ON p2.id = c.titular_persona_id
             WHERE c.municipio_id = v_municipio_id
               AND c.estado = ANY (gesta.fn_estados_concesion_proceso('UNICIDAD_PADRON'))
               AND NOT c.es_temporal_feria
               AND c.id <> o.id
               AND (
                   c.titular_persona_id = NEW.persona_destino_id
                   OR (v_p_dest.curp IS NOT NULL AND p2.curp = v_p_dest.curp)
                   OR (v_p_dest.rfc  IS NOT NULL AND p2.rfc  = v_p_dest.rfc)
               )
        ) THEN
            RAISE EXCEPTION 'RN-PAD-01: La persona destino (%) ya es titular de otra concesión activa o suspendida en el padrón del municipio %',
                            NEW.persona_destino_id, v_municipio_id;
        END IF;

        v_ef := COALESCE(NEW.fecha_efectiva, NEW.fecha_dictamen, NEW.fecha_notificacion, v_hoy);
        IF v_ef < o.fecha_inicio THEN
            RAISE EXCEPTION 'La fecha efectiva (%) no puede ser anterior al inicio de la concesión de origen (%)', v_ef, o.fecha_inicio;
        END IF;
        IF o.fecha_fin IS NOT NULL AND v_ef > o.fecha_fin THEN
            RAISE EXCEPTION 'La fecha efectiva (%) excede la fecha de fin de la concesión de origen (%)', v_ef, o.fecha_fin;
        END IF;
        NEW.fecha_efectiva := v_ef;

        PERFORM set_config('gesta.traspaso_cierre_origen', o.id::text, true);
        UPDATE gesta.concesion
           SET estado = 'CEDIDA',
               fecha_fin = GREATEST(v_ef - 1, o.fecha_inicio)
         WHERE id = o.id;
        PERFORM set_config('gesta.traspaso_cierre_origen', '', true);

        INSERT INTO gesta.concesion (
            local_id, titular_persona_id, giro_id, estado, es_formal,
            numero_expediente, fecha_dictamen, fecha_inicio
        )
        VALUES (
            o.local_id, NEW.persona_destino_id, o.giro_id, 'VIGENTE',
            (NEW.tipo_tramite = 'FORMAL' AND NEW.dictamen = 'APROBADO'),
            NEW.numero_expediente, NEW.fecha_dictamen, v_ef
        )
        RETURNING id INTO v_new;

        NEW.concesion_destino_id := v_new;
        IF NEW.tipo_tramite = 'FORMAL' AND NEW.dictamen = 'APROBADO' THEN
            NEW.regularizado := true;
        END IF;

    ELSIF TG_OP = 'UPDATE'
          AND OLD.concesion_destino_id IS NOT NULL
          AND NOT OLD.regularizado
          AND (NEW.regularizado OR (NEW.tipo_tramite = 'FORMAL' AND NEW.dictamen = 'APROBADO')) THEN
        NEW.tipo_tramite := 'FORMAL';
        NEW.dictamen := 'APROBADO';
        PERFORM set_config('gesta.traspaso_formalizando', NEW.concesion_destino_id::text, true);
        UPDATE gesta.concesion
           SET es_formal = true,
               numero_expediente = NEW.numero_expediente,
               fecha_dictamen = NEW.fecha_dictamen
         WHERE id = NEW.concesion_destino_id;
        PERFORM set_config('gesta.traspaso_formalizando', '', true);
        NEW.regularizado := true;
    END IF;

    IF NEW.tipo_tramite = 'FORMAL' AND NEW.dictamen = 'APROBADO'
       AND NEW.concesion_destino_id IS NOT NULL AND NEW.cargo_traspaso_id IS NULL THEN
        SELECT * INTO v_dt
          FROM gesta.fn_calcular_derecho_traspaso(
              NEW.concesion_origen_id,
              NEW.persona_destino_id,
              COALESCE(NEW.cuota_base_uma, 10.0),
              COALESCE(NEW.fecha_efectiva, v_hoy)
          );
        IF v_dt.monto_neto_pagar IS NOT NULL AND v_dt.monto_neto_pagar > 0 THEN
            INSERT INTO gesta.cargo (
                local_id, concesion_id, concepto, periodo_inicio, periodo_fin,
                metodo_calculo, valor_tarifa_aplicado, unidad_valor_aplicada,
                valor_uma_aplicado, cuota_unidad_aplicada, unidades, monto_total
            )
            VALUES (
                NEW.local_id, NEW.concesion_destino_id, 'OTRO',
                COALESCE(NEW.fecha_efectiva, v_hoy), COALESCE(NEW.fecha_efectiva, v_hoy),
                'CUOTA_FIJA', v_dt.cuota_base_uma, 'UMA',
                v_dt.uma_aplicada, v_dt.monto_neto_pagar, 1, v_dt.monto_neto_pagar
            )
            RETURNING id INTO v_cargo_dt;
            NEW.cargo_traspaso_id := v_cargo_dt;
        END IF;
    END IF;

    IF NEW.regularizado AND NEW.concesion_destino_id IS NULL THEN
        RAISE EXCEPTION 'No se puede marcar como regularizado un traspaso que aún no genera concesión de destino';
    END IF;

    RETURN NEW;
END $$;


ALTER FUNCTION gesta.trg_traspaso_ejecuta() OWNER TO gesta_owner;

--
-- TOC entry 936 (class 1255 OID 20314)
-- Name: trg_uma_mercado_ventana(); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.trg_uma_mercado_ventana() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $$
DECLARE
    v_hoy date;
    v_anio int;
    v_inicio date;
    v_prox_inicio date;
    v_tiene_uma_ciclo boolean;
    v_tiene_cargos_ciclo boolean;
BEGIN
    IF gesta.app_es_sistema() THEN
        RETURN NEW;
    END IF;
    IF app_usuario() IS NULL THEN
        RAISE EXCEPTION 'V6.1: capturar la UMA requiere un usuario identificado (app.usuario_id)';
    END IF;

    v_hoy := fn_hoy_local(NEW.mercado_id);
    v_anio := EXTRACT(YEAR FROM v_hoy)::int;
    v_inicio := CASE WHEN EXTRACT(MONTH FROM v_hoy) = 1
                     THEN make_date(v_anio - 1, 2, 1)
                     ELSE make_date(v_anio, 2, 1) END;
    v_prox_inicio := make_date(v_anio, 2, 1);

    IF NEW.vigente_desde <> v_inicio
       AND NOT (EXTRACT(MONTH FROM v_hoy) = 1 AND NEW.vigente_desde = v_prox_inicio) THEN
        RAISE EXCEPTION 'Solo se puede registrar la UMA con vigente_desde = % (o % de forma anticipada en enero), no %',
                        v_inicio, v_prox_inicio, NEW.vigente_desde;
    END IF;

    SELECT EXISTS (
        SELECT 1 FROM uma_mercado
         WHERE mercado_id = NEW.mercado_id AND vigente_desde = NEW.vigente_desde
    ) INTO v_tiene_uma_ciclo;

    SELECT EXISTS (
        SELECT 1 FROM cargo cg
        JOIN local_comercial lc ON lc.id = cg.local_id
         WHERE lc.mercado_id = NEW.mercado_id
           AND cg.unidad_valor_aplicada = 'UMA'
           AND cg.estado <> 'CANCELADO'
           AND cg.periodo_inicio >= NEW.vigente_desde
           AND cg.periodo_inicio < (NEW.vigente_desde + interval '1 year')::date
    ) INTO v_tiene_cargos_ciclo;

    IF (TG_OP = 'UPDATE' OR v_tiene_uma_ciclo)
       AND v_tiene_cargos_ciclo
       AND NOT (
           (NEW.vigente_desde = v_prox_inicio AND v_hoy BETWEEN make_date(v_anio, 1, 9) AND make_date(v_anio, 2, 15))
        OR (NEW.vigente_desde = v_inicio AND v_hoy BETWEEN make_date(v_anio, 2, 1) AND make_date(v_anio, 2, 15))
       ) THEN
        RAISE EXCEPTION 'La UMA del mercado ya tiene cargos activos en el ciclo y solo puede editarse en la ventana anual (hasta el 15 de febrero; hoy es %).', v_hoy;
    END IF;

    IF TG_OP = 'UPDATE' THEN
        IF OLD.vigente_desde NOT IN (v_inicio, v_prox_inicio) THEN
            RAISE EXCEPTION 'La UMA de ciclos anteriores (vigente desde %) es inmutable', OLD.vigente_desde;
        END IF;
        IF NEW.mercado_id <> OLD.mercado_id OR NEW.vigente_desde <> OLD.vigente_desde THEN
            RAISE EXCEPTION 'mercado_id y vigente_desde de la UMA no se modifican';
        END IF;
    END IF;

    NEW.registrado_por := app_usuario();
    NEW.registrado_en := now();
    RETURN NEW;
END $$;


ALTER FUNCTION gesta.trg_uma_mercado_ventana() OWNER TO gesta_owner;

--
-- TOC entry 909 (class 1255 OID 20219)
-- Name: trg_usuario_rol_valida(); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.trg_usuario_rol_valida() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $$
DECLARE v_req boolean;
BEGIN
    SELECT requiere_alcance INTO v_req FROM rol WHERE id = NEW.rol_id;
    IF v_req AND num_nonnulls(NEW.municipio_id, NEW.mercado_id) <> 1 THEN
        RAISE EXCEPTION 'Este rol exige alcance: indique municipio_id O mercado_id';
    END IF;
    IF NOT v_req AND num_nonnulls(NEW.municipio_id, NEW.mercado_id) <> 0 THEN
        RAISE EXCEPTION 'Este rol no admite alcance por municipio/mercado (su alcance es por persona)';
    END IF;
    RETURN NEW;
END $$;


ALTER FUNCTION gesta.trg_usuario_rol_valida() OWNER TO gesta_owner;

--
-- TOC entry 1079 (class 1255 OID 41087)
-- Name: trg_zona_mercado_geometria(); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.trg_zona_mercado_geometria() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $$
DECLARE
    v_geom_merc public.geometry;
    v_tol numeric;
    v_otra_zona text;
    v_local_fuera text;
BEGIN
    SELECT m.geom_limite, m.tolerancia_traslape_m2
      INTO v_geom_merc, v_tol
      FROM gesta.mercado m
     WHERE m.id = NEW.mercado_id;

    IF v_geom_merc IS NULL THEN
        RAISE EXCEPTION 'CU-04: El mercado % debe tener definido su polígono límite (geom_limite) antes de registrar o editar zonas', NEW.mercado_id;
    END IF;

    IF NEW.geom IS NOT NULL THEN
        NEW.geom := public.ST_Force2D(
            CASE WHEN public.ST_SRID(NEW.geom) = 0 THEN public.ST_SetSRID(NEW.geom, 4326)
                 WHEN public.ST_SRID(NEW.geom) <> 4326 THEN public.ST_Transform(NEW.geom, 4326)
                 ELSE NEW.geom END
        );
        IF NOT public.ST_IsValid(NEW.geom) THEN
            RAISE EXCEPTION 'CU-04: Polígono inválido en la zona %: %', NEW.nombre, public.ST_IsValidReason(NEW.geom);
        END IF;
        IF NOT public.ST_Covers(v_geom_merc, NEW.geom) THEN
            RAISE EXCEPTION 'CU-04: El polígono de la zona % debe estar completamente contenido dentro del límite del mercado %', NEW.nombre, NEW.mercado_id;
        END IF;

        PERFORM pg_advisory_xact_lock(hashtextextended('zona_geom:' || NEW.mercado_id::text, 0));
        SELECT z.nombre INTO v_otra_zona
          FROM gesta.zona_mercado z
         WHERE z.mercado_id = NEW.mercado_id
           AND z.id IS DISTINCT FROM NEW.id
           AND z.geom IS NOT NULL
           AND z.geom && NEW.geom
           AND public.ST_Intersects(z.geom, NEW.geom)
           AND public.ST_Area(public.ST_CollectionExtract(public.ST_Intersection(z.geom, NEW.geom), 3)::public.geography) > COALESCE(v_tol, 0.25)
         LIMIT 1;
        IF v_otra_zona IS NOT NULL THEN
            RAISE EXCEPTION 'CU-04: El polígono de la zona % se traslapa con la zona % del mismo mercado', NEW.nombre, v_otra_zona;
        END IF;
    END IF;

    IF TG_OP = 'UPDATE' AND (NEW.geom IS DISTINCT FROM OLD.geom OR NEW.mercado_id IS DISTINCT FROM OLD.mercado_id) THEN
        IF NEW.mercado_id IS DISTINCT FROM OLD.mercado_id
           AND EXISTS (SELECT 1 FROM gesta.local_comercial lc WHERE lc.zona_id = NEW.id) THEN
            RAISE EXCEPTION 'CU-04: No se puede cambiar de mercado una zona que ya tiene locales asignados';
        END IF;
        IF NEW.geom IS NULL AND EXISTS (
            SELECT 1 FROM gesta.local_comercial lc
             WHERE lc.zona_id = NEW.id AND lc.estatus <> 'BAJA' AND lc.geom IS NOT NULL
        ) THEN
            RAISE EXCEPTION 'CU-04: No se puede eliminar la geometría de la zona % porque tiene locales georreferenciados asignados', NEW.nombre;
        END IF;
        IF NEW.geom IS NOT NULL THEN
            SELECT lc.numero_local INTO v_local_fuera
              FROM gesta.local_comercial lc
             WHERE lc.zona_id = NEW.id
               AND lc.estatus <> 'BAJA'
               AND lc.geom IS NOT NULL
               AND NOT public.ST_Covers(NEW.geom, lc.geom)
             LIMIT 1;
            IF v_local_fuera IS NOT NULL THEN
                RAISE EXCEPTION 'CU-04: La nueva geometría de la zona % deja fuera al local comercial activo %', NEW.nombre, v_local_fuera;
            END IF;
        END IF;
    END IF;

    RETURN NEW;
END $$;


ALTER FUNCTION gesta.trg_zona_mercado_geometria() OWNER TO gesta_owner;

--
-- TOC entry 791 (class 1255 OID 41089)
-- Name: trg_zona_restringida_valida(); Type: FUNCTION; Schema: gesta; Owner: gesta_owner
--

CREATE FUNCTION gesta.trg_zona_restringida_valida() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gesta', 'public'
    AS $$
DECLARE
    v_local_conflicto text;
BEGIN
    NEW.geom := public.ST_Force2D(
        CASE WHEN public.ST_SRID(NEW.geom) = 0 THEN public.ST_SetSRID(NEW.geom, 4326)
             WHEN public.ST_SRID(NEW.geom) <> 4326 THEN public.ST_Transform(NEW.geom, 4326)
             ELSE NEW.geom END
    );
    IF NOT public.ST_IsValid(NEW.geom) THEN
        RAISE EXCEPTION 'Polígono inválido en zona restringida (%): %', NEW.nombre, public.ST_IsValidReason(NEW.geom);
    END IF;

    IF current_setting('gesta.permitir_conflicto_zona_rest', true) IS DISTINCT FROM '1' THEN
        IF NEW.tipo = 'PRIMER_CUADRO' THEN
            SELECT lc.numero_local INTO v_local_conflicto
              FROM gesta.local_comercial lc
              JOIN gesta.mercado m ON m.id = lc.mercado_id
             WHERE m.municipio_id = NEW.municipio_id
               AND lc.estatus <> 'BAJA'
               AND lc.tipo_espacio = 'FIJO'
               AND lc.geom IS NOT NULL
               AND public.ST_Intersects(NEW.geom, lc.geom)
             LIMIT 1;
            IF v_local_conflicto IS NOT NULL THEN
                RAISE EXCEPTION 'RN-PAD-04: La zona restringida PRIMER_CUADRO intersecta con el local comercial FIJO activo %', v_local_conflicto;
            END IF;
        ELSE
            SELECT lc.numero_local INTO v_local_conflicto
              FROM gesta.local_comercial lc
              JOIN gesta.mercado m ON m.id = lc.mercado_id
             WHERE m.municipio_id = NEW.municipio_id
               AND lc.estatus <> 'BAJA'
               AND lc.geom IS NOT NULL
               AND public.ST_DWithin(NEW.geom, lc.geom, 0.002)
               AND public.ST_DWithin(NEW.geom::public.geography, lc.geom::public.geography, 100)
             LIMIT 1;
            IF v_local_conflicto IS NOT NULL THEN
                RAISE EXCEPTION 'RN-PAD-03: La zona restringida (%) se encuentra a menos de 100 m del local comercial activo %', NEW.tipo, v_local_conflicto;
            END IF;
        END IF;
    END IF;

    RETURN NEW;
END $$;


ALTER FUNCTION gesta.trg_zona_restringida_valida() OWNER TO gesta_owner;

