    persona_destino_id uuid NOT NULL,
    tipo_tramite gesta.tipo_tramite DEFAULT 'FORMAL'::gesta.tipo_tramite NOT NULL,
    fecha_solicitud date,
    fecha_notificacion date,
    fecha_efectiva date,
    numero_expediente character varying(50),
    dictamen gesta.resultado_dictamen DEFAULT 'PENDIENTE'::gesta.resultado_dictamen NOT NULL,
