    CONSTRAINT ck_traspaso_aprobado_expediente CHECK ((((dictamen <> 'APROBADO'::gesta.resultado_dictamen) AND (NOT regularizado)) OR ((tipo_tramite = 'FORMAL'::gesta.tipo_tramite) AND (dictamen = 'APROBADO'::gesta.resultado_dictamen) AND (numero_expediente IS NOT NULL) AND (length(btrim((numero_expediente)::text)) > 0) AND (fecha_dictamen IS NOT NULL)))),
    CONSTRAINT ck_traspaso_dictamen CHECK ((((tipo_tramite = 'INFORMAL_NOTIFICADO'::gesta.tipo_tramite) AND (dictamen = 'NO_APLICA'::gesta.resultado_dictamen)) OR ((tipo_tramite = 'FORMAL'::gesta.tipo_tramite) AND (dictamen <> 'NO_APLICA'::gesta.resultado_dictamen)))),
    CONSTRAINT ck_traspaso_personas CHECK ((persona_origen_id <> persona_destino_id)),
    CONSTRAINT ck_traspaso_regularizado CHECK (((NOT regularizado) OR (concesion_destino_id IS NOT NULL)))
);

