--
-- TOC entry 283 (class 1259 OID 32832)
-- Name: v_saldo_favor; Type: VIEW; Schema: gesta; Owner: gesta_owner
--

CREATE VIEW gesta.v_saldo_favor WITH (security_invoker='true') AS
 WITH concesion_actual AS (
         SELECT DISTINCT ON (c.local_id) c.local_id,
            c.id AS concesion_id,
            c.titular_persona_id,
            c.fecha_inicio
           FROM gesta.concesion c
          WHERE (c.estado = ANY (ARRAY['VIGENTE'::gesta.estado_concesion, 'SUSPENDIDA'::gesta.estado_concesion]))
          ORDER BY c.local_id, (c.estado = 'VIGENTE'::gesta.estado_concesion) DESC, c.fecha_inicio DESC
        ), det_efectivo AS (
         SELECT p_1.local_id,
            pd.pago_id,
            pd.cargo_id,
                CASE
                    WHEN (cg.estado = 'CANCELADO'::gesta.estado_cargo) THEN (0)::numeric
                    ELSE GREATEST(LEAST(pd.monto_aplicado, (cg.monto_total - COALESCE(sum(pd.monto_aplicado) OVER (PARTITION BY p_1.local_id, pd.cargo_id ORDER BY p_1.fecha_pago, pd.pago_id ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING), (0)::numeric))), (0)::numeric)
                END AS aplicado_efectivo
           FROM ((gesta.pago_detalle pd
             JOIN gesta.cargo cg ON ((cg.id = pd.cargo_id)))
             JOIN gesta.pago p_1 ON ((p_1.id = pd.pago_id)))
          WHERE (p_1.estado = 'VIGENTE'::gesta.estado_pago)
        )
 SELECT p.local_id,
    sum((p.monto - COALESCE(d.aplicado, (0)::numeric))) AS saldo_favor,
    COALESCE(p.persona_pagador_id, ca.titular_persona_id) AS titular_persona_id
   FROM ((gesta.pago p
     LEFT JOIN ( SELECT det_efectivo.local_id,
            det_efectivo.pago_id,
            sum(det_efectivo.aplicado_efectivo) AS aplicado
           FROM det_efectivo
          GROUP BY det_efectivo.local_id, det_efectivo.pago_id) d ON (((d.local_id = p.local_id) AND (d.pago_id = p.id))))
     LEFT JOIN concesion_actual ca ON (((ca.local_id = p.local_id) AND (gesta.fn_fecha_local(p.mercado_id, p.fecha_pago) >= ca.fecha_inicio))))
  WHERE (p.estado = 'VIGENTE'::gesta.estado_pago)
  GROUP BY p.local_id, COALESCE(p.persona_pagador_id, ca.titular_persona_id)
 HAVING (sum((p.monto - COALESCE(d.aplicado, (0)::numeric))) > (0)::numeric);


ALTER VIEW gesta.v_saldo_favor OWNER TO gesta_owner;

--
-- TOC entry 272 (class 1259 OID 21107)
-- Name: v_adeudos; Type: VIEW; Schema: gesta; Owner: gesta_owner
--

CREATE VIEW gesta.v_adeudos WITH (security_invoker='true') AS
 WITH concesion_actual AS (
         SELECT DISTINCT ON (c.local_id) c.local_id,
            c.id AS concesion_id,
            c.titular_persona_id,
            c.estado,
            c.fecha_inicio
           FROM gesta.concesion c
          WHERE (c.estado = ANY (ARRAY['VIGENTE'::gesta.estado_concesion, 'SUSPENDIDA'::gesta.estado_concesion]))
          ORDER BY c.local_id, (c.estado = 'VIGENTE'::gesta.estado_concesion) DESC, c.fecha_inicio DESC
        ), cargos_agrupados AS (
         SELECT lc.id AS local_id,
            lc.mercado_id,
            lc.numero_local,
            COALESCE(c.id, ca_act.concesion_id) AS concesion_id,
            COALESCE(c.titular_persona_id, ca_act.titular_persona_id) AS titular_persona_id,
            ca_act.titular_persona_id AS titular_actual_id,
            (((COALESCE(c.estado, ca_act.estado) = 'VIGENTE'::gesta.estado_concesion) OR (COALESCE(c.id, ca_act.concesion_id) IS NULL)) AND (row_number() OVER (PARTITION BY lc.id, COALESCE(c.titular_persona_id, ca_act.titular_persona_id) ORDER BY (COALESCE(c.estado, ca_act.estado) = 'VIGENTE'::gesta.estado_concesion) DESC, (min(cg.periodo_inicio))) = 1)) AS aplica_saldo_favor,
            count(*) AS cargos_vencidos,
            sum((cg.monto_total - cg.monto_pagado)) AS saldo_adeudado,
            min(cg.periodo_inicio) AS adeudo_desde
           FROM (((((gesta.cargo cg
             JOIN gesta.local_comercial lc ON ((lc.id = cg.local_id)))
             JOIN gesta.mercado m ON ((m.id = lc.mercado_id)))
             LEFT JOIN gesta.concesion c ON ((c.id = cg.concesion_id)))
             LEFT JOIN concesion_actual ca_act ON ((ca_act.local_id = lc.id)))
             LEFT JOIN LATERAL ( SELECT r.dias_gracia
                   FROM gesta.regla_mora r
                  WHERE (r.activo AND (r.municipio_id = m.municipio_id) AND ((r.mercado_id IS NULL) OR (r.mercado_id = lc.mercado_id)) AND (gesta.fn_hoy_local(lc.mercado_id) >= r.vigente_desde) AND (gesta.fn_hoy_local(lc.mercado_id) <= COALESCE(r.vigente_hasta, 'infinity'::date)))
                  ORDER BY (r.mercado_id IS NOT NULL) DESC, r.vigente_desde DESC, r.id DESC
                 LIMIT 1) rm ON (true))
          WHERE ((cg.estado = ANY (ARRAY['PENDIENTE'::gesta.estado_cargo, 'PARCIAL'::gesta.estado_cargo])) AND ((cg.concepto = ANY (ARRAY['RECARGO'::gesta.concepto_cargo, 'PENALIZACION'::gesta.concepto_cargo, 'MULTA'::gesta.concepto_cargo])) OR ((cg.periodicidad = 'MENSUAL'::gesta.periodicidad) AND ((cg.periodo_inicio + GREATEST((COALESCE((rm.dias_gracia)::integer, 15) - 1), 0)) < gesta.fn_hoy_local(lc.mercado_id))) OR (cg.periodo_fin < gesta.fn_hoy_local(lc.mercado_id))))
          GROUP BY lc.id, lc.mercado_id, lc.numero_local, COALESCE(c.id, ca_act.concesion_id), COALESCE(c.titular_persona_id, ca_act.titular_persona_id), ca_act.titular_persona_id, COALESCE(c.estado, ca_act.estado)
        )
 SELECT ca.local_id,
    ca.mercado_id,
    ca.numero_local,
    ca.titular_persona_id,
    ca.cargos_vencidos,
    ca.saldo_adeudado,
    ca.adeudo_desde,
    ca.titular_persona_id AS deudor_identificado,
    (
        CASE
            WHEN ca.aplica_saldo_favor THEN COALESCE(sfc.saldo_favor, (0)::numeric)
            ELSE (0)::numeric
        END)::numeric(12,2) AS saldo_favor_local,
    (GREATEST((ca.saldo_adeudado -
        CASE
            WHEN ca.aplica_saldo_favor THEN COALESCE(sfc.saldo_favor, (0)::numeric)
            ELSE (0)::numeric
        END), (0)::numeric))::numeric(12,2) AS saldo_neto_exigible,
    (NOT (ca.titular_persona_id IS DISTINCT FROM ca.titular_actual_id)) AS es_titular_principal
   FROM (cargos_agrupados ca
     LEFT JOIN gesta.v_saldo_favor sfc ON (((sfc.local_id = ca.local_id) AND (NOT (sfc.titular_persona_id IS DISTINCT FROM ca.titular_persona_id)))));


ALTER VIEW gesta.v_adeudos OWNER TO gesta_owner;

