--
-- TOC entry 273 (class 1259 OID 21112)
-- Name: v_alertas_padron; Type: VIEW; Schema: gesta; Owner: gesta_owner
--

CREATE VIEW gesta.v_alertas_padron WITH (security_invoker='true') AS
 SELECT 'GIRO_NO_AUTORIZADO'::text AS alerta,
    lc.mercado_id,
    lc.id AS local_id,
    ((('Autorizado: '::text || (ga.nombre)::text) || ' / Observado: '::text) || (go_.nombre)::text) AS detalle
   FROM (((gesta.local_comercial lc
     JOIN gesta.concesion c ON (((c.local_id = lc.id) AND (c.estado = 'VIGENTE'::gesta.estado_concesion))))
     JOIN gesta.giro_comercial ga ON ((ga.id = c.giro_id)))
     JOIN gesta.giro_comercial go_ ON ((go_.id = lc.giro_observado_id)))
  WHERE ((lc.giro_observado_id <> c.giro_id) AND (lc.estatus <> 'BAJA'::gesta.estatus_local))
UNION ALL
 SELECT 'TRASPASO_NO_FORMALIZADO'::text AS alerta,
    lc.mercado_id,
    t.local_id,
    ('Traspaso informal notificado el '::text || COALESCE((t.fecha_notificacion)::text, 's/f'::text)) AS detalle
   FROM (gesta.traspaso t
     JOIN gesta.local_comercial lc ON ((lc.id = t.local_id)))
  WHERE ((t.tipo_tramite = 'INFORMAL_NOTIFICADO'::gesta.tipo_tramite) AND (NOT t.regularizado) AND (lc.estatus <> 'BAJA'::gesta.estatus_local))
UNION ALL
 SELECT 'OCUPANTE_DISTINTO_A_TITULAR'::text AS alerta,
    lc.mercado_id,
    lc.id AS local_id,
    (((('Ocupante real ('::text || c.ocupante_persona_id) || ') distinto al titular de la concesión ('::text) || c.titular_persona_id) || ')'::text) AS detalle
   FROM (gesta.concesion c
     JOIN gesta.local_comercial lc ON ((lc.id = c.local_id)))
  WHERE ((c.estado = 'VIGENTE'::gesta.estado_concesion) AND (c.ocupante_persona_id IS NOT NULL) AND (c.ocupante_persona_id <> c.titular_persona_id) AND (lc.estatus <> 'BAJA'::gesta.estatus_local) AND (NOT (EXISTS ( SELECT 1
           FROM gesta.concesion_suplente cs
          WHERE ((cs.concesion_id = c.id) AND (cs.persona_id = c.ocupante_persona_id))))))
UNION ALL
 SELECT 'CONCESION_SIN_EXPEDIENTE'::text AS alerta,
    lc.mercado_id,
    lc.id AS local_id,
    'Concesión vigente sin expediente formal regularizado (RN-04 / CU-12 2a)'::text AS detalle
   FROM (gesta.concesion c
     JOIN gesta.local_comercial lc ON ((lc.id = c.local_id)))
  WHERE ((c.estado = 'VIGENTE'::gesta.estado_concesion) AND (NOT c.es_formal) AND (NOT c.es_temporal_feria) AND (lc.estatus <> 'BAJA'::gesta.estatus_local))
UNION ALL
 SELECT 'TITULAR_CON_VARIOS_LOCALES'::text AS alerta,
    lc.mercado_id,
    lc.id AS local_id,
    (('Titular con múltiples concesiones activas/suspendidas en el padrón municipal ('::text || c.titular_persona_id) || ')'::text) AS detalle
   FROM (gesta.concesion c
     JOIN gesta.local_comercial lc ON ((lc.id = c.local_id)))
  WHERE ((NOT c.es_temporal_feria) AND (c.estado = ANY (gesta.fn_estados_concesion_proceso('UNICIDAD_PADRON'::text))) AND (EXISTS ( SELECT 1
           FROM gesta.concesion c2
          WHERE ((c2.municipio_id = c.municipio_id) AND (c2.titular_persona_id = c.titular_persona_id) AND (c2.id <> c.id) AND (NOT c2.es_temporal_feria) AND (c2.estado = ANY (gesta.fn_estados_concesion_proceso('UNICIDAD_PADRON'::text)))))))
UNION ALL
 SELECT 'DISCREPANCIA_CURP_RFC'::text AS alerta,
    lc.mercado_id,
    lc.id AS local_id,
    ((((('Discrepancia en primeros 10 caracteres entre CURP ('::text || (p.curp)::text) || ') y RFC ('::text) || (p.rfc)::text) || ') del titular '::text) || p.id) AS detalle
   FROM ((gesta.concesion c
     JOIN gesta.local_comercial lc ON ((lc.id = c.local_id)))
     JOIN gesta.persona p ON ((p.id = c.titular_persona_id)))
  WHERE ((c.estado = ANY (gesta.fn_estados_concesion_proceso('UNICIDAD_PADRON'::text))) AND (lc.estatus <> 'BAJA'::gesta.estatus_local) AND (p.tipo_persona = 'FISICA'::gesta.tipo_persona) AND (p.curp IS NOT NULL) AND (p.rfc IS NOT NULL) AND ("left"((p.curp)::text, 10) <> "left"((p.rfc)::text, 10)))
UNION ALL
 SELECT 'POSIBLE_HOMONIMIA_TITULAR'::text AS alerta,
    lc.mercado_id,
    lc.id AS local_id,
    ((('Posible duplicidad de persona física por raíz de 10 caracteres y nombre ('::text || COALESCE("left"((p.curp)::text, 10), "left"((p.rfc)::text, 10))) || ') con titular '::text) || p2.id) AS detalle
   FROM ((((gesta.concesion c
     JOIN gesta.local_comercial lc ON ((lc.id = c.local_id)))
     JOIN gesta.persona p ON ((p.id = c.titular_persona_id)))
     JOIN gesta.concesion c2 ON (((c2.municipio_id = c.municipio_id) AND (c2.id <> c.id) AND (NOT c2.es_temporal_feria) AND (c2.estado = ANY (gesta.fn_estados_concesion_proceso('UNICIDAD_PADRON'::text))))))
     JOIN gesta.persona p2 ON (((p2.id = c2.titular_persona_id) AND (p2.id <> p.id))))
  WHERE ((NOT c.es_temporal_feria) AND (c.estado = ANY (gesta.fn_estados_concesion_proceso('UNICIDAD_PADRON'::text))) AND (p.tipo_persona = 'FISICA'::gesta.tipo_persona) AND (p2.tipo_persona = 'FISICA'::gesta.tipo_persona) AND (COALESCE("left"((p.curp)::text, 10), "left"((p.rfc)::text, 10)) IS NOT NULL) AND (COALESCE("left"((p.curp)::text, 10), "left"((p.rfc)::text, 10)) = COALESCE("left"((p2.curp)::text, 10), "left"((p2.rfc)::text, 10))) AND (upper(btrim((p.nombres)::text)) = upper(btrim((p2.nombres)::text))) AND (upper(btrim((p.apellido_paterno)::text)) = upper(btrim((p2.apellido_paterno)::text))))
UNION ALL
 SELECT 'ABANDONO_10_DIAS_RESCISION'::text AS alerta,
    lc.mercado_id,
    lc.id AS local_id,
    'Causal de rescisión (Art. 20 Fracc. XXVIII): >= 3 visitas georreferenciadas con local cerrado y > 10 días continuos sin actividad ni pagos'::text AS detalle
   FROM gesta.local_comercial lc
  WHERE ((lc.estatus = 'OCUPADO'::gesta.estatus_local) AND (EXISTS ( SELECT 1
           FROM gesta.asistencia_local a
          WHERE ((a.local_id = lc.id) AND ((a.tipo_incidencia)::text = 'AUSENTE_CERRADO'::text) AND (a.ubicacion IS NOT NULL) AND (NOT (EXISTS ( SELECT 1
                   FROM gesta.asistencia_local ap
                  WHERE ((ap.local_id = lc.id) AND ((ap.tipo_incidencia)::text = 'PRESENTE'::text) AND (ap.fecha > a.fecha))))) AND (NOT (EXISTS ( SELECT 1
                   FROM gesta.pago pg
                  WHERE ((pg.local_id = lc.id) AND (pg.estado = 'VIGENTE'::gesta.estado_pago) AND (gesta.fn_fecha_local(lc.mercado_id, pg.fecha_pago) > a.fecha))))))
         HAVING ((count(*) >= 3) AND ((max(a.fecha) - min(a.fecha)) >= 10)))))
UNION ALL
 SELECT 'MOROSIDAD_MAYOR_3_MESES'::text AS alerta,
    va.mercado_id,
    va.local_id,
    (((('Causal de rescisión (Art. 20 Fracc. XXXV): adeudo vencido desde '::text || va.adeudo_desde) || ' ($'::text) || va.saldo_neto_exigible) || ')'::text) AS detalle
   FROM gesta.v_adeudos va
  WHERE (va.es_titular_principal AND (va.saldo_neto_exigible > (0)::numeric) AND (va.adeudo_desde <= ((gesta.fn_hoy_local(va.mercado_id) - '3 mons'::interval))::date))
UNION ALL
 SELECT 'LOCAL_OCUPADO_SIN_CONCESION'::text AS alerta,
    lc.mercado_id,
    lc.id AS local_id,
    'Sin concesión vigente'::text AS detalle
   FROM gesta.local_comercial lc
  WHERE ((lc.estatus = 'OCUPADO'::gesta.estatus_local) AND (NOT (EXISTS ( SELECT 1
           FROM gesta.concesion c
          WHERE ((c.local_id = lc.id) AND (c.estado = 'VIGENTE'::gesta.estado_concesion))))))
UNION ALL
 SELECT 'SIN_POLIGONO'::text AS alerta,
    lc.mercado_id,
    lc.id AS local_id,
    'Local sin georreferenciar'::text AS detalle
   FROM gesta.local_comercial lc
  WHERE ((lc.geom IS NULL) AND (lc.estatus <> 'BAJA'::gesta.estatus_local))
UNION ALL
 SELECT 'PAGO_REQUIERE_REVISION'::text AS alerta,
    p.mercado_id,
    p.local_id,
    ((('Folio '::text || (p.folio)::text) || ': '::text) || p.motivo_revision) AS detalle
   FROM gesta.pago p
  WHERE (p.requiere_revision AND (p.estado = 'VIGENTE'::gesta.estado_pago))
UNION ALL
 SELECT 'FIJO_EN_PRIMER_CUADRO'::text AS alerta,
    lc.mercado_id,
    lc.id AS local_id,
    ('Comercio fijo fuera de recinto en zona: '::text || (COALESCE(z.nombre, 'Primer Cuadro'::character varying))::text) AS detalle
   FROM ((gesta.local_comercial lc
     JOIN gesta.mercado m ON ((m.id = lc.mercado_id)))
     JOIN gesta.zona_restringida z ON (((z.municipio_id = m.municipio_id) AND (z.tipo = 'PRIMER_CUADRO'::gesta.tipo_zona_rest) AND public.st_intersects(z.geom, lc.geom))))
  WHERE ((lc.tipo_espacio = 'FIJO'::gesta.tipo_espacio) AND (lc.estatus <> 'BAJA'::gesta.estatus_local) AND ((m.geom_limite IS NOT NULL) AND (NOT public.st_covers(m.geom_limite, lc.geom))))
UNION ALL
 SELECT 'CERCA_DE_INFRAESTRUCTURA_PROTEGIDA'::text AS alerta,
    lc.mercado_id,
    lc.id AS local_id,
    (('A menos de 100 m de '::text || (z.tipo)::text) || COALESCE(((' ('::text || (z.nombre)::text) || ')'::text), ''::text)) AS detalle
   FROM ((gesta.local_comercial lc
     JOIN gesta.mercado m ON ((m.id = lc.mercado_id)))
     JOIN gesta.zona_restringida z ON (((z.municipio_id = m.municipio_id) AND (z.tipo <> 'PRIMER_CUADRO'::gesta.tipo_zona_rest) AND public.st_dwithin(z.geom, lc.geom, (0.002)::double precision) AND public.st_dwithin((z.geom)::public.geography, (lc.geom)::public.geography, (100)::double precision))))
  WHERE ((lc.estatus <> 'BAJA'::gesta.estatus_local) AND (lc.tipo_espacio = ANY (ARRAY['VIA_PUBLICA'::gesta.tipo_espacio, 'AMBULANTE'::gesta.tipo_espacio, 'SEMIFIJO'::gesta.tipo_espacio])) AND (NOT ((m.geom_limite IS NOT NULL) AND public.st_covers(m.geom_limite, lc.geom))));


