-- Name: v_alertas_cobro; Type: VIEW; Schema: gesta; Owner: gesta_owner
--

CREATE VIEW gesta.v_alertas_cobro WITH (security_invoker='true') AS
 WITH x AS (
         SELECT lc.id AS local_id,
            lc.mercado_id,
            lc.estatus,
            q.tarifa_id,
            q.area_m2,
            q.valor,
            q.unidad,
            q.uma_aplicada,
            q.metodo,
            q.periodicidad,
            q.monto,
            q.incluir_en_lote,
            q.metros_lineales
           FROM (gesta.local_comercial lc
             LEFT JOIN LATERAL gesta.fn_calcular_cuota(lc.id, gesta.fn_hoy_local(lc.mercado_id)) q(tarifa_id, area_m2, valor, unidad, uma_aplicada, metodo, periodicidad, monto, incluir_en_lote, metros_lineales) ON (true))
          WHERE (lc.estatus <> 'BAJA'::gesta.estatus_local)
        )
 SELECT 'LOCAL_SIN_AREA'::text AS alerta,
    x.mercado_id,
    x.local_id,
    'Tarifa por m² (o con excedente) sin área oficial ni calculada'::text AS detalle
   FROM x
  WHERE ((x.metodo = ANY (ARRAY['POR_M2'::gesta.metodo_calculo, 'CUOTA_BASE_MAS_EXCEDENTE'::gesta.metodo_calculo])) AND (x.area_m2 IS NULL))
UNION ALL
 SELECT 'LOCAL_SIN_METROS_LINEALES'::text AS alerta,
    x.mercado_id,
    x.local_id,
    'Tarifa por metro lineal sin metros lineales registrados'::text AS detalle
   FROM x
  WHERE ((x.metodo = 'POR_METRO_LINEAL'::gesta.metodo_calculo) AND (x.metros_lineales IS NULL))
UNION ALL
 SELECT 'LOCAL_SIN_TARIFA'::text AS alerta,
    x.mercado_id,
    x.local_id,
    'Ninguna tarifa aplicable a la fecha'::text AS detalle
   FROM x
  WHERE (x.tarifa_id IS NULL)
UNION ALL
 SELECT 'LOCAL_SIN_UMA'::text AS alerta,
    x.mercado_id,
    x.local_id,
    'Tarifa en UMA y el mercado no tiene UMA vigente'::text AS detalle
   FROM x
  WHERE ((x.unidad = 'UMA'::gesta.unidad_valor) AND (x.uma_aplicada IS NULL))
UNION ALL
 SELECT 'LOCAL_VACIO'::text AS alerta,
    x.mercado_id,
    x.local_id,
    ('Estatus '::text || (x.estatus)::text) AS detalle
   FROM x
  WHERE (x.estatus = ANY (ARRAY['DESOCUPADO'::gesta.estatus_local, 'ABANDONADO'::gesta.estatus_local, 'EN_LITIGIO'::gesta.estatus_local]))
UNION ALL
 SELECT v_alertas_padron.alerta,
    v_alertas_padron.mercado_id,
    v_alertas_padron.local_id,
    v_alertas_padron.detalle
   FROM gesta.v_alertas_padron
  WHERE (v_alertas_padron.alerta = ANY (ARRAY['LOCAL_OCUPADO_SIN_CONCESION'::text, 'SIN_POLIGONO'::text]));


