--
-- TOC entry 276 (class 1259 OID 21132)
-- Name: v_tarifas_ambiguas; Type: VIEW; Schema: gesta; Owner: gesta_owner
--

CREATE VIEW gesta.v_tarifas_ambiguas WITH (security_invoker='true') AS
 SELECT a.id AS tarifa_a,
    b.id AS tarifa_b,
    a.mercado_id,
    a.zona_id,
    a.tipo_espacio,
    a.giro_id,
    a.municipio_id
   FROM (gesta.tarifa a
     JOIN gesta.tarifa b ON (((a.id < b.id) AND a.activo AND b.activo AND (a.municipio_id = b.municipio_id) AND (NOT (a.mercado_id IS DISTINCT FROM b.mercado_id)) AND (NOT (a.zona_id IS DISTINCT FROM b.zona_id)) AND (NOT (a.tipo_espacio IS DISTINCT FROM b.tipo_espacio)) AND (NOT (a.giro_id IS DISTINCT FROM b.giro_id)) AND (daterange(a.vigente_desde, a.vigente_hasta, '[]'::text) && daterange(b.vigente_desde, b.vigente_hasta, '[]'::text)))));


ALTER VIEW gesta.v_tarifas_ambiguas OWNER TO gesta_owner;

--
-- TOC entry 275 (class 1259 OID 21127)
-- Name: v_tarifas_ensombrecidas; Type: VIEW; Schema: gesta; Owner: gesta_owner
--

CREATE VIEW gesta.v_tarifas_ensombrecidas WITH (security_invoker='true') AS
 SELECT p.mercado_id,
    p.municipio_id,
    p.id AS tarifa_ensombrecida,
    g.id AS tarifa_ganadora,
    ((
        CASE
            WHEN (p.giro_id IS NOT NULL) THEN 4
            ELSE 0
        END +
        CASE
            WHEN (p.zona_id IS NOT NULL) THEN 2
            ELSE 0
        END) +
        CASE
            WHEN (p.tipo_espacio IS NOT NULL) THEN 1
            ELSE 0
        END) AS puntaje_ensombrecida,
    (
        CASE
            WHEN (g.giro_id IS NOT NULL) THEN 4
            ELSE 0
        END +
        CASE
            WHEN (g.tipo_espacio IS NOT NULL) THEN 1
            ELSE 0
        END) AS puntaje_ganadora,
    GREATEST(p.vigente_desde, g.vigente_desde) AS traslape_desde,
    LEAST(COALESCE(p.vigente_hasta, 'infinity'::date), COALESCE(g.vigente_hasta, 'infinity'::date)) AS traslape_hasta
   FROM (gesta.tarifa p
     JOIN gesta.tarifa g ON ((g.activo AND p.activo AND (g.municipio_id = p.municipio_id) AND (g.mercado_id IS NULL) AND (p.mercado_id IS NOT NULL) AND ((g.tipo_espacio IS NULL) OR (p.tipo_espacio IS NULL) OR (g.tipo_espacio = p.tipo_espacio)) AND ((g.giro_id IS NULL) OR (p.giro_id IS NULL) OR (g.giro_id = p.giro_id)) AND (daterange(p.vigente_desde, p.vigente_hasta, '[]'::text) && daterange(g.vigente_desde, g.vigente_hasta, '[]'::text)))))
  WHERE ((
        CASE
            WHEN (g.giro_id IS NOT NULL) THEN 4
            ELSE 0
        END +
        CASE
            WHEN (g.tipo_espacio IS NOT NULL) THEN 1
            ELSE 0
        END) > ((
        CASE
            WHEN (p.giro_id IS NOT NULL) THEN 4
            ELSE 0
        END +
        CASE
            WHEN (p.zona_id IS NOT NULL) THEN 2
            ELSE 0
        END) +
        CASE
            WHEN (p.tipo_espacio IS NOT NULL) THEN 1
            ELSE 0
        END));


ALTER VIEW gesta.v_tarifas_ensombrecidas OWNER TO gesta_owner;

--
-- TOC entry 280 (class 1259 OID 21163)
-- Name: v_alertas_configuracion; Type: VIEW; Schema: gesta; Owner: gesta_owner
--

CREATE VIEW gesta.v_alertas_configuracion WITH (security_invoker='true') AS
 WITH m AS (
         SELECT mc.id AS mercado_id,
            mc.municipio_id,
            gesta.fn_hoy_local(mc.id) AS hoy
           FROM gesta.mercado mc
          WHERE (mc.activo AND (gesta.app_es_sistema() OR gesta.app_es_admin(mc.id) OR gesta.app_tiene_rol('TESORERIA'::text, mc.id)))
        ), usa_uma AS (
         SELECT m.mercado_id
           FROM m
          WHERE (EXISTS ( SELECT 1
                   FROM gesta.tarifa t
                  WHERE (t.activo AND (t.unidad_valor = 'UMA'::gesta.unidad_valor) AND (t.municipio_id = m.municipio_id) AND ((t.mercado_id IS NULL) OR (t.mercado_id = m.mercado_id)) AND ((m.hoy >= t.vigente_desde) AND (m.hoy <= COALESCE(t.vigente_hasta, 'infinity'::date))))))
        )
 SELECT 'UMA_PROXIMA_A_CAMBIAR'::text AS alerta,
    'INFO'::text AS severidad,
    m.mercado_id,
    m.municipio_id,
    'La UMA nueva rige desde el 1 de febrero: el administrador debe capturarla del 1 al 15 de febrero'::text AS detalle
   FROM m
  WHERE ((EXTRACT(month FROM m.hoy) = (1)::numeric) AND (EXTRACT(day FROM m.hoy) >= (15)::numeric))
UNION ALL
 SELECT 'FALTA_UMA'::text AS alerta,
        CASE
            WHEN ((m.hoy >= make_date((EXTRACT(year FROM m.hoy))::integer, 2, 1)) AND (m.hoy <= make_date((EXTRACT(year FROM m.hoy))::integer, 2, 15))) THEN 'ADVERTENCIA'::text
            ELSE 'CRITICA'::text
        END AS severidad,
    m.mercado_id,
    m.municipio_id,
    (('El mercado no tiene UMA vigente al '::text || m.hoy) || ': los cargos en UMA no se generan y los cobros quedan en revisión'::text) AS detalle
   FROM m
  WHERE ((m.mercado_id IN ( SELECT usa_uma.mercado_id
           FROM usa_uma)) AND (gesta.fn_valor_uma(m.hoy, m.mercado_id) IS NULL))
UNION ALL
 SELECT 'UMA_DIFIERE_OFICIAL'::text AS alerta,
    'ADVERTENCIA'::text AS severidad,
    m.mercado_id,
    m.municipio_id,
    (((((('UMA capturada '::text || um.valor_diario) || ' vs oficial '::text) || uo.valor_diario) || ' (vigente desde '::text) || um.vigente_desde) || ')'::text) AS detalle
   FROM ((m
     JOIN gesta.uma_mercado um ON (((um.mercado_id = m.mercado_id) AND (um.vigente_desde <= m.hoy) AND (m.hoy < ((um.vigente_desde + '1 year'::interval))::date))))
     JOIN gesta.uma_oficial uo ON ((uo.vigente_desde = um.vigente_desde)))
  WHERE (um.valor_diario <> uo.valor_diario)
UNION ALL
 SELECT 'FALTA_REGLA_MORA'::text AS alerta,
    'CRITICA'::text AS severidad,
    m.mercado_id,
    m.municipio_id,
    (('El mercado/municipio no tiene regla_mora activa y vigente al '::text || m.hoy) || ': fn_generar_recargos no podrá devengar recargos (RN-FIS-04)'::text) AS detalle
   FROM m
  WHERE (NOT (EXISTS ( SELECT 1
           FROM gesta.regla_mora rm
          WHERE (rm.activo AND (rm.municipio_id = m.municipio_id) AND ((rm.mercado_id IS NULL) OR (rm.mercado_id = m.mercado_id)) AND (m.hoy >= rm.vigente_desde) AND (m.hoy <= COALESCE(rm.vigente_hasta, 'infinity'::date))))))
UNION ALL
 SELECT 'CONCESIONES_VENCIDAS_SIN_CERRAR'::text AS alerta,
    'ADVERTENCIA'::text AS severidad,
    m.mercado_id,
    m.municipio_id,
    (x.n || ' concesión(es) VIGENTE/SUSPENDIDA con fecha_fin pasada: el job fn_vencer_concesiones no corrió'::text) AS detalle
   FROM (m
     JOIN LATERAL ( SELECT count(*) AS n
           FROM (gesta.concesion c
             JOIN gesta.local_comercial lc ON ((lc.id = c.local_id)))
          WHERE ((lc.mercado_id = m.mercado_id) AND (c.estado = ANY (ARRAY['VIGENTE'::gesta.estado_concesion, 'SUSPENDIDA'::gesta.estado_concesion])) AND (c.fecha_fin < m.hoy))) x ON ((x.n > 0)))
UNION ALL
 SELECT 'LOTE_MES_ANTERIOR_PENDIENTE'::text AS alerta,
    'ADVERTENCIA'::text AS severidad,
    m.mercado_id,
    m.municipio_id,
    (('No se generó el lote de cargos del mes anterior ('::text || (date_trunc('month'::text, ((m.hoy)::timestamp without time zone - '1 mon'::interval)))::date) || ')'::text) AS detalle
   FROM m
  WHERE ((EXISTS ( SELECT 1
           FROM (gesta.concesion c
             JOIN gesta.local_comercial lc ON ((lc.id = c.local_id)))
          WHERE ((lc.mercado_id = m.mercado_id) AND (c.fecha_inicio <= ((date_trunc('month'::text, (m.hoy)::timestamp without time zone))::date - 1)) AND (COALESCE(c.fecha_fin, 'infinity'::date) >= (date_trunc('month'::text, ((m.hoy)::timestamp without time zone - '1 mon'::interval)))::date)))) AND (NOT (EXISTS ( SELECT 1
           FROM gesta.lote_cargos l
          WHERE ((l.mercado_id = m.mercado_id) AND (l.periodo_inicio <= (date_trunc('month'::text, ((m.hoy)::timestamp without time zone - '1 mon'::interval)))::date) AND (l.periodo_fin >= ((date_trunc('month'::text, (m.hoy)::timestamp without time zone))::date - 1)))))))
UNION ALL
 SELECT 'RECARGOS_MES_PENDIENTES'::text AS alerta,
    'ADVERTENCIA'::text AS severidad,
    m.mercado_id,
    m.municipio_id,
    (x.n || ' recargo(s) mensual(es) vencido(s) (actuales o retroactivos) pendientes de generar: ejecutar fn_generar_recargos'::text) AS detalle
   FROM (m
     JOIN LATERAL ( SELECT count(*) AS n
           FROM (((gesta.cargo cg
             JOIN gesta.local_comercial lc ON ((lc.id = cg.local_id)))
             JOIN LATERAL ( SELECT r.porcentaje_recargo,
                    r.dias_gracia,
                    r.tope_maximo_pct
                   FROM gesta.regla_mora r
                  WHERE (r.activo AND (r.municipio_id = m.municipio_id) AND ((r.mercado_id IS NULL) OR (r.mercado_id = lc.mercado_id)) AND (m.hoy >= r.vigente_desde) AND (m.hoy <= COALESCE(r.vigente_hasta, 'infinity'::date)))
                  ORDER BY (r.mercado_id IS NOT NULL) DESC, r.vigente_desde DESC, r.id DESC
                 LIMIT 1) rm ON (true))
             JOIN LATERAL generate_series(date_trunc('month'::text, ((
                CASE
                    WHEN ((cg.periodicidad = 'MENSUAL'::gesta.periodicidad) AND (cg.concepto = ANY (ARRAY['DERECHO_PISO'::gesta.concepto_cargo, 'PENALIZACION'::gesta.concepto_cargo]))) THEN (cg.periodo_inicio + GREATEST(((rm.dias_gracia)::integer - 1), 0))
                    ELSE (cg.periodo_fin + (rm.dias_gracia)::integer)
                END + 1))::timestamp without time zone), date_trunc('month'::text, (m.hoy)::timestamp without time zone), '1 mon'::interval) gs(mes_mora) ON (true))
          WHERE ((lc.mercado_id = m.mercado_id) AND (cg.concepto = ANY (ARRAY['DERECHO_PISO'::gesta.concepto_cargo, 'PENALIZACION'::gesta.concepto_cargo])) AND (cg.estado = ANY (ARRAY['PENDIENTE'::gesta.estado_cargo, 'PARCIAL'::gesta.estado_cargo])) AND (
                CASE
                    WHEN ((cg.periodicidad = 'MENSUAL'::gesta.periodicidad) AND (cg.concepto = ANY (ARRAY['DERECHO_PISO'::gesta.concepto_cargo, 'PENALIZACION'::gesta.concepto_cargo]))) THEN (cg.periodo_inicio + GREATEST(((rm.dias_gracia)::integer - 1), 0))
                    ELSE (cg.periodo_fin + (rm.dias_gracia)::integer)
                END < m.hoy) AND (round((((cg.monto_total - cg.monto_pagado) * rm.porcentaje_recargo) / (100)::numeric), 2) > (0)::numeric) AND (COALESCE(( SELECT sum(rc0.monto_total) AS sum
                   FROM gesta.cargo rc0
                  WHERE ((rc0.cargo_origen_id = cg.id) AND (rc0.concepto = 'RECARGO'::gesta.concepto_cargo) AND (rc0.estado <> 'CANCELADO'::gesta.estado_cargo))), (0)::numeric) < round(((cg.monto_total * rm.tope_maximo_pct) / (100)::numeric), 2)) AND (NOT (EXISTS ( SELECT 1
                   FROM gesta.cargo rc
                  WHERE ((rc.cargo_origen_id = cg.id) AND (rc.concepto = 'RECARGO'::gesta.concepto_cargo) AND (rc.estado <> 'CANCELADO'::gesta.estado_cargo) AND (date_trunc('month'::text, (rc.periodo_inicio)::timestamp without time zone) = gs.mes_mora))))))) x ON ((x.n > 0)))
UNION ALL
 SELECT 'SALDOS_FAVOR_PENDIENTES_APLICAR'::text AS alerta,
    'ADVERTENCIA'::text AS severidad,
    m.mercado_id,
    m.municipio_id,
    (x.n || ' local(es) con saldo a favor y cargos abiertos pendientes de compensación FIFO'::text) AS detalle
   FROM (m
     JOIN LATERAL ( SELECT count(DISTINCT sf.local_id) AS n
           FROM ((gesta.v_saldo_favor sf
             JOIN gesta.local_comercial lc ON ((lc.id = sf.local_id)))
             JOIN gesta.cargo cg ON ((cg.local_id = sf.local_id)))
          WHERE ((lc.mercado_id = m.mercado_id) AND (cg.estado = ANY (ARRAY['PENDIENTE'::gesta.estado_cargo, 'PARCIAL'::gesta.estado_cargo])))) x ON ((x.n > 0)))
UNION ALL
 SELECT 'PAGOS_EN_REVISION_ANTIGUOS'::text AS alerta,
    'ADVERTENCIA'::text AS severidad,
    m.mercado_id,
    m.municipio_id,
    (x.n || ' pago(s) en revisión con más de 15 días: resolverlos'::text) AS detalle
   FROM (m
     JOIN LATERAL ( SELECT count(*) AS n
           FROM gesta.pago p
          WHERE ((p.mercado_id = m.mercado_id) AND p.requiere_revision AND (p.estado = 'VIGENTE'::gesta.estado_pago) AND (p.creado_en < (now() - '15 days'::interval)))) x ON ((x.n > 0)))
UNION ALL
 SELECT 'TARIFAS_AMBIGUAS'::text AS alerta,
    'ADVERTENCIA'::text AS severidad,
    m.mercado_id,
    m.municipio_id,
    (x.n || ' par(es) de tarifas con la misma especificidad y vigencias empalmadas'::text) AS detalle
   FROM (m
     JOIN LATERAL ( SELECT count(*) AS n
           FROM gesta.v_tarifas_ambiguas a
          WHERE ((a.municipio_id = m.municipio_id) AND ((a.mercado_id IS NULL) OR (a.mercado_id = m.mercado_id)))) x ON ((x.n > 0)))
UNION ALL
 SELECT 'TARIFAS_ENSOMBRECIDAS'::text AS alerta,
    'ADVERTENCIA'::text AS severidad,
    m.mercado_id,
    m.municipio_id,
    (x.n || ' tarifa(s) propia(s) del mercado pierden contra una tarifa municipal con más atributos (v_tarifas_ensombrecidas)'::text) AS detalle
   FROM (m
     JOIN LATERAL ( SELECT count(DISTINCT e.tarifa_ensombrecida) AS n
           FROM gesta.v_tarifas_ensombrecidas e
          WHERE (e.mercado_id = m.mercado_id)) x ON ((x.n > 0)));


