 SELECT lc.id AS local_id,
    lc.mercado_id,
    lc.numero_local,
    lc.tipo_espacio,
    COALESCE(lc.area_oficial_m2, lc.area_calculada_m2) AS area_m2,
    q.tarifa_id,
    q.metodo,
    q.valor,
    q.unidad,
    q.uma_aplicada,
    q.periodicidad,
    q.monto AS cuota_por_unidad
   FROM (gesta.local_comercial lc
     LEFT JOIN LATERAL gesta.fn_calcular_cuota(lc.id, gesta.fn_hoy_local(lc.mercado_id)) q(tarifa_id, area_m2, valor, unidad, uma_aplicada, metodo, periodicidad, monto, incluir_en_lote, metros_lineales) ON (true));


ALTER VIEW gesta.v_local_cuota_actual OWNER TO gesta_owner;

--
-- TOC entry 277 (class 1259 OID 21137)
-- Name: v_pagos_sin_corte; Type: VIEW; Schema: gesta; Owner: gesta_owner
--

CREATE VIEW gesta.v_pagos_sin_corte WITH (security_invoker='true') AS
 SELECT mercado_id,
    cobrador_id,
    gesta.fn_fecha_local(mercado_id, fecha_pago) AS fecha_local,
    count(*) AS pagos,
    sum(monto) AS monto
   FROM gesta.pago p
  WHERE ((corte_caja_id IS NULL) AND (estado = 'VIGENTE'::gesta.estado_pago) AND (forma_pago = 'EFECTIVO'::gesta.forma_pago))
  GROUP BY mercado_id, cobrador_id, (gesta.fn_fecha_local(mercado_id, fecha_pago));


ALTER VIEW gesta.v_pagos_sin_corte OWNER TO gesta_owner;

--
-- TOC entry 281 (class 1259 OID 21168)
-- Name: v_persona_publica; Type: VIEW; Schema: gesta; Owner: gesta_owner
--

CREATE VIEW gesta.v_persona_publica WITH (security_invoker='true') AS
 SELECT id,
    tipo_persona,
    nombres,
    apellido_paterno,
    apellido_materno,
    razon_social
   FROM gesta.persona p
  WHERE ((id = gesta.app_persona_actual()) OR gesta.app_persona_en_mi_mercado(id) OR gesta.app_persona_en_mi_alcance_operativo(id));


ALTER VIEW gesta.v_persona_publica OWNER TO gesta_owner;

