--
-- TOC entry 7298 (class 2618 OID 24691)
-- Name: v_conciliacion_depositos _RETURN; Type: RULE; Schema: gesta; Owner: gesta_owner
--

CREATE OR REPLACE VIEW gesta.v_conciliacion_depositos WITH (security_invoker='true') AS
 SELECT d.id AS deposito_id,
    d.mercado_id,
    d.fecha_deposito,
    d.monto_depositado,
    COALESCE(sum(p.monto) FILTER (WHERE (p.estado = 'VIGENTE'::gesta.estado_pago)), (0)::numeric) AS total_pagos_vinculados,
    (d.monto_depositado - COALESCE(sum(p.monto) FILTER (WHERE (p.estado = 'VIGENTE'::gesta.estado_pago)), (0)::numeric)) AS dif_vs_pagos,
    d.tarjeta_monto,
    d.diferencia AS dif_vs_tarjeta,
    d.justificacion_diferencia,
    ((d.tarjeta_monto IS NOT NULL) AND (d.diferencia = (0)::numeric) AND ((d.monto_depositado - COALESCE(sum(p.monto) FILTER (WHERE (p.estado = 'VIGENTE'::gesta.estado_pago)), (0)::numeric)) = (0)::numeric)) AS conciliado
   FROM (gesta.deposito_hacienda d
     LEFT JOIN gesta.pago p ON ((p.deposito_id = d.id)))
  GROUP BY d.id;


--
-- TOC entry 7300 (class 2618 OID 32924)
-- Name: v_cortes_caja_conciliados _RETURN; Type: RULE; Schema: gesta; Owner: gesta_owner
--

CREATE OR REPLACE VIEW gesta.v_cortes_caja_conciliados WITH (security_invoker='true') AS
 SELECT c.id AS corte_caja_id,
    c.mercado_id,
    c.cobrador_id,
    c.fecha_corte,
    c.secuencia,
    c.num_pagos AS num_pagos_original,
    c.monto_total AS monto_sistema_cierre,
    c.monto_declarado,
    c.diferencia AS diferencia_arqueo_ciego,
    (count(a.id))::integer AS pagos_cancelados_post_corte,
    (COALESCE(sum(a.monto_anulado), (0)::numeric))::numeric(12,2) AS monto_cancelado_post_corte,
    ((c.monto_total - COALESCE(sum(a.monto_anulado), (0)::numeric)))::numeric(12,2) AS monto_neto_vigente,
    ((c.monto_declarado - (c.monto_total - COALESCE(sum(a.monto_anulado), (0)::numeric))))::numeric(12,2) AS diferencia_neta_actual,
    c.recibido_por,
    c.liquidado_en
   FROM (gesta.corte_caja_diario c
     LEFT JOIN gesta.corte_caja_ajuste a ON ((a.corte_caja_id = c.id)))
  GROUP BY c.id;


