-- TOC entry 7398 (class 3256 OID 24649)
-- Name: auditoria p_auditoria_admin; Type: POLICY; Schema: gesta; Owner: gesta_owner
--

CREATE POLICY p_auditoria_admin ON gesta.auditoria FOR SELECT TO gesta_app USING ((((mercado_id IS NOT NULL) AND (gesta.app_es_admin(mercado_id) OR gesta.app_tiene_rol('TESORERIA'::text, mercado_id))) OR ((mercado_id IS NULL) AND (municipio_id IS NOT NULL) AND gesta.app_es_admin_municipio(municipio_id)) OR ((mercado_id IS NULL) AND (municipio_id IS NULL) AND (EXISTS ( SELECT 1
   FROM gesta.municipio mu
  WHERE gesta.app_es_admin_municipio(mu.id))))));


